      "path": "hindsight-integrations/coding-agents/src/dsh.ts",
      "content": "/**\n * DeepSeek Harness (`dsh`) entrypoint — a native Cordis plugin.\n *\n * dsh is plugin-first: its canonical extension surface is a set of typed lifecycle events, and its\n * Claude Code / Codex hook bridges are just translators onto that same surface. So this integration\n * binds the events directly instead of installing hook binaries — a bridge would cost the same\n * install (neither bridge ships in a default profile) while losing the transcript, the session id\n * and the awaited stop boundary.\n *\n *   agent/session-start  -> RuntimeCore.seedIfCold      (cold-check + background git/codebase seed)\n *   agent/pre-step       -> RuntimeCore.onPrompt        (recall) + the injection as a sourced message\n *   agent/turn-stopping  -> RuntimeCore.onSessionIdle   (write-back of the completed exchange)\n *   ctx.tools            -> the hindsight_* page suite, registered natively\n *\n * ONE dsh PROCESS SERVES MANY WORKSPACES. Unlike opencode/Kilo/Cline — one process, one project —\n * dsh's Web UI creates sessions in whatever directory the user picks, each with its own\n * `session.header.cwd`. Memory is per-repo, so a RuntimeCore (bank, client, seed) is built PER\n * WORKSPACE ROOT and cached, never once per process.\n *\n * The plugin imports NOTHING from dsh at all: every host shape is structurally typed here, and the\n * tool definitions are built in dsh's own registry shape rather than through its `defineTool`\n * builder (see `toDshParameters`). So there is no dsh package for pnpm to resolve inside a profile,\n * and no version to keep in step — any dsh whose event names still match can load this file.\n */\nimport { randomUUID } from \"node:crypto\";\nimport { resolveHostMemory } from \"./core/host-client\";\nimport { diag } from \"./core/diag\";\nimport type { ToolSpec } from \"./core/page-tools\";\nimport { log } from \"./core/log\";\nimport { RuntimeCore } from \"./core/runtime\";\nimport { HINDSIGHT_PLUGIN, readDshEvents, type DshSessionEvent } from \"./core/transcript-dsh\";\n\nconst HARNESS = \"dsh\";\n\n/** Cordis plugin name (loader diagnostics, and the `source.plugin` on everything we inject). */\nexport const name = HINDSIGHT_PLUGIN;\n\n/** The agent registry owns the lifecycle events below; without it there is nothing to bind. */\nexport const inject = [\"agents\"];\n\n// ── host shapes (structural: this package must not depend on dsh's packages) ─────\n\ninterface DshSession {\n  readonly header: { readonly id: string; readonly cwd?: string; readonly origin?: string };\n  /**\n   * Legacy in-memory event log. Present on DeepSeek Harness < alpha.4; removed in alpha.4+.\n   * Prefer {@link snapshotEvents} when available.\n   */\n  readonly events?: readonly DshSessionEvent[];\n  /** Public accessor on DeepSeek Harness alpha.4+ (replaces the removed `events` property). */\n  snapshotEvents?(): readonly DshSessionEvent[];\n  /** How many leading events a FORK copied from its parent (`session/fork`); 0 or absent otherwise.\n   *  Persisted with the session, so it survives a restart. */\n  readonly inheritedEventCount?: number;\n}\n\ninterface DshAgent {\n  readonly session: DshSession;\n}\n\n/** A `user/message` as dsh's pre-step decision carries it. */\ninterface DshUserMessage {\n  role: \"user\";\n  content: { type: string; text?: string }[];\n  source: { kind: string; form?: string };\n  id?: string;\n}\n\ntype PreStepDecision =\n  | { kind: \"enter\"; messages: DshUserMessage[] }\n  | { kind: \"reject\"; [key: string]: unknown };\n\ninterface PreStepPayload {\n  agent: DshAgent;\n  signal: AbortSignal;\n}\n\n/** The Cordis context surface this plugin uses. */\ninterface DshContext {\n  on(\n    event: \"agent/session-start\",\n    listener: (payload: { agent: DshAgent }) => void\n  ): (() => void) | void;\n  on(\n    event: \"agent/pre-step\",\n    listener: (\n      payload: PreStepPayload,\n      next: () => Promise<PreStepDecision>\n    ) => Promise<PreStepDecision>,\n    options?: { prepend?: boolean }\n  ): (() => void) | void;\n  on(\n    event: \"agent/turn-stopping\",\n    listener: (payload: { agent: DshAgent }) => Promise<void> | void\n  ): (() => void) | void;\n  on(\n    event: \"agent/disposed\",\n    listener: (payload: { agent: DshAgent }) => void\n  ): (() => void) | void;\n  inject(names: string[], callback: (ctx: DshToolContext) => void): void;\n}\n\ninterface DshToolContext {\n  tools: {\n    register(definition: unknown): void;\n    /** Registry introspection; used only to log what the host ended up exposing. */\n    schemas?(): { name: string }[];\n  };\n}\n\n/** `exec` as a dsh tool body receives it (only the caller matters to us). */\ninterface DshToolRunContext {\n  readonly agent?: DshAgent;\n}\n\n// ── per-workspace runtime cache ─────────────────────────────────────────────────\n\nexport interface Workspace {\n  core: RuntimeCore;\n  root: string;\n  /** Started by the first SESSION in this repo, then shared by every later one. */\n  seeded?: Promise<void>;\n  tools?: ToolSpec[];\n}\n\n/** `null` caches \"memory is off for this repo\" so a disabled bank isn't re-derived every turn. */\nconst workspaces = new Map<string, Workspace | null>();\n/**\n * sessionId -> agent, so a core's transcript source (which only receives the id) can read the live\n * log back on stop. `agent/disposed` is what bounds it: an agent holds its whole session log, so\n * dropping the entry when the host disposes the agent is what keeps a long-lived Web server from\n * pinning every session it ever opened.\n */\nconst liveAgents = new Map<string, DshAgent>();\n\n/**\n * Prefer `session.snapshotEvents()` (DeepSeek Harness alpha.4+); fall back to the legacy\n * `session.events` property so older hosts keep working. Missing both yields an empty log —\n * which is exactly the alpha.4 breakage when callers still read `events` alone.\n */\nexport function dshSessionEvents(\n  session: Pick<DshSession, \"snapshotEvents\" | \"events\">\n): readonly DshSessionEvent[] {\n  return session.snapshotEvents?.() ?? session.events ?? [];\n}\n\n/**\n * The events this session produced itself — what its write-back saves. A fork saves only its new\n * turns (#5940): the prefix it inherited is the parent's conversation, which the parent already\n * stores, and the child's first write-back used to send all of it again under its own document,\n * re-extracting history the bank already held. The full log is still what the model sees, so\n * everything else (the injection dedupe below) reads `dshSessionEvents`.\n */\nexport function ownEvents(\n  session: Pick<DshSession, \"snapshotEvents\" | \"events\" | \"inheritedEventCount\">\n): readonly DshSessionEvent[] {\n  return dshSessionEvents(session).slice(session.inheritedEventCount ?? 0);\n}\n\n/** Where a session is working. dsh records it on the session header; a session without one is rare. */\nfunction workspaceRoot(agent: DshAgent): string {\n  return agent.session.header.cwd || process.cwd();\n}\n\n/**\n * The memory runtime for one workspace root, built on first use.\n *\n * Bank derivation and the per-bank opt-out live here rather than in `apply`, because the plugin\n * loads before any session exists and the process may end up serving several unrelated\n * repositories. Building one has NO side effect: the seed is started by `ensureSeeded` when a\n * session actually opens, so merely registering the tools never seeds the launch directory.\n */\nfunction workspaceFor(root: string): Workspace | undefined {\n  const cached = workspaces.get(root);\n  if (cached !== undefined) return cached ?? undefined;\n\n  // One shared builder for every long-lived host (core/host-client.ts): the global switch, the\n  // per-bank opt-out and `optInOnly` all land in `cfg.disabled`.\n  const { cfg, bankId, client } = resolveHostMemory(HARNESS, root);\n  if (cfg.disabled) {\n    workspaces.set(root, null); // inert: same agent, no memory (baseline parity)\n    return undefined;\n  }\n  // The 5th argument is this host's whole reason for existing here: RuntimeCore binds the\n  // page tools (and retain stamps) to the workspace it is given, and dsh's process cwd is the\n  // launch directory, routinely a different repository from the session's.\n  const core = new RuntimeCore(client, bankId, cfg, HARNESS, root);\n  // The write-back path reads the log back off the live agent — dsh keeps the whole session in\n  // memory, so unlike opencode there is nothing to refetch over HTTP.\n  core.setTranscriptSource(async (sessionId) => {\n    const agent = liveAgents.get(sessionId);\n    return agent ? readDshEvents(ownEvents(agent.session)) : [];\n  });\n  const workspace: Workspace = { core, root };\n  workspaces.set(root, workspace);\n  return workspace;\n}\n\n/**\n * Start this repo's cold-check + background seed once.\n *\n * Fire-and-forget by design: `agent/session-start` is an emit that no extension point awaits, and\n * the Web UI must not wait on a network round-trip to open a session. Nothing the first prompt\n * needs comes from here — it builds its own pages preamble from that session's page list.\n */\nfunction ensureSeeded(workspace: Workspace): void {\n  workspace.seeded ??= workspace.core.seedIfCold(workspace.root);\n}\n\nfunction workspaceForAgent(agent: DshAgent): Workspace | undefined {\n  // A subagent session is a child of a conversation we already track: injecting into it would pay\n  // for a second recall per delegation, and retaining it would file a fragment of a session that\n  // the parent already stores in full.\n  if (agent.session.header.origin === \"subagent\") return undefined;\n  return workspaceFor(workspaceRoot(agent));\n}\n\n// ── message helpers ─────────────────────────────────────────────────────────────\n\n/**\n * The human text in this step's claimed batch.\n *\n * `agent/pre-step` fires before EVERY step, including tool continuations that claimed no new input,\n * and other plugins contribute their own context messages to the same batch (V3 hosts tag them\n * `kind: 'plugin'`, V4 hosts use a producer-owned kind such as `time-context`). Only a\n * `kind: 'user'` message is a prompt worth recalling on.\n */\nfunction promptOf(messages: readonly DshUserMessage[]): string {\n  return (messages || [])\n    .filter((message) => message?.source?.kind === \"user\")\n    .flatMap((message) => message.content || [])\n    .filter((block) => block?.type === \"text\" && block.text)\n    .map((block) => block.text!)\n    .join(\"\\n\")\n    .trim();\n}\n\n/**\n * Build the injected memory message.\n *\n * `form: 'recall'` is dsh's own vocabulary for retrieved context, so its UI renders the block as\n * recalled material rather than as something the user typed. Session format V4 requires injected\n * messages to use a producer-owned source kind; `plugin:hindsight` is the canonical fallback name\n * for an unregistered plugin. The non-user source also keeps the block out of a write-back.\n */\nfunction injectionMessage(text: string): DshUserMessage {\n  return {\n    id: randomUUID(),\n    role: \"user\",\n    content: [{ type: \"text\", text }],\n    source: { kind: `plugin:${HINDSIGHT_PLUGIN}`, form: \"recall\" },\n  };\n}\n\n/**\n * The text of the last memory block this session's history carries, if any.\n *\n * dsh keeps every injected message in the history it sends, so re-appending an unchanged block (the\n * per-turn roster) only stacks identical copies (#5026). This used to be remembered in a map keyed\n * by session id, which a fork (new id, inherited history) and a restart (empty map) both reset while\n * the block was still in the history — so the next unchanged recall appended a second copy (#5940).\n * Reading it off the history itself is what the model will actually see.\n */\nexport function lastInjectedText(events: readonly DshSessionEvent[]): string | undefined {\n  for (let i = events.length - 1; i >= 0; i--) {\n    const event = events[i];\n    if (event?.type !== \"user/message\") continue;\n    const message = event.data as Partial<DshUserMessage> | undefined;\n    if (message?.source?.kind !== `plugin:${HINDSIGHT_PLUGIN}`) continue;\n    return (message.content ?? []).map((block) => block.text ?? \"\").join(\"\\n\");\n  }\n  return undefined;\n}\n\n// ── the lifecycle, testable without a dsh host ──────────────────────────────────\n\n/**\n * The three lifecycle handlers, over an injectable workspace resolver. `apply` binds these to the\n * real Cordis events; the tests drive them with a stand-in agent and core.\n */\nexport function createDshHooks(resolve: (agent: DshAgent) => Workspace | undefined) {\n  return {\n    sessionStart({ agent }: { agent: DshAgent }): void {\n      const workspace = resolve(agent);\n      if (!workspace) return;\n      liveAgents.set(agent.session.header.id, agent);\n      ensureSeeded(workspace);\n    },\n\n    async preStep(\n      { agent, signal }: PreStepPayload,\n      next: () => Promise<PreStepDecision>\n    ): Promise<PreStepDecision> {\n      const decision = await next();\n      if (decision.kind !== \"enter\" || signal.aborted) return decision;\n      const workspace = resolve(agent);\n      if (!workspace) return decision;\n      const sessionId = agent.session.header.id;\n      liveAgents.set(sessionId, agent);\n      // A resumed session gets no `agent/session-start` in some compositions; seeding here too\n      // keeps the cold-check exactly-once without depending on which events a host fired.\n      ensureSeeded(workspace);\n      // No new human input means a tool continuation: recall already ran for this turn, and its\n      // block is already in the history the model is about to be sent.\n      const prompt = promptOf(decision.messages);\n      if (!prompt) return decision;\n      await workspace.core.onPrompt(sessionId, prompt);\n      const injection = workspace.core.getInjection(sessionId);\n      if (!injection) {\n        diag(HARNESS, \"inject_empty\", { session: sessionId });\n        return decision;\n      }\n      if (injection === lastInjectedText(dshSessionEvents(agent.session))) {\n        diag(HARNESS, \"inject_unchanged\", { session: sessionId });\n        return decision;\n      }\n      diag(HARNESS, \"inject_ok\", { session: sessionId, chars: injection.length });\n      return { kind: \"enter\", messages: [...decision.messages, injectionMessage(injection)] };\n    },\n\n    async turnStopping({ agent }: { agent: DshAgent }): Promise<void> {\n      const workspace = resolve(agent);\n      if (!workspace) return;\n      const sessionId = agent.session.header.id;\n      liveAgents.set(sessionId, agent);\n      // The stop boundary is the only moment the completed exchange is readable, so this bypasses\n      // the turn cadence exactly like the opencode idle path it shares (`onSessionIdle`).\n      await workspace.core.onSessionIdle(sessionId);\n    },\n\n    disposed({ agent }: { agent: DshAgent }): void {\n      liveAgents.delete(agent.session.header.id);\n    },\n  };\n}\n\n// ── native tools ────────────────────────────────────────────────────────────────\n\n/**\n * Project one harness-agnostic ToolSpec's input onto the JSON Schema dsh's registry stores.\n *\n * dsh's own `defineTool` is a pure builder — it compiles this exact schema shape and wraps the\n * callbacks — and `ctx.tools.register` validates a definition structurally, not by module identity.\n * Building the schema here therefore keeps the plugin free of a `@deepseek-ai/dsh-tools` dependency\n * that pnpm would have to resolve inside the profile, at the cost of one small projection.\n *\n * Our specs state their input as a Zod raw shape (the MCP dialect every harness shares) and are\n * deliberately flat: required or optional strings. Optionality and the description are the only two\n * facts to carry across; a parameter that is ever anything but a string fails loudly here rather\n * than registering a mis-typed tool.\n */\nexport function toDshParameters(spec: ToolSpec): Record<string, unknown> {\n  const properties: Record<string, unknown> = {};\n  const required: string[] = [];\n  for (const [key, schema] of Object.entries(spec.inputSchema)) {\n    const zod = schema as {\n      def?: { type?: string; innerType?: { def?: { type?: string } } };\n      description?: string;\n      isOptional?: () => boolean;\n    };\n    // `.optional()` wraps the real type, so unwrap before checking it — otherwise every optional\n    // parameter would pass the guard below whatever it actually holds.\n    const inner = zod.def?.type === \"optional\" ? zod.def.innerType?.def?.type : zod.def?.type;\n    if (inner !== undefined && inner !== \"string\") {\n      throw new Error(\n        `hindsight tool ${spec.name}: dsh projection supports string parameters only`\n      );\n    }\n    properties[key] = {\n      type: \"string\",\n      ...(zod.description ? { description: zod.description } : {}),\n    };\n    if (typeof zod.isOptional !== \"function\" || !zod.isOptional()) required.push(key);\n  }\n  return { type: \"object\", properties, ...(required.length ? { required } : {}) };\n}\n\n/** The tool bodies return MCP-shaped results and never throw; dsh wants a value or a throw. */\nasync function runSpec(spec: ToolSpec, args: Record<string, unknown>): Promise<string> {\n  const result = await spec.handler(args);\n  const text = (result.content || []).map((block) => block.text).join(\"\\n\");\n  // dsh normalizes a thrown tool body into an isError result with this message, which is exactly\n  // what our isError:true means — mapping it any other way would report a failure as a success.\n  if (result.isError) throw new Error(text || \"hindsight tool failed\");\n  return text;\n}\n\n/**\n * Register the hindsight_* suite on `ctx.tools`.\n *\n * The dsh tools registry is host+per-scope layered, so a host-plane registration is visible to\n * every agent — including the Web surface's per-session agent presets. Each call resolves the bank\n * from the CALLING agent's workspace, because one process serves many repositories.\n */\nfunction registerTools(toolCtx: DshToolContext, fallbackRoot: string): void {\n  // The registry is populated at plugin load, before any session exists, so the NAMES and schemas\n  // come from the launch directory's workspace and each call rebinds to its own caller's bank. The\n  // one consequence: if memory is off for the launch directory specifically (a `banks.<id>`\n  // opt-out) the tools are absent even for other repositories this process later serves.\n  const template = workspaceFor(fallbackRoot);\n  if (!template) return; // memory disabled where this process was launched\n  for (const spec of specsOf(template)) {\n    toolCtx.tools.register({\n      name: spec.name,\n      description: spec.description,\n      parameters: toDshParameters(spec),\n      output: {\n        schema: { type: \"string\" },\n        render: (_args: unknown, value: string) => [{ type: \"text\", text: value }],\n      },\n      async execute(args: Record<string, unknown>, exec: DshToolRunContext): Promise<string> {\n        // Bind to the caller's repository, not to whichever workspace happened to load first.\n        const workspace = exec?.agent ? workspaceForAgent(exec.agent) : template;\n        if (!workspace) return \"Hindsight memory is disabled for this workspace.\";\n        const bound = specsOf(workspace).find((candidate) => candidate.name === spec.name);\n        if (!bound) return `Hindsight tool ${spec.name} is unavailable.`;\n        return runSpec(bound, args);\n      },\n    });\n  }\n  // Log what the HOST sees, not just what we handed it: a tool that registers cleanly but never\n  // reaches a model is the failure mode worth catching, and this is the one line that shows it.\n  const exposed = toolCtx.tools.schemas?.() ?? [];\n  log.debug(HARNESS, \"tools registered\", {\n    count: specsOf(template).length,\n    hostCatalog: exposed.length,\n    hindsight: exposed.filter((schema) => schema.name?.startsWith(\"hindsight_\")).length,\n  });\n}\n\n/** The tool specs for one workspace, built once (each closes over that bank's client and root). */\nfunction specsOf(workspace: Workspace): ToolSpec[] {\n  workspace.tools ??= workspace.core.toolSpecs();\n  return workspace.tools;\n}\n\n// ── cordis entrypoint ───────────────────────────────────────────────────────────\n\n/**\n * Bind the memory lifecycle for the lifetime of `ctx`. Every listener is fail-open: RuntimeCore\n * never throws, and a workspace we cannot resolve simply leaves that session unmemoried.\n */\nexport function apply(ctx: DshContext): void {\n  const hooks = createDshHooks(workspaceForAgent);\n  ctx.on(\"agent/session-start\", hooks.sessionStart);\n  // `prepend: true` puts this listener outermost, so the injection is appended AFTER every other\n  // contributor's messages — the memory block reads last, closest to the model's turn.\n  ctx.on(\"agent/pre-step\", hooks.preStep, { prepend: true });\n  ctx.on(\"agent/turn-stopping\", hooks.turnStopping);\n  ctx.on(\"agent/disposed\", hooks.disposed);\n  // The tools registry is optional: a composition without it (a bare headless assembly) still gets\n  // recall, injection and write-back.\n  ctx.inject([\"tools\"], (toolCtx) => {\n    registerTools(toolCtx, process.cwd());\n  });\n}\n\nexport default { name, inject, apply };\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/host-client.ts",
      "content": "/**\n * ONE place a long-lived host turns \"which repo am I serving\" into a configured client.\n *\n * Every persistent host (dsh, Cline, Kilo, Prime Agent, opencode and the other plugin entries, the\n * MCP server) used to carry its own copy of the same four steps — loadConfig, deriveBankId,\n * applyBankConfig, `new HindsightClient({...})`. Five copies of a block is five chances to leave a\n * field out, and two already had: dsh and Prime Agent never passed `maxParallelRetains` (so both\n * silently ignored that setting), and dsh never passed the directory to `applyBankConfig` (so\n * `optInOnly` was not enforced there at all). #3600 was the same shape a third time — the\n * credential snapshot — which is why the fix is one shared builder rather than a sixth line added\n * to each host.\n *\n * The one-shot CLIs (`status.ts`, `deepen.ts`) stay out: they resolve config from `--config`/\n * `--harness` flags rather than from a workspace, and their process ends long before a credential\n * can rotate under them.\n */\nimport { applyBankConfig, loadConfig, type Config } from \"./config\";\nimport { bankProjectName, deriveBankIdOrSkip } from \"./bank\";\nimport { HindsightClient } from \"./hindsight\";\n\n/** A host's resolved memory: the config for THIS workspace, the bank it resolved to, and a client\n *  bound to both. */\nexport interface HostMemory {\n  cfg: Config;\n  bankId: string;\n  client: HindsightClient;\n}\n\n/** Resolve config for one workspace: env + file + `harnesses.<name>`, then the `banks.<id>`\n *  section for the bank that directory maps to, with `optInOnly` enforced. */\nexport function resolveHostConfig(\n  harness: string,\n  directory: string\n): { cfg: Config; bankId: string; project?: string } {\n  const cfg0 = loadConfig({ harness });\n  // A globally disabled plugin stops HERE, before bank derivation: `disabled` exists to be a\n  // zero-overhead baseline — the same agent with no memory — not merely a silent one. Callers\n  // return early on `cfg.disabled`, so the empty bank id never reaches a request.\n  if (cfg0.disabled) return { cfg: cfg0, bankId: \"\" };\n  const bankId = deriveBankIdOrSkip(cfg0, directory, harness);\n  // An unidentifiable repository takes the same exit: no bank id is safer than a guessed one, and\n  // `disabled` is the signal every caller already handles (#3950).\n  if (bankId === null) return { cfg: { ...cfg0, disabled: true }, bankId: \"\" };\n  const resolved = applyBankConfig(cfg0, bankId, directory);\n  // The repository the bank is ABOUT, for page scoping — the same rule as deepen.ts: only a bank\n  // that is this repo's, not one a `banks.<id>.bank` rename points several repos at (#4490).\n  const project = resolved.bankId === bankId ? bankProjectName(resolved.cfg, directory) : undefined;\n  return { ...resolved, project };\n}\n\n/**\n * Resolve config for `directory` and build the client for it.\n *\n * Callers still decide what a disabled config means for them (skip registration, cache a null\n * workspace, expose no tools) — `cfg.disabled` on the returned config already accounts for both\n * the global switch and the per-bank opt-out. Building a client has no side effect: nothing is\n * sent until a caller asks for something.\n */\nexport function resolveHostMemory(harness: string, directory: string): HostMemory {\n  const { cfg, bankId, project } = resolveHostConfig(harness, directory);\n  return {\n    cfg,\n    bankId,\n    client: new HindsightClient({\n      apiUrl: cfg.apiUrl,\n      apiToken: cfg.apiToken,\n      bank: bankId,\n      // Names the repo in the initiative pages this host captures, as the seeded pages do.\n      project,\n      maxParallelRetains: cfg.maxParallelRetains,\n      observationScopes: cfg.observationScopes,\n      pageSearchLimit: cfg.pageSearchLimit,\n      recallOptions: cfg.recallOptions,\n      // The credential a host STARTED with is not the one it must keep using: enable auth or\n      // rotate the key mid-session and the snapshot 401s every call until restart (#3600). Read\n      // through the same pipeline the constructor used, so a per-bank `banks.<id>.apiToken` is\n      // honoured on re-resolution exactly as it was on the first one.\n      // The URL stays the one this client was built with, so a token re-read after the config\n      // moved this directory to ANOTHER server is that server's credential: never send it here.\n      tokenProvider: () => {\n        const live = resolveHostConfig(harness, directory).cfg;\n        return live.apiUrl === cfg.apiUrl ? live.apiToken : cfg.apiToken;\n      },\n    }),\n  };\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/hook.ts",
      "content": "/**\n * Shared runtime for HOOK-based harnesses (Claude Code, Codex, Cursor CLI, ...).\n *\n * The ONE runtime path (see docs/superpowers/specs/2026-07-27-reflect-pages-runtime.md):\n *   - AUTO-INJECT once per session, on the first prompt, from the source `cfg.autoInject` names:\n *     \"reflect\" (default) is an agentic synthesis over the bank returning the root-cause decision\n *     with exact values; \"pages\" is a page search and \"recall\" a raw memory recall, both\n *     retrieval-only and far cheaper; \"none\" injects nothing and leaves it to the tools. Cached\n *     per session, injected on the turn it ran. A failed or empty attempt is retried on a later\n *     prompt within a small budget (see `resolveInjection`).\n *   - PAGES every turn: the page set is fetched on a cadence and matched LOCALLY against\n *     the prompt (section-level lexical scoring — no server/LLM call); the top sections are\n *     injected with provenance. Fast like recall, organized like reflect.\n *   - The tool-guide/page-roster block re-injects on the same cadence.\n *\n * Every outcome is recorded in the diagnostics file — a memory-less session can't masquerade as a\n * memory session. A failure never breaks the agent.\n *\n * A harness plugs in with a HookSpec: its name, how to read (prompt, cwd, sessionId) from its\n * stdin event, and how to wrap injected context in its native output schema. The pure logic lives\n * in `buildHookOutput` (client + cache file in, injection string out) so it's unit-testable\n * without stdin/stdout; `runHook` is thin plumbing around it, with a `makeClient` seam for tests.\n */\nimport { existsSync } from \"node:fs\";\nimport { deriveBankIdOrSkip } from \"./bank\";\nimport type { Config } from \"./config\";\nimport { applyBankConfig, loadConfig } from \"./config\";\nimport { diag, diagFilePath, readHookEvent } from \"./diag\";\nimport { describeError, log, setLogLevel } from \"./log\";\nimport { startBackgroundSeed } from \"./seed\";\nimport { stripInjectedMemory } from \"./transcript-util\";\nimport type { ClientOpts } from \"./hindsight\";\nimport { HindsightClient, ReflectError } from \"./hindsight\";\nimport { brandWord } from \"./brand\";\nimport {\n  buildReflectQuery,\n  buildSystemInjection,\n  formatPageFallback,\n  formatRecallFallback,\n  PAGE_INJECT_LEAD,\n  RECALL_INJECT_LEAD,\n} from \"./inject\";\nimport type { PageRef } from \"./page-injection\";\nimport { buildRosterRefresh, parsePageList } from \"./page-injection\";\nimport {\n  readSessionCache,\n  sessionCacheFile,\n  sessionRootDir,\n  stashPendingContext,\n  takePendingContext,\n  writeSessionCache,\n  type SessionCache,\n} from \"./session-cache\";\nimport { appendJournalTurn, journalPath } from \"./turn-journal\";\n\nexport interface HookEventFields {\n  prompt?: string;\n  cwd?: string;\n  sessionId?: string;\n}\n\nexport interface HookSpec {\n  /** Harness name — config `harnesses.<name>` section, {harness} template field, diag records. */\n  harness: string;\n  /** Read the fields out of the harness's stdin event (shapes differ per harness). */\n  parse(event: Record<string, unknown>): HookEventFields;\n  /** Optional event gate, evaluated before config loading: false makes the hook a silent no-op. */\n  accept?(event: Record<string, unknown>): boolean;\n  /** Some hosts execute hook commands from their global config directory. Those hosts must provide\n   * a workspace path in the event; falling back to process.cwd() would create a bank for config. */\n  requireCwd?: boolean;\n  /** Record this prompt in the session's own turn journal (core/turn-journal.ts). Set ONLY by the\n   *  harnesses whose host keeps no durable transcript, because for them the journal IS the\n   *  transcript their Stop hook retains — see the ZCode and TraeCode entries in\n   *  harness/hook-lifecycle.ts. */\n  journalPrompt?: boolean;\n  /** Wrap injected context (and an optional user-facing notice) in the harness's native\n   *  hook-output schema. Harnesses whose schema has no user-visible channel ignore `notice`. */\n  emit(context: string, notice?: string, event?: Record<string, unknown>): unknown;\n  /** For a host that only hands a TOOL hook's context to the model (Grok Build, #5467): the\n   *  turn's context is stashed for the session instead of emitted, and the next event this\n   *  accepts (a tool hook routed to the same entry) delivers it once through `emit`. */\n  toolHook?: {\n    accept(event: Record<string, unknown>): boolean;\n    emit(context: string): unknown;\n  };\n}\n\n/** Minimal client shape `buildHookOutput` needs — `HindsightClient` satisfies it structurally. */\ninterface HookClient {\n  reflect(query: string, opts: { budget?: string; timeoutMs: number }): Promise<string>;\n  listPages(): Promise<unknown>;\n  searchPages(\n    query: string,\n    opts?: { limit?: number; timeoutMs?: number }\n  ): Promise<{ id: string; name: string; snippet: string }[]>;\n  recallObservations(query: string, opts: { timeoutMs: number }): Promise<string[]>;\n  pagesSupported?: boolean;\n  /** Recorded on reflect failures so the diag trail says which bank to look at server-side. */\n  readonly bank?: string;\n}\n\n/** How many turns auto-inject may FAIL on before a session gives up on memory. The budget is\n *  turns, not time: each retry costs another full attempt (up to `reflectTimeoutMs` on the\n *  reflect path), so a dead server spends this many turns before every later turn is free. */\nconst HOOK_INJECT_ATTEMPTS = 2;\n\n/** How many turns a pages/recall source may come back EMPTY on before the session stops asking.\n *  Larger than the failure budget: an empty retrieval is cheap (no LLM), and its query is the\n *  current prompt, so an opener like \"hi\" matching nothing says nothing about the real question. */\nconst HOOK_INJECT_EMPTY_ATTEMPTS = 5;\n\n/**\n * What to cache for a once-per-session auto-injection, given what the source returned.\n *\n * `null` (ran, nothing matched THIS prompt) and `undefined` (failed) both stay unresolved so a\n * later turn can try again, each until its own attempt budget is spent. Caching either as an\n * answer cost the whole session its memory: a first-prompt timeout (#4607), or a first prompt\n * that simply matched nothing (#5082).\n */\nfunction resolveInjection(got: string | null | undefined, attempts: number): string | undefined {\n  if (got != null) return got;\n  const budget = got === null ? HOOK_INJECT_EMPTY_ATTEMPTS : HOOK_INJECT_ATTEMPTS;\n  return attempts >= budget ? \"\" : undefined;\n}\n\n/** Servers older than the query truncation reject a recall query over 500 tokens with HTTP 400,\n *  which cost the turn its memory on long or non-Latin prompts (#5476). A byte-level BPE token\n *  never covers less than one UTF-8 byte, so non-ASCII is costed at its byte length (a true\n *  ceiling) and ASCII at half a token, which still leaves English and code ~1000 characters. */\nconst RECALL_QUERY_MAX_TOKENS = 500;\n\nfunction boundRecallQuery(prompt: string): string {\n  let cost = 0;\n  let end = 0;\n  for (const ch of prompt) {\n    const cp = ch.codePointAt(0)!;\n    cost += cp < 0x80 ? 0.5 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;\n    if (cost > RECALL_QUERY_MAX_TOKENS) break;\n    end += ch.length;\n  }\n  return prompt.slice(0, end);\n}\n\n/** Page search for the prompt, formatted for injection. `null` = it ran and nothing\n *  matched (an answer); `undefined` = it FAILED (recorded as `${event}_failed`) and is worth\n *  retrying. The two used to be one value, which cached a transient failure as \"this session has\n *  no memory\" for every remaining turn (#4607). Never throws. */\nasync function injectPages(\n  harness: string,\n  prompt: string,\n  client: HookClient,\n  timeoutMs: number,\n  event: string,\n  lead?: string\n): Promise<string | null | undefined> {\n  const t0 = Date.now();\n  try {\n    // The search query rides in a GET query string; the goal's opening carries its keywords.\n    // How MANY pages come back is the client's `pageSearchLimit`, shared with the MCP tool.\n    const hits = await client.searchPages(prompt.slice(0, 500), { timeoutMs });\n    diag(harness, event, { ms: Date.now() - t0, count: hits.length });\n    return hits.length ? formatPageFallback(hits, lead) : null;\n  } catch (e) {\n    diag(harness, `${event}_failed`, { ms: Date.now() - t0, error: describeError(e) });\n    return undefined;\n  }\n}\n\n/** Raw recall over the bank (what it asks for is the client's `recallOptions`), formatted for\n *  injection; same contract as `injectPages`. */\nasync function injectRecall(\n  harness: string,\n  prompt: string,\n  client: HookClient,\n  timeoutMs: number,\n  event: string,\n  lead?: string\n): Promise<string | null | undefined> {\n  const t0 = Date.now();\n  try {\n    // What is asked for — types, token budget, everything — is the client's `recallOptions`.\n    const observations = await client.recallObservations(boundRecallQuery(prompt), { timeoutMs });\n    diag(harness, event, { ms: Date.now() - t0, count: observations.length });\n    return observations.length ? formatRecallFallback(observations, lead) : null;\n  } catch (e) {\n    diag(harness, `${event}_failed`, { ms: Date.now() - t0, error: describeError(e) });\n    return undefined;\n  }\n}\n\n/**\n * Reflect timed out or 5xx'd: the synthesis path broke, but retrieval may still answer. Try the\n * curated pages first (search), and only when none match fall back to a raw recall\n * over the bank's memories. Returns the memory body to inject, or a nullish value when both came\n * back empty or failed — the caller only asks whether there IS a body, so the sources' tri-state\n * is passed through rather than flattened. Never throws.\n */\nasync function reflectFallback(\n  harness: string,\n  prompt: string,\n  client: HookClient,\n  timeoutMs: number\n): Promise<string | null | undefined> {\n  // Page search and recall share ONE retrieval budget after reflect fails, rather than each\n  // spending a full injectTimeoutMs and doubling the time added to the host's hook window.\n  const deadline = Date.now() + timeoutMs;\n  const remaining = () => Math.max(deadline - Date.now(), 1);\n  return (\n    (await injectPages(harness, prompt, client, remaining(), \"reflect_fallback_pages\")) ??\n    // Event name predates the `injectRecall` rename and is kept: it is a logged contract that\n    // other tools read, so renaming it would silently break them.\n    (await injectRecall(harness, prompt, client, remaining(), \"reflect_fallback_observations\"))\n  );\n}\n\nexport interface HookOutput {\n  /** The model-facing injection block, or undefined when there's nothing to inject. */\n  context?: string;\n  /** User-facing line(s) — set only on the reflect turn (its goal + result preview). */\n  notice?: string;\n  /** This session's page roster, from the shared per-session cache. The SINGLE source\n   *  of truth for every page-derived block in a turn: the persistent-plugin runtime rebuilds its\n   *  SessionStart preamble from this too, so a turn can no longer be told both \"no pages yet\" and\n   *  a list of pages in the same context (#4607). Empty also signals a bank the engine never built. */\n  pages: PageRef[];\n}\n\n/**\n * Pure hook logic: reflect once per session (cached); page sections + roster on every\n * turn. Returns the injection plus a per-turn user-facing notice.\n */\nexport async function buildHookOutput(args: {\n  harness: string;\n  prompt: string;\n  cfg: Config;\n  client: HookClient;\n  cacheFile: string;\n}): Promise<HookOutput> {\n  const { harness, prompt, cfg, client, cacheFile } = args;\n\n  const cached = readSessionCache(cacheFile);\n  const turns = (cached.turns ?? 0) + 1;\n\n  // ── auto-inject: once per session, on the first prompt ────────────────────────\n  // cfg.autoInject picks the source: a reflect synthesis, a page search, or a recall of\n  // observations. \"none\" = tool-only mode: the roster's tool guide instead sends new goals through\n  // pages first and reserves reflection for gaps. Whatever the source, its body is\n  // cached as `reflectAnswer` (the field name predates the other sources).\n  let reflectAnswer = cached.reflectAnswer;\n  let reflectAttempts = cached.reflectAttempts ?? 0;\n  let reflectRanThisTurn = false;\n  // Set by whichever source actually FAILED — reflect's catch, or a pages/recall helper returning\n  // undefined. An empty answer is not a failure: a source can legitimately have nothing to say on a\n  // sparse bank (diag records reflect_empty), and reporting that would tell the user the plugin\n  // broke on exactly the sessions where it did not.\n  let reflectFailed = false;\n  // Set when reflect timed out / 5xx'd and a retrieval-only fallback supplied the memory instead.\n  let fallback: string | null | undefined;\n  const deferInitialReflect = cached.deferInitialReflect === true;\n  if (deferInitialReflect) {\n    // A new bank has no useful history yet. Do not burn the once-per-session synthesis on prompt\n    // one; this marker is deliberately consumed below so prompt two remains eligible to reflect.\n    diag(harness, \"reflect_deferred_new_bank\", { query: prompt.slice(0, 80) });\n  } else if (cfg.autoInject === \"pages\" && reflectAnswer === undefined) {\n    reflectRanThisTurn = true;\n    reflectAttempts++;\n    const got = await injectPages(\n      harness,\n      prompt,\n      client,\n      cfg.injectTimeoutMs,\n      \"inject_pages\",\n      PAGE_INJECT_LEAD\n    );\n    // `undefined` is the search FAILING, distinct from `null` (it ran, nothing matched). These\n    // modes stayed silent on a failure while reflect announced one — the same turn looked healthy\n    // whether memory was unavailable or simply had nothing to say.\n    if (got === undefined) reflectFailed = true;\n    reflectAnswer = resolveInjection(got, reflectAttempts);\n  } else if (cfg.autoInject === \"recall\" && reflectAnswer === undefined) {\n    reflectRanThisTurn = true;\n    reflectAttempts++;\n    const got = await injectRecall(\n      harness,\n      prompt,\n      client,\n      cfg.injectTimeoutMs,\n      \"inject_recall\",\n      RECALL_INJECT_LEAD\n    );\n    if (got === undefined) reflectFailed = true; // see the pages branch above\n    reflectAnswer = resolveInjection(got, reflectAttempts);\n  } else if (cfg.autoInject === \"reflect\" && reflectAnswer === undefined) {\n    reflectRanThisTurn = true;\n    reflectAttempts++;\n    const t0 = Date.now();\n    // Previously clamped to a hardcoded 20s, which made a raised reflectTimeoutMs dead config on\n    // this path (#4398); the 20s now lives in the default instead. Not clamped: a user who raises reflectTimeoutMs past the host's prompt-hook timeout (30s on\n    // the hook harnesses) must raise that too — see the README's reflectTimeoutMs row.\n    const timeoutMs = cfg.reflectTimeoutMs;\n    try {\n      reflectAnswer = await client.reflect(buildReflectQuery(prompt), {\n        // Automatic reflection runs inside the host's hook window. Hindsight's low budget is the\n        // supported default for bounded reflect calls; callers that explicitly invoke the MCP\n        // tool still get the deeper high-budget path.\n        budget: \"low\",\n        timeoutMs,\n      });\n      diag(harness, reflectAnswer ? \"reflect_ok\" : \"reflect_empty\", {\n        ms: Date.now() - t0,\n        chars: reflectAnswer.length,\n        query: prompt.slice(0, 80),\n        // Verbatim injected synthesis — the ONLY durable record of what the agent actually saw\n        // (post-mortems otherwise depend on the harness happening to persist hook context).\n        answer: reflectAnswer.slice(0, 8000),\n      });\n    } catch (e) {\n      // A failure is RETRYABLE, not an answer — `resolveInjection` leaves it unresolved until the\n      // budget is spent. Caching \"\" here meant one timeout on the session's first prompt disabled\n      // synthesis for the ENTIRE session, and against a real server a reflect near the timeout is a\n      // coin flip, not an edge case (#4607).\n      // ...except a permanent 4xx, which fails identically on every later turn: resolve it now\n      // rather than spend the session's second attempt on a call that cannot succeed (#5207).\n      reflectAnswer =\n        e instanceof ReflectError && e.permanent\n          ? \"\"\n          : resolveInjection(undefined, reflectAttempts);\n      reflectFailed = true;\n      log.warn(harness, \"reflect failed — session runs without memory\", {\n        error: describeError(e),\n      });\n      diag(harness, \"reflect_failed\", {\n        ms: Date.now() - t0,\n        bank: client.bank,\n        timeoutMs,\n        // Wider than describeError's default: the server's error body is the useful part.\n        error: describeError(e, 1500),\n        query: prompt.slice(0, 80),\n      });\n      if (e instanceof ReflectError && e.fallbackEligible) {\n        fallback = await reflectFallback(harness, prompt, client, cfg.injectTimeoutMs);\n        // The fallback body is cached exactly like a reflect answer: injected once, not retried.\n        if (fallback) reflectAnswer = fallback;\n      }\n    }\n  }\n\n  // ── page roster (ids + titles only): refreshed on the cadence ────────\n  const cadence = cfg.pageRefreshEveryTurns;\n  const stale = !cached.pages || (cadence > 0 && turns - cached.pages.atTurn >= cadence);\n  let pages = cached.pages?.list ?? [];\n  if (stale) {\n    const t0 = Date.now();\n    try {\n      pages = parsePageList(await client.listPages());\n      diag(harness, \"pages_ok\", { ms: Date.now() - t0, count: pages.length });\n    } catch (e) {\n      diag(harness, client.pagesSupported === false ? \"pages_unavailable\" : \"pages_failed\", {\n        ms: Date.now() - t0,\n        error: describeError(e),\n      });\n    }\n  }\n\n  writeSessionCache(cacheFile, {\n    turns,\n    reflectAnswer,\n    reflectAttempts,\n    pages: { atTurn: stale ? turns : (cached.pages?.atTurn ?? turns), list: pages },\n  } satisfies SessionCache);\n\n  const blocks: string[] = [];\n  // Hook-injected context lands in the USER MESSAGE and persists in the transcript — unlike a\n  // system prompt, it accumulates. The reflect block is injected exactly ONCE, the turn reflect\n  // ran. No cadence re-injection: replaying the turn-1 synthesis at arbitrary later turns reads\n  // as random noise once the session drifts, and the agent holds hindsight_reflect for a FRESH\n  // pass if compaction or drift makes it need memory again.\n  if (reflectAnswer && reflectRanThisTurn) blocks.push(buildSystemInjection(reflectAnswer));\n  // Pages are NOT auto-injected: the agent pulls them through\n  // hindsight_search_pages when a question warrants it — an unprompted injection on\n  // every turn (even a plain \"yes\") read as phantom research. The roster below keeps the tool\n  // and the page names in front of the agent.\n  if (cadence > 0 && turns % cadence === 0) {\n    blocks.push(\n      buildRosterRefresh(pages, {\n        reflectOnNewGoals: cfg.autoInject !== \"reflect\",\n        extra: cfg.toolGuideExtra,\n      })\n    );\n  }\n  const kept = blocks.filter(Boolean);\n\n  // User-facing notice ONLY on a turn that actually ran a source (reflect, pages or recall),\n  // showing its assigned goal and a preview of what came back. Ordinary turns stay silent — page\n  // content is pulled via the hindsight_search_pages tool, a visible tool call.\n  let notice: string | undefined;\n  if (fallback) {\n    // Silent: the session still got memory, just not a synthesis. The notice used to say which\n    // source answered and point at the diag file, but that read as an error on a turn that\n    // worked; reflect_failed + reflect_fallback_* in the diag trail carry the details.\n  } else if (reflectRanThisTurn && reflectAnswer) {\n    const q = prompt.replace(/\\s+/g, \" \").trim();\n    const excerpt = q.length > 48 ? `${q.slice(0, 48)}…` : q;\n    // Page/recall bodies open with a fixed lead line; preview what came back, not that.\n    const body =\n      cfg.autoInject === \"reflect\" ? reflectAnswer : reflectAnswer.split(\"\\n\").slice(1).join(\"\\n\");\n    const preview = body.replace(/\\s+/g, \" \").trim();\n    notice =\n      `${brandWord()} · goal: recall this repo's past decisions about “${excerpt}”\\n` +\n      `↳ ${preview.length > 140 ? `${preview.slice(0, 140)}…` : preview}`;\n  } else if (reflectFailed) {\n    // The failure is already in the diag trail and plugin.log, but both are files nobody is\n    // tailing mid-session, so a memory-less session looked exactly like a healthy one (#3443).\n    // One terse line pointing at the trail — not an explanation, and not advice to the agent:\n    // this fires only on a turn that actually attempted a source, so at most\n    // HOOK_INJECT_ATTEMPTS times per session.\n    notice = `${brandWord()} · no memory this turn — see ${diagFilePath()}`;\n  }\n\n  return { context: kept.length ? kept.join(\"\\n\\n\") : undefined, notice, pages };\n}\n\n/** Run one hook invocation: stdin event in, (maybe) an injection object on stdout. */\nexport async function runHook(\n  spec: HookSpec,\n  makeClient: (opts: ClientOpts) => HookClient = (o) => new HindsightClient(o)\n): Promise<void> {\n  // Anti-recursion: the codebase survey's own headless session sets this so its hooks are a no-op.\n  if (process.env.HINDSIGHT_DISABLE_HOOKS) return;\n\n  const ev = readHookEvent(spec.harness);\n  if (!ev) return;\n  if (spec.accept && !spec.accept(ev)) return;\n  const { prompt: rawPrompt, cwd: rawCwd, sessionId } = spec.parse(ev);\n  if (spec.toolHook?.accept(ev)) {\n    // Runs on every tool call, so it does nothing but hand over what a prompt hook stashed.\n    const pending = sessionId ? takePendingContext(spec.harness, sessionId) : undefined;\n    if (pending) process.stdout.write(JSON.stringify(spec.toolHook.emit(pending)));\n    return;\n  }\n  if (spec.requireCwd && !rawCwd) return;\n  const cwd = rawCwd || process.cwd();\n  // Hosts may put their own tagged blocks (a <system-reminder>, a task notification) before the\n  // user's words. Left in, they fill the head of the reflect goal and the length-capped recall\n  // query, so the search runs on boilerplate and never reaches what the user asked (#6488).\n  const prompt = stripInjectedMemory(rawPrompt || \"\").trim();\n  if (!prompt) return;\n\n  let cfg = loadConfig({ harness: spec.harness });\n  setLogLevel(cfg.logLevel);\n  if (cfg.disabled) {\n    log.debug(spec.harness, \"hook skipped: disabled\");\n    return;\n  }\n\n  // Before any network work, and deliberately before the bank is resolved: the journal is this\n  // session's only record of what the user said, and a slow or unreachable server must not be able\n  // to cost the turn. Journaling under `retainSessions: false` writes a temp file nothing reads,\n  // which is cheaper than threading that decision through two processes to find out.\n  if (spec.journalPrompt) {\n    appendJournalTurn(journalPath(spec.harness, sessionId), { role: \"user\", content: prompt });\n  }\n\n  const out = (context: string | undefined, notice?: string) =>\n    process.stdout.write(JSON.stringify(spec.emit(context ?? \"\", notice, ev)));\n\n  const sessionRoot = sessionRootDir(spec.harness, sessionId, cwd);\n  const derived = deriveBankIdOrSkip(cfg, cwd, spec.harness, sessionRoot);\n  if (derived === null) return; // repository unidentifiable: stay silent rather than invent a bank\n  const resolved = applyBankConfig(cfg, derived, cwd);\n  cfg = resolved.cfg;\n  const bankId = resolved.bankId;\n  if (cfg.disabled) {\n    log.debug(spec.harness, \"hook skipped: bank disabled via banks override\", { bank: bankId });\n    return;\n  }\n  const client = makeClient({\n    apiUrl: cfg.apiUrl,\n    apiToken: cfg.apiToken,\n    bank: bankId,\n    maxParallelRetains: cfg.maxParallelRetains,\n    observationScopes: cfg.observationScopes,\n    pageSearchLimit: cfg.pageSearchLimit,\n    recallOptions: cfg.recallOptions,\n  });\n  const cacheFile = sessionCacheFile(spec.harness, sessionId || \"no-session\");\n\n  // Safety net on EVERY harness: on the session's FIRST prompt (no cache file yet), fire the\n  // ingestion engine. Normally the shared SessionStart lifecycle already did — the engine's\n  // per-bank lock makes this a no-op — but a session that predates installation never received\n  // SessionStart. This limited fallback heals that case without duplicating any survey logic.\n  if (cfg.autoSeed !== false && !existsSync(cacheFile)) {\n    startBackgroundSeed(cwd, { limit: cfg.seedLimit, harness: spec.harness });\n  }\n\n  const output = await buildHookOutput({ harness: spec.harness, prompt, cfg, client, cacheFile });\n  // Mid-session heal: a bank with ZERO pages means the engine never built it (e.g. the session\n  // predates the install, so no SessionStart and the first-prompt net already passed). Fire the\n  // idempotent engine — the per-bank lock makes repeats free while it builds.\n  if (cfg.autoSeed !== false && client.pagesSupported !== false && output.pages.length === 0) {\n    startBackgroundSeed(cwd, { limit: cfg.seedLimit, harness: spec.harness });\n  }\n  let context = output.context;\n  if (context && spec.toolHook && sessionId) {\n    stashPendingContext(spec.harness, sessionId, context);\n    context = undefined;\n  }\n  if (context || output.notice) out(context, output.notice);\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/runtime.ts",
      "content": "/**\n * Host adapter runtime for PERSISTENT-PLUGIN harnesses (opencode, opencode2, Kilo, Cline, dsh, pi,\n * Prime Agent — every host that loads us once and keeps us). It delegates SessionStart and\n * prompt behavior to the same core lifecycle as fresh-process hook harnesses; this class keeps only\n * the host-specific injection, toast, and incremental-transcript responsibilities.\n *\n * A harness adapter feeds it three normalized events and reads two values back:\n *   - seedIfCold(repoPath)          : plugin load -> cold-check auto-seed (the page preamble is\n *                                     NOT computed here; onPrompt builds it per session)\n *   - onPrompt(sessionId, prompt)   : each user turn -> recall + build this turn's injection\n *   - getInjection(sessionId)       : the text to inject into this turn's user message (or undefined)\n *   - toolSpecs()                   : the hindsight_* page/recall tools to register natively\n *   - onTranscript(sessionId, turns, lastTurnComplete): full transcript -> write back (on by default)\n *   - onSessionIdle(sessionId)      : assistant finished -> refetch + write back the completed\n *                                     exchange (the Stop-equivalent these hosts lack)\n *   - flush()                       : host is exiting -> wait (bounded) for in-flight write-backs\n * No opencode/claude specifics live here — only the memory logic.\n */\nimport type { Config } from \"./config\";\nimport { maybeAutoUpdate } from \"./auto-update\";\nimport { DAEMON_WAIT_RETAIN_MS, DAEMON_WAIT_SESSION_START_MS, ensureDaemon } from \"./daemon\";\nimport { diag } from \"./diag\";\nimport { describeError, log, setLogLevel } from \"./log\";\nimport type { HindsightClient } from \"./hindsight\";\nimport { buildPagesPreamble } from \"./page-injection\";\nimport { buildPageTools, type ToolSpec } from \"./page-tools\";\nimport { buildPageTrigger } from \"./missions\";\nimport { retainLiveSession, type TransportTurn } from \"./chat\";\nimport { memoryCursorStore } from \"./retain-cursor\";\nimport { memoryUsageCursorStore, recordUsage } from \"./usage\";\nimport { buildRetainStamp } from \"./retain-stamp\";\nimport { buildSessionStartContext } from \"./session-start\";\nimport { syncCompanionSkill } from \"./skill-sync\";\nimport { buildHookOutput } from \"./hook\";\nimport { stripInjectedMemory } from \"./transcript-util\";\nimport { sessionCacheFile, writeSessionCache } from \"./session-cache\";\n\nconst HARNESS = \"opencode\";\n/** How long `flush` holds a host's exit for in-flight write-backs: room for one retain request. */\nconst FLUSH_TIMEOUT_MS = 10_000;\n\nexport class RuntimeCore {\n  private readonly injection = new Map<string, string>(); // sessionId -> this turn's injection block\n  private readonly turnCount = new Map<string, number>(); // sessionId -> user-turn counter (cadence)\n  private readonly sessionState = new Map<string, { startTs: string; retainedTurns: number }>();\n  /** Live write-back cursors. In memory, unlike the hook harnesses': this host outlives the session. */\n  private readonly cursors = memoryCursorStore();\n  /** Turns already written to the usage log (core/usage.ts), per session. */\n  private readonly usageCursors = memoryUsageCursorStore();\n  /** Pulls a session's CURRENT transcript from the host (set by the adapter); see onSessionIdle. */\n  private fetchTranscript?: (sessionId: string) => Promise<TransportTurn[]>;\n  /** Write-backs started and not yet settled — what `flush` waits for. */\n  private readonly inFlight = new Set<Promise<void>>();\n  private deferInitialReflect = false;\n  /** Host-notice channel (opencode/Kilo: client.tui.showToast via the adapter). Optional, fail-open. */\n  private notify?: (title: string, message: string) => void;\n\n  constructor(\n    private readonly client: HindsightClient,\n    private readonly bankId: string,\n    private readonly cfg: Config,\n    /**\n     * Which persistent-plugin host loaded us. Scopes diagnostics, the session cache file and the\n     * retained transcript's harness field, so Kilo sessions don't masquerade as opencode ones.\n     * Defaults to opencode, the original (and only other) plugin harness.\n     */\n    readonly harness: string = HARNESS,\n    /** Workspace root this host opened — the SAME directory bank resolution used, so a\n     *  `{gitProject}` in retainTags names the repo the bank was derived from. */\n    private readonly projectDir: string = process.cwd()\n  ) {\n    setLogLevel(cfg.logLevel);\n  }\n\n  setNotifier(notify: (title: string, message: string) => void): void {\n    this.notify = notify;\n  }\n\n  /**\n   * Supply a way to READ the session's transcript back from the host. Without it `onSessionIdle`\n   * no-ops, so hosts that can't refetch keep the old (lagging) turn-driven write-back rather than\n   * retaining a stale transcript.\n   */\n  setTranscriptSource(fetch: (sessionId: string) => Promise<TransportTurn[]>): void {\n    this.fetchTranscript = fetch;\n  }\n\n  /** The hindsight_* page + recall tools, bound to this bank, for the harness to register natively. */\n  toolSpecs(): ToolSpec[] {\n    return buildPageTools(this.client, this.bankId, {\n      repoDir: this.projectDir,\n      harness: this.harness,\n      pageTrigger: buildPageTrigger(this.cfg),\n      reflectTimeoutMs: this.cfg.reflectToolTimeoutMs,\n      reflectBudget: this.cfg.reflectBudget,\n      toolGuideExtra: this.cfg.toolGuideExtra,\n      stampFor: () =>\n        buildRetainStamp(this.cfg, {\n          directory: this.projectDir,\n          harness: this.harness,\n          bankId: this.bankId,\n        }),\n    });\n  }\n\n  get writeBackEnabled(): boolean {\n    return this.cfg.retainSessions;\n  }\n\n  /**\n   * Plugin load (SessionStart-equivalent): on a cold repo, deterministically start the background\n   * git-log seed + codebase survey. Reuses the exact hook-harness logic\n   * (`buildSessionStartContext`) so opencode seeds identically. Never throws.\n   *\n   * It deliberately does NOT keep that call's pages preamble. This runs once per PROCESS and\n   * these hosts outlive every session, so a roster captured here is stale for every session but\n   * the first — `onPrompt` builds its own from the session's live page list (#4607).\n   */\n  async seedIfCold(repoPath: string | undefined): Promise<void> {\n    // Anti-recursion: a headless survey session runs the agent (which loads this plugin) with\n    // HINDSIGHT_DISABLE_HOOKS=1 — the tools stay registered (toolSpecs, so the survey can ingest),\n    // but seeding/recall/write-back must no-op or the survey would re-seed itself (see core/survey.ts).\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return;\n    // Companion skill, the same housekeeping `runSessionStartHook` does for hook harnesses — but\n    // with `install`, because a persistent-plugin host can be wired by its OWN plugin manager\n    // (`dsh plugin add …`, `cline plugin install`), a route our installer never sees, leaving the\n    // plugin loaded with its tools registered and no skill on disk at all (#4406). No-op for a host\n    // with no skills directory (opencode; opencode2 registers it in memory instead).\n    syncCompanionSkill(this.harness, { install: true });\n    // Daemon mode: this is the SessionStart of a persistent-plugin host, so it owns the same\n    // warm-up the hook harnesses do in `runSessionStartHook` — start it before the user has typed\n    // anything, wait only briefly, and let a cold one keep coming up in the background. Without it\n    // these hosts never started a daemon at all and every request failed with ECONNREFUSED (#3524);\n    // `runSessionStartHook` is a hook-only wrapper, so calling `buildSessionStartContext` directly\n    // (as every plugin harness does) skipped the ensure entirely.\n    await ensureDaemon(this.cfg, this.harness, { waitMs: DAEMON_WAIT_SESSION_START_MS });\n    // Same session-start housekeeping the hook harnesses do in `runSessionStartHook`: a persistent\n    // plugin host is a session start too, and leaving it out would mean opencode/Kilo/Cline users\n    // never got an update — the parity gap `ensureDaemon` above already had to be fixed for.\n    void maybeAutoUpdate(this.cfg);\n    try {\n      const out = await buildSessionStartContext({\n        cwd: repoPath || process.cwd(),\n        bankId: this.bankId,\n        cfg: this.cfg,\n        client: this.client,\n        harness: this.harness,\n      });\n      // The seed note is user-facing; opencode has no visible-system channel at load, so surface it\n      // on stderr (shows in the plugin log / console) rather than dropping it.\n      // Banner: via the host's toast API when available (stderr corrupts the TUI); always logged.\n      if (out.systemMessage) {\n        const plain = out.systemMessage.replace(/\\x1b\\[[0-9;]*m/g, \"\");\n        log.info(this.harness, plain);\n        this.notify?.(\"Hindsight\", plain.replace(/^Hindsight is /, \"Is \"));\n      }\n      this.deferInitialReflect = out.deferInitialReflect === true;\n    } catch {\n      /* seeding is best-effort — a cold-check failure never breaks the agent */\n    }\n  }\n\n  /**\n   * Each user turn delegates to the same `buildHookOutput` used by hook harnesses. The cache file\n   * intentionally replaces the old in-memory reflect/page state, keeping lifecycle behavior\n   * identical across hosts while this adapter retains only delivery-specific state.\n   */\n  async onPrompt(sessionId: string | undefined, rawPrompt: string): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId) return;\n    // Same cleaning as the hook harnesses' runHook: a host's tagged block ahead of the user's\n    // words would otherwise become the reflect goal and the length-capped recall query (#6488).\n    const prompt = stripInjectedMemory(rawPrompt).trim();\n    // No prompt text means no recall, so no block for this turn either: the previous turn's block\n    // must not be handed out again, since every host now persists it into the user message.\n    if (!prompt) {\n      this.injection.delete(sessionId);\n      return;\n    }\n    const turns = (this.turnCount.get(sessionId) ?? 0) + 1;\n    this.turnCount.set(sessionId, turns);\n\n    const cacheFile = sessionCacheFile(this.harness, sessionId);\n    if (this.deferInitialReflect) {\n      // `seedIfCold` has no session id. Transfer its SessionStart decision to the first concrete\n      // session here; `buildHookOutput` consumes it exactly once, like hook harnesses do.\n      this.deferInitialReflect = false;\n      writeSessionCache(cacheFile, { deferInitialReflect: true });\n    }\n    const output = await buildHookOutput({\n      harness: this.harness,\n      prompt,\n      cfg: this.cfg,\n      client: this.client,\n      cacheFile,\n    });\n\n    const blocks: string[] = [];\n    // The SessionStart-equivalent preamble, injected once on the first turn (later turns get the\n    // periodic refresh below). Built HERE, from this session's own roster, rather than reused from\n    // plugin load: that one is a process-lifetime snapshot, so a host started before the pages\n    // existed told every later session \"No pages yet\" while the same turn's memory block\n    // listed pages by id (#4607).\n    if (turns === 1) {\n      blocks.push(\n        buildPagesPreamble(output.pages, {\n          reflectOnNewGoals: this.cfg.autoInject !== \"reflect\",\n          extra: this.cfg.toolGuideExtra,\n        })\n      );\n    }\n    if (output.context) blocks.push(output.context);\n    // OpenCode has no user-message hook channel; use its native toast instead of stderr, which\n    // renders inside the TUI input line. The shared output owns when a notice exists.\n    if (output.notice) {\n      // The notice is painted for a terminal; a toast shows the escapes as text (#6257).\n      const preview = output.notice\n        .replace(/\\x1b\\[[0-9;]*m/g, \"\")\n        .replace(/\\s+/g, \" \")\n        .trim()\n        .slice(0, 140);\n      log.info(this.harness, \"reflect goal\", { preview });\n      this.notify?.(\"Hindsight · recalled past decisions\", preview);\n    }\n    const block = blocks.filter(Boolean).join(\"\\n\\n\");\n    this.injection.set(sessionId, block);\n  }\n\n  /**\n   * The text to inject into this turn's user message (built by the preceding onPrompt), or\n   * undefined.\n   *\n   * It goes into the USER turn on every host, never the system prompt (#5914). The block changes\n   * from turn to turn — the recall runs once, the roster refresh on a cadence — so a system prompt\n   * carrying it differed between requests and broke the provider's prefix cache from that point\n   * on. Persisted in the turn it belongs to, it leaves the system prompt and the earlier history\n   * byte-identical. That used to need a fallback to the most recent block for opencode's\n   * `experimental.chat.system.transform`, which fired with no session id; nothing reads it that\n   * way any more.\n   */\n  getInjection(sessionId: string): string | undefined {\n    return this.injection.get(sessionId) || undefined;\n  }\n\n  /**\n   * Full normalized transcript (rich: user/assistant text + tool calls/outputs): upsert every turn\n   * when enabled. On by default for persistent-plugin hosts (parity with hook-harness Stop\n   * write-back), so opencode sessions compound into memory; opt out with `retainSessions: false`.\n   *\n   * There is deliberately no client-side cadence. Batching write-backs meant holding turns in a\n   * process the host can close at any moment, with no reliable signal on the way out — the flush a\n   * cadence needs would have to ride a session-end hook, and those are cancelled at shutdown. The\n   * server coalesces instead: queued retains for one document fold into a single execution\n   * (`engine.retain.fold`), so submitting every turn costs one extraction, not one per turn, and\n   * nothing is ever held somewhere it can be lost.\n   */\n  async onTranscript(\n    sessionId: string,\n    turns: TransportTurn[],\n    /** Whether the agent has finished answering the last prompt. Required, not defaulted: opencode\n     *  hands this over while BUILDING a request (false), pi and Cline after the run ends (true), and\n     *  a wrong default records every turn one late and never the session's last. */\n    lastTurnComplete: boolean\n  ): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId || !turns.length) return;\n    // Usage is a local file, so it is recorded whether or not write-back is on (#5391).\n    this.recordUsage(sessionId, turns, lastTurnComplete);\n    if (!this.writeBackEnabled) return;\n    const st = this.stateFor(sessionId);\n    this.retain(sessionId, turns, st.startTs);\n  }\n\n  /**\n   * Session went idle — the assistant has finished replying.\n   *\n   * This is the Stop-equivalent these hosts lack. `onTranscript` alone is driven by\n   * `messages.transform`, which the host runs while BUILDING a request, so the transcript it hands\n   * us never contains the reply that request produced: write-back always lagged one user turn, and\n   * a session's final exchange was never retained at all. Refetching here (rather than replaying a\n   * cached list) is the whole point — the cached one predates the reply.\n   *\n   * Cadence is deliberately bypassed: idle means \"there may be nothing after this\", so a pending\n   * turn must not wait for a threshold it will never reach.\n   */\n  async onSessionIdle(sessionId: string): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId || !this.fetchTranscript) return;\n    let turns: TransportTurn[];\n    try {\n      turns = await this.fetchTranscript(sessionId);\n    } catch (e) {\n      diag(this.harness, \"idle_fetch_failed\", {\n        error: describeError(e),\n        session: sessionId,\n      });\n      return;\n    }\n    if (!turns.length) return;\n    this.recordUsage(sessionId, turns, true); // idle: the reply is in\n    if (!this.writeBackEnabled) return; // usage above is local and recorded regardless (#5391)\n    const st = this.stateFor(sessionId);\n    // idle can fire more than once for one exchange (and again on a session with no new activity);\n    // only retain when this transcript actually grew past what we last wrote.\n    if (turns.length <= st.retainedTurns) return;\n    st.retainedTurns = turns.length;\n    this.retain(sessionId, turns, st.startTs, \"idle\");\n  }\n\n  private recordUsage(sessionId: string, turns: TransportTurn[], lastTurnComplete: boolean): void {\n    recordUsage({\n      harness: this.harness,\n      sessionId,\n      bankId: this.bankId,\n      turns,\n      cursors: this.usageCursors,\n      lastTurnComplete,\n      // No `reviseLastTurn` here, unlike the hook path: this runtime never records a turn before its\n      // reply exists. `onTranscript` is handed `false` while the host is still building the request,\n      // which holds the turn back, and `onSessionIdle` refetches a transcript that includes the\n      // reply before recording it.\n    });\n  }\n\n  private stateFor(sessionId: string): {\n    startTs: string;\n    retainedTurns: number;\n  } {\n    let st = this.sessionState.get(sessionId);\n    if (!st) {\n      st = { startTs: new Date().toISOString(), retainedTurns: 0 };\n      this.sessionState.set(sessionId, st);\n    }\n    return st;\n  }\n\n  /**\n   * Wait for every write-back still in flight, at most `timeoutMs`. Write-backs stay fire-and-forget\n   * so a turn never blocks on the network; a host that announces its exit (pi's `session_shutdown`)\n   * calls this so the session's final retain is not dropped with the process (#5081). Bounded so a\n   * stalled server cannot hold the host's exit open. Never throws.\n   */\n  async flush(timeoutMs = FLUSH_TIMEOUT_MS): Promise<void> {\n    if (!this.inFlight.size) return;\n    let timer: ReturnType<typeof setTimeout> | undefined;\n    await Promise.race([\n      Promise.all(this.inFlight),\n      new Promise<void>((r) => {\n        timer = setTimeout(r, timeoutMs);\n      }),\n    ]);\n    clearTimeout(timer);\n  }\n\n  /** Fire-and-forget upsert of the session transcript; never throws into the host. */\n  private retain(\n    sessionId: string,\n    turns: TransportTurn[],\n    startTs: string,\n    trigger = \"turn\"\n  ): void {\n    const t0 = Date.now();\n    // Daemon mode: the write path is the last chance to get a daemon up — the Stop-hook role, for\n    // hosts that have no Stop hook. A daemon that died mid-session would otherwise take the whole\n    // exchange with it. The wait sits INSIDE the fire-and-forget chain, so\n    // unlike the Stop hook it costs the host nothing: this call already returns before the retain\n    // does. Deliberately not gated on the result — retain proceeds either way, so an unreachable\n    // daemon produces the same `retain_failed` diagnostic as an unreachable Cloud server.\n    const write = ensureDaemon(this.cfg, this.harness, { waitMs: DAEMON_WAIT_RETAIN_MS })\n      .then(() =>\n        retainLiveSession(this.client, sessionId, turns, startTs, this.harness, {\n          cursors: this.cursors,\n          stamp: buildRetainStamp(this.cfg, {\n            directory: this.projectDir,\n            harness: this.harness,\n            bankId: this.bankId,\n            sessionId,\n          }),\n        })\n      )\n      .then(() =>\n        diag(this.harness, \"retain_ok\", {\n          ms: Date.now() - t0,\n          turns: turns.length,\n          session: sessionId,\n          trigger,\n        })\n      )\n      .catch((e) =>\n        diag(this.harness, \"retain_failed\", {\n          ms: Date.now() - t0,\n          error: describeError(e),\n          session: sessionId,\n          trigger,\n        })\n      );\n    this.inFlight.add(write);\n    void write.finally(() => this.inFlight.delete(write));\n  }\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/session-start.ts",
      "content": "/**\n * Shared `SessionStart` lifecycle: deterministically auto-seeds a cold repo's bank from its git\n * history (in the background, non-blocking), keeps warm banks deepening on every start, and\n * injects a short visible note plus the live\n * page roster + guidance preamble that tells the agent to consult the repo's pages.\n *\n * Earlier design injected an instruction asking the AGENT to pose a y/n question to the user and\n * then run a seed command itself. Live testing showed that doesn't work: the model surfaces the\n * question, then plows ahead with the user's actual task and never runs the command — so nothing\n * ever seeds. Fix: the hook does the seeding itself. There is nothing left for the agent to decide\n * or execute for seeding, so no shell command (and no shell-escaping) is needed anymore.\n *\n * Tri-state cold check: a boolean \"is it cold?\" would collapse \"cold\" and \"server unreachable\"\n * into the same outcome, which is wrong here — a transient outage must not get treated the same\n * as \"already seeded\" and silently suppress seeding forever. So `buildSessionStartContext` calls\n * `client.listDocumentIds` directly so it can tell the three cases apart:\n *   - throws (server unreachable)      -> no seed, no state written  (try again next session)\n *   - non-empty set (warm/pre-seeded)  -> no seed, seededAt written  (remember, skip enumerating)\n *   - empty set (cold)                 -> start the background seed, seededAt written, note added\n * \"Empty\" means no git documents AND no survey-baseline marker: under `gitIngest: \"none\"` no git\n * document is ever written, and the markers are what show the repo was already surveyed (#5124).\n */\nimport { gitHeadSha, gitLogIsCurrent, hasGitHistory, commitsSince } from \"./git\";\nimport { DEEPEN_DIFF_TARGET } from \"./status\";\nimport { startBackgroundSeed } from \"./seed\";\nimport { maybeAutoUpdate } from \"./auto-update\";\nimport { syncCompanionSkill } from \"./skill-sync\";\nimport { SURVEY_DOC_IDS, startCodebaseSurvey, type SurveyHarness } from \"./survey\";\nimport { applyBankConfig, loadConfig } from \"./config\";\nimport { DAEMON_WAIT_SESSION_START_MS, ensureDaemon } from \"./daemon\";\nimport type { Config } from \"./config\";\nimport { deriveBankIdOrSkip } from \"./bank\";\nimport { brandWord } from \"./brand\";\nimport { diag, readHookEvent } from \"./diag\";\nimport { setLogLevel } from \"./log\";\nimport { parsePageList, buildPagesPreamble, type PageRef } from \"./page-injection\";\nimport type { ClientOpts, RetainOpts } from \"./hindsight\";\nimport type { RetainExtractionMode } from \"./missions\";\nimport { buildRetainStamp } from \"./retain-stamp\";\nimport { detectLegacyClaudePlugin, legacyClaudePluginWarning } from \"./legacy\";\nimport { HindsightClient } from \"./hindsight\";\nimport {\n  sessionCacheFile,\n  sessionRootDir,\n  stashPendingContext,\n  writeSessionCache,\n} from \"./session-cache\";\n\n/** Minimal client shape `buildSessionStartContext` needs. */\ninterface SeedContextClient {\n  listDocumentIds(tag: string, tagsMatch?: \"all\" | \"all_strict\"): Promise<Set<string>>;\n  // Optional: lets the git note see a git-log document written at a commit HEAD is behind\n  // (gitLogIsCurrent). The minimal test clients omit it and keep the exact-HEAD check.\n  documentTags?(documentId: string): Promise<string[] | undefined>;\n  listPages(): Promise<unknown>;\n  // Optional: whether the bank holds any document at all. Without it the first-prompt reflect is\n  // never deferred — only a confirmed-empty bank is.\n  hasDocuments?(): Promise<boolean>;\n  pagesSupported?: boolean;\n  // Optional: applies the bank's missions and retain strategies when the deepen engine (which\n  // otherwise does it) is not started. HindsightClient has it; the minimal test clients omit it.\n  configureBankSettings?(opts: {\n    manage?: boolean;\n    extractionMode?: RetainExtractionMode;\n    defaults?: Record<string, unknown>;\n  }): Promise<void>;\n  // Optional: used to write the survey-baseline marker (Option A). HindsightClient has it; the\n  // minimal test clients omit it, and the baseline write guards on its presence.\n  retain?(\n    content: string,\n    context: string,\n    documentId: string,\n    tags: string[],\n    strategy: string,\n    opts?: RetainOpts\n  ): Promise<void>;\n}\n\n/**\n * The session banner: one line — the gradient \"Hindsight\" wordmark (same colors as the API\n * server's banner) plus the repo's bank. Shown on EVERY session start; \"learning\" on a cold\n * repo (first ingest running), \"remembering\" once the bank is warm.\n */\nexport function buildSeedBanner(bankId: string, cold = true, gitNote?: string): string {\n  // Two lines: what Hindsight DOES for this repo (value, not mechanism), then where the memory\n  // lives + sync state. The brand word leads line 1 so the host TUI's message prefix lands there.\n  const headline = cold\n    ? `${brandWord()} is learning this repo — ingesting its decisions, conventions and history`\n    : `${brandWord()} is tracking the decisions, conventions and history of this repo`;\n  const details = `  ↳ memory bank “${bankId}”` + (gitNote ? ` · ${gitNote}` : \"\");\n  return `${headline}\\n${details}`;\n}\n\n/**\n * One-phrase git-sync state for the banner (the syncStatus contract, condensed): whether the bank\n * is current with the repo's commits. Cheap — reuses the cold-check's doc-id set plus ONE tag query\n * (gitlog-head:<sha>, the freshness marker the deepen engine maintains), and one read of that tag\n * when HEAD is not the commit it names. Same check as the deepen engine's (gitLogIsCurrent), so the\n * banner never promises a catch-up the engine will skip. Returns undefined when there's nothing\n * meaningful to say (gitIngest off, no git, cold bank — \"learning\" already covers it).\n */\nasync function gitSyncNote(args: {\n  client: SeedContextClient;\n  cwd: string;\n  gitIds: Set<string>;\n  mode: \"message\" | \"full\" | \"none\";\n  cold: boolean;\n}): Promise<string | undefined> {\n  const { client, cwd, gitIds, mode, cold } = args;\n  if (mode === \"none\" || cold) return undefined;\n  const head = gitHeadSha(cwd);\n  if (!head) return undefined;\n  const gitlogCurrent = await gitLogIsCurrent(client, cwd, head).catch(() => undefined);\n  if (gitlogCurrent === undefined) return undefined; // server hiccup: say nothing rather than guess\n  if (mode === \"message\") return gitlogCurrent ? \"git in sync\" : \"catching up on new commits\";\n  // full: deepening progress = per-commit docs vs the recent-history target\n  const deepened = [...gitIds].filter((id) => id.startsWith(\"git:\")).length;\n  let target = DEEPEN_DIFF_TARGET;\n  try {\n    const { execFileSync } = await import(\"node:child_process\");\n    const n = Number(\n      execFileSync(\"git\", [\"-C\", cwd, \"rev-list\", \"--count\", \"HEAD\"], {\n        encoding: \"utf8\",\n        windowsHide: true,\n        stdio: [\"ignore\", \"pipe\", \"pipe\"], // do not corrupt the host banner on a late git failure\n      }).trim()\n    );\n    if (n > 0) target = Math.min(DEEPEN_DIFF_TARGET, n);\n  } catch {\n    /* keep the default target */\n  }\n  return gitlogCurrent && deepened >= target\n    ? \"git in sync\"\n    : `syncing git history (${Math.min(deepened, target)}/${target})`;\n}\n\n/** Split SessionStart output: `systemMessage` renders in the terminal (user-visible);\n *  `additionalContext` is injected into the model's context only. */\nexport interface SessionStartOutput {\n  systemMessage?: string;\n  additionalContext?: string;\n  /** Internal lifecycle signal: defer one auto-reflect while a new bank gains useful content. */\n  deferInitialReflect?: boolean;\n}\n\n/** Host-specific adapter for the shared SessionStart core. Claude and Codex use the\n * Claude-compatible envelope; Cursor's native hooks require snake-case `additional_context`. */\nexport interface SessionStartHookSpec {\n  harness: string;\n  parse(event: Record<string, unknown>): { cwd?: string; sessionId?: string };\n  /** Optional event gate, evaluated before config loading: false makes the hook a silent no-op. */\n  accept?(event: Record<string, unknown>): boolean;\n  emit(output: SessionStartOutput): unknown;\n  /** The host drops SessionStart context (Grok Build, #5467): stash it for the session's first tool\n   *  hook instead — see HookSpec.toolHook. */\n  deferContextToToolHook?: boolean;\n  /** Optional per-repo host registration, run once memory is confirmed LIVE for the repo (after\n   *  bank derivation and the opt-in/`disabled` gates). Returns an optional user-facing banner\n   *  hint (registration maintenance is host business, its absence a host problem) and must never\n   *  throw. TraeCode uses this to keep `<repo>/.trae/mcp.json` registering its MCP server and to\n   *  nudge when the workspace-MCP gate hides it (core/traecode-mcp.ts). */\n  ensureMcpRegistration?: (cwd: string) => string | undefined;\n}\n\n/**\n * Build this session's additionalContext: (maybe) kick off a background auto-seed of a cold repo\n * and (always, unless the hook is disabled) append the page bank mission. See module doc\n * for the tri-state cold check. Never throws.\n */\nexport async function buildSessionStartContext(args: {\n  cwd: string;\n  /** Where the session started — see `sessionRootDir`. Same as `cwd` on a fresh session; they\n   *  differ on a resume, where the bank was resolved from the ORIGINAL root. */\n  sessionRoot?: string;\n  bankId: string;\n  cfg: Config;\n  client: SeedContextClient;\n  harness?: string;\n  stateDir?: string;\n  hasGit?: (dir: string) => boolean;\n  startSeed?: (repoDir: string, opts?: { limit?: number; harness?: string }) => void;\n  startSurvey?: typeof startCodebaseSurvey;\n  headSha?: (dir: string) => string | null;\n  commitsSince?: (dir: string, sinceSha: string) => number | null;\n  /** Registry key of the old Claude Code plugin still active for `cwd`; defaults to reading\n   *  Claude's plugin files, and only for the claude-code harness. */\n  detectLegacyPlugin?: (cwd: string) => string | undefined;\n}): Promise<SessionStartOutput> {\n  const { cwd, bankId, cfg, client, stateDir } = args;\n  const t0 = Date.now();\n  let cold: boolean | undefined; // undefined = not checked (autoSeed off / non-git / unreachable)\n  let gitDocIds: Set<string> | undefined; // the cold-check's doc set, reused by the banner's git note\n  let bankEmpty = false; // true only when the server confirmed the bank holds no documents\n  let deepening = false; // the background deepen engine was started, and configures the bank\n  const harness = args.harness ?? \"claude-code\";\n  const hasGit = args.hasGit ?? hasGitHistory;\n  const startSeed = args.startSeed ?? startBackgroundSeed;\n  const startSurvey = args.startSurvey ?? startCodebaseSurvey;\n  const resolveHeadSha = args.headSha ?? gitHeadSha;\n  const countCommitsSince = args.commitsSince ?? commitsSince;\n  // sessionRoot as well as cwd, so a stamped {gitProject} names the project the bank id does.\n  const retainStamp = () =>\n    buildRetainStamp(cfg, { directory: cwd, sessionRoot: args.sessionRoot, harness, bankId });\n\n  // Codebase-survey baseline (Option A): the bank is the only state, so the HEAD at the last survey\n  // is recorded IN the bank as a tiny `survey-baseline:<sha>` marker doc (tag source:survey-baseline;\n  // content = the bare sha so extraction yields no facts), mirroring the deepen engine's gitlog-head\n  // marker. The commit-count re-survey reads these back by tag.\n  const SURVEY_BASELINE_TAG = \"source:survey-baseline\";\n  const SURVEY_BASELINE_PREFIX = \"survey-baseline:\";\n  const recordSurveyBaseline = (sha: string): void => {\n    if (!client.retain) return; // minimal client (some tests) — nothing to record\n    try {\n      const stamp = retainStamp();\n      const content =\n        `🛰️ Hindsight is researching this codebase — survey started at commit ${sha.slice(0, 12)}. ` +\n        `(Internal marker: no memories are extracted from this document.)`;\n      const tags = [...new Set([...stamp.tags, SURVEY_BASELINE_TAG])];\n      // Fire-and-forget; Promise.resolve tolerates a non-Promise return (e.g. a test spy).\n      const retained = client.retain(\n        content,\n        \"hindsight codebase-survey baseline\",\n        `${SURVEY_BASELINE_PREFIX}${sha}`,\n        tags,\n        \"survey\",\n        // `retain` only sets metadata when it is truthy, so an empty stamp sends none.\n        { metadata: Object.keys(stamp.metadata).length ? stamp.metadata : undefined }\n      );\n      void Promise.resolve(retained).catch(() => {});\n    } catch {\n      /* best-effort — a failed baseline write never breaks SessionStart */\n    }\n  };\n\n  // The banner is USER-FACING and must ride `systemMessage` (the only hook field Claude Code\n  // renders in the terminal); `additionalContext` is model-only and would show the human nothing.\n  // The pages preamble is model context and stays in `additionalContext`.\n  let systemMessage: string | undefined;\n\n  if (cfg.autoSeed !== false) {\n    if (hasGit(cwd)) {\n      // The LIVE bank is the ONLY state (cold-check-wins): delete the bank and the next session is\n      // a true first-open — no client-side flags can contradict it. Opting out of memory is the\n      // `disabled` config field (global or per-harness), not a hidden state file.\n      {\n        let docIds: Set<string> | undefined;\n        try {\n          docIds = await client.listDocumentIds(\"source:git\", \"all_strict\");\n        } catch {\n          docIds = undefined; // server unreachable: transient — do nothing, try again next session\n        }\n\n        // No git documents is not the whole story: under `gitIngest: \"none\"` none are ever\n        // written, so a bank an earlier session already surveyed still reads as cold and every\n        // session would launch another survey (#5124). Its survey-baseline markers say otherwise\n        // — the same evidence the warm branch below reads. An unreadable marker list keeps the\n        // git-only answer.\n        let baselines: Set<string> | undefined;\n        if (docIds?.size === 0) {\n          baselines = await client\n            .listDocumentIds(SURVEY_BASELINE_TAG, \"all_strict\")\n            .catch(() => undefined);\n        }\n        cold = docIds !== undefined ? docIds.size === 0 && !baselines?.size : undefined;\n        gitDocIds = docIds;\n        // Only a CONFIRMED-empty bank defers the first-prompt reflect. A cold repo can sit in a\n        // bank that already holds memories (a shared bank, imported conversations), and a failed\n        // or missing probe proves nothing (#5209). Probed before the seed and the survey baseline\n        // below write their first documents.\n        if (cold === true && client.hasDocuments) {\n          bankEmpty = await client.hasDocuments().then(\n            (has) => !has,\n            () => false\n          );\n        }\n        if (docIds !== undefined) {\n          // ALWAYS fire the background deepen engine when the server is reachable — it is\n          // idempotent (per-bank lock, dedup by document id) and each run does only the missing\n          // work: cold seed, newly appeared conversations, the next per-commit diff batch. The\n          // one-time extras stay cold-gated below.\n          // Pass the ASKING harness through: without it deepen.js falls back to the config\n          // loader's harness default and misfiles this session's survey + git history into the\n          // wrong bank (e.g. `opencode::<project>` for a claude-code session). See #3247.\n          startSeed(cwd, { limit: cfg.seedLimit, harness });\n          deepening = true;\n          // Cold iff the bank has zero source:git docs and no survey baseline (an undefined result\n          // — server error — is NOT treated as cold; we never surveyed/noted on an unconfirmed-empty\n          // bank).\n          if (cold) {\n            if (cfg.codebaseSurvey !== false) {\n              // Run the survey under the current harness's own CLI only (none without a recipe).\n              const sha = resolveHeadSha(cwd);\n              const started = await startSurvey(cwd, {\n                harness: harness as SurveyHarness,\n                model: cfg.surveyModel,\n                budgetUsd: cfg.surveyBudgetUsd,\n                sha: sha ?? undefined,\n              });\n              if (started && sha) recordSurveyBaseline(sha);\n            }\n            diag(harness, \"seed_started\", { bank: bankId });\n          } else if (cfg.codebaseSurvey !== false && cfg.surveyRefreshCommits > 0) {\n            // WARM bank: re-run the survey once enough commits have accrued since the last one, so\n            // structural pages track an evolving architecture. Branch-robust: read the\n            // survey-baseline:<sha> markers and take the MIN reachable `sha..HEAD` count (= the most\n            // recent survey that's an ancestor of HEAD; dead-branch/rebased markers are unreachable →\n            // ignored). No reachable baseline yet (pre-feature bank, or all markers gone) => record\n            // HEAD as the baseline WITHOUT surveying (no surprise spend).\n            const sha = resolveHeadSha(cwd);\n            if (sha) {\n              const markers =\n                baselines ??\n                (await client\n                  .listDocumentIds(SURVEY_BASELINE_TAG, \"all_strict\")\n                  .catch(() => new Set<string>()));\n              const counts: number[] = [];\n              for (const id of markers) {\n                if (!id.startsWith(SURVEY_BASELINE_PREFIX)) continue;\n                const n = countCommitsSince(cwd, id.slice(SURVEY_BASELINE_PREFIX.length));\n                if (n !== null) counts.push(n);\n              }\n              const sinceLast = counts.length ? Math.min(...counts) : null;\n              // A baseline without FINDINGS means the surveyed agent died before ingesting (no\n              // CLI on PATH, budget kill) — the marker alone must not suppress retries forever.\n              const uploads = await client\n                .listDocumentIds(\"source:upload\", \"all_strict\")\n                .catch(() => new Set<string>());\n              const findingsAbsent =\n                counts.length > 0 && !SURVEY_DOC_IDS.some((id) => uploads.has(id));\n              if ((sinceLast !== null && sinceLast >= cfg.surveyRefreshCommits) || findingsAbsent) {\n                const started = await startSurvey(cwd, {\n                  harness: harness as SurveyHarness,\n                  model: cfg.surveyModel,\n                  budgetUsd: cfg.surveyBudgetUsd,\n                  sha,\n                });\n                if (started) {\n                  recordSurveyBaseline(sha);\n                  diag(harness, \"survey_refresh\", {\n                    bank: bankId,\n                    commits: sinceLast,\n                    retry: findingsAbsent,\n                  });\n                }\n              } else if (sinceLast === null) {\n                recordSurveyBaseline(sha); // first baseline, or reset after a rebase — no survey\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n\n  if (!deepening) {\n    // The deepen engine is what configures the bank; without it a session write-back would name a\n    // `conversation` strategy the bank does not have, and the server would extract it with its\n    // generic rules (CL-Bench: \"The user is working on Question 11\", \"The agent ran a query\").\n    await client\n      .configureBankSettings?.({\n        manage: cfg.manageBankConfig,\n        extractionMode: cfg.retainExtractionMode,\n        defaults: cfg.defaultBankConfig,\n      })\n      .catch(() => {}); // best-effort: an unreachable server is retried next session\n  }\n\n  let pages: PageRef[] = [];\n  try {\n    pages = parsePageList(await client.listPages());\n  } catch {\n    if (client.pagesSupported === false) {\n      diag(harness, \"pages_unavailable\", { bank: bankId });\n    }\n    /* fail-open preamble */\n  }\n  const additionalContext = buildPagesPreamble(pages, {\n    reflectOnNewGoals: cfg.autoInject !== \"reflect\",\n    extra: cfg.toolGuideExtra,\n  });\n  // An empty page roster is NOT an empty bank: a bank with memories and no pages still answers a\n  // reflect (#5209), so only the confirmed-empty probe above defers it.\n  const deferInitialReflect = bankEmpty;\n\n  // The banner shows on EVERY session — Hindsight's presence is part of the product, not a\n  // one-time setup note. Wording tracks the bank state: cold = \"learning\", else \"remembering\";\n  // warm banners also condense the syncStatus contract into a git-sync phrase.\n  let gitNote: string | undefined;\n  if (gitDocIds) {\n    gitNote = await gitSyncNote({\n      client,\n      cwd,\n      gitIds: gitDocIds,\n      mode: cfg.gitIngest,\n      cold: cold === true,\n    }).catch(() => undefined);\n  }\n  systemMessage = buildSeedBanner(bankId, cold === true, gitNote);\n\n  // The old per-agent plugin keeps running next to this one until the user removes it — say so\n  // where they will see it. Only Claude Code had that plugin.\n  const detectLegacy =\n    args.detectLegacyPlugin ?? (harness === \"claude-code\" ? detectLegacyClaudePlugin : undefined);\n  const legacyPlugin = detectLegacy?.(cwd);\n  if (legacyPlugin) {\n    systemMessage += `\\n${legacyClaudePluginWarning(legacyPlugin)}`;\n    diag(harness, \"legacy_plugin_active\", { plugin: legacyPlugin });\n  }\n\n  // ALWAYS record the session start (warm sessions used to log nothing — undebuggable).\n  diag(harness, \"session_start\", { bank: bankId, cold, pages: pages.length, ms: Date.now() - t0 });\n\n  return { systemMessage, additionalContext, deferInitialReflect };\n}\n\n/** Run one SessionStart hook invocation: stdin event in, (maybe) an additionalContext object on stdout. */\nexport async function runSessionStartHook(\n  spec: SessionStartHookSpec,\n  makeClient: (opts: ClientOpts) => SeedContextClient = (o) => new HindsightClient(o)\n): Promise<void> {\n  // Anti-recursion: the codebase survey's own headless claude session (core/survey.ts) sets this\n  // so its hooks are a no-op — it must not re-seed/re-survey its own survey session.\n  if (process.env.HINDSIGHT_DISABLE_HOOKS) return;\n\n  // Whole-body try/catch (unlike runHook/runRetainHook, which only guard individual steps): a\n  // throw here happens during session bootstrap, before the agent has done anything — more\n  // disruptive than a failure mid-prompt — so nothing in this function may ever escape it.\n  try {\n    const ev = readHookEvent(spec.harness);\n    if (!ev) return;\n    if (spec.accept && !spec.accept(ev)) return;\n    const { harness } = spec;\n    const { cwd: rawCwd, sessionId } = spec.parse(ev);\n    const cwd = rawCwd || process.cwd();\n\n    let cfg = loadConfig({ harness });\n    setLogLevel(cfg.logLevel);\n    syncCompanionSkill(harness); // keep the installed skill current with the package version\n    if (cfg.disabled) return;\n    // …and keep the package itself current. AFTER the disabled check, unlike the skill sync above:\n    // `disabled` means an inert plugin, and a network call plus a background npm install is not\n    // inert. It also keeps the two harness families symmetric — the plugin hosts never construct a\n    // RuntimeCore when disabled (harness/plugin-entry.ts), so they already skip this.\n    // Detached and rate-limited to once a day; the update lands for the NEXT session.\n    void maybeAutoUpdate(cfg);\n\n    // Recorded HERE, on the session's first hook, so every later hook of this session resolves the\n    // same bank however far the agent navigates (#3563).\n    const sessionRoot = sessionRootDir(harness, sessionId, cwd);\n    const derived = deriveBankIdOrSkip(cfg, cwd, harness, sessionRoot);\n    if (derived === null) return; // repository unidentifiable: no bank, no seed, no injection\n    const resolved = applyBankConfig(cfg, derived, cwd);\n    cfg = resolved.cfg;\n    const bankId = resolved.bankId;\n    if (cfg.disabled) return; // per-bank opt-out (banks.<id> override)\n    // Memory is live HERE — the one point where registering the host's per-repo MCP access is\n    // correct: the caller of an opt-out repo must not gain a config file it never asked for.\n    const mcpHint = spec.ensureMcpRegistration?.(cwd);\n    // Daemon mode: warm it up now, before the user has typed anything. The start itself is\n    // detached; we wait only briefly, so an already-running daemon is adopted immediately while a\n    // cold one keeps coming up in the background and is picked up by a later turn.\n    await ensureDaemon(cfg, harness, { waitMs: DAEMON_WAIT_SESSION_START_MS });\n    const client = makeClient({\n      apiUrl: cfg.apiUrl,\n      apiToken: cfg.apiToken,\n      bank: bankId,\n      maxParallelRetains: cfg.maxParallelRetains,\n      observationScopes: cfg.observationScopes,\n    });\n\n    const out = await buildSessionStartContext({ cwd, sessionRoot, bankId, cfg, client, harness });\n    // The registration's banner hint (e.g. TraeCode's workspace-MCP gate) rides the same\n    // user-facing message as the legacy-plugin warning — the banner is the only visible channel.\n    if (mcpHint)\n      out.systemMessage = out.systemMessage ? `${out.systemMessage}\\n${mcpHint}` : mcpHint;\n    if (out.deferInitialReflect && sessionId) {\n      writeSessionCache(sessionCacheFile(harness, sessionId), { deferInitialReflect: true });\n    }\n    if (spec.deferContextToToolHook && out.additionalContext && sessionId) {\n      stashPendingContext(harness, sessionId, out.additionalContext);\n      out.additionalContext = undefined;\n    }\n    // The lifecycle computes one host-neutral output; the registry owns each host's wire schema.\n    const payload = spec.emit(out);\n    if (out.systemMessage || out.additionalContext) {\n      process.stdout.write(JSON.stringify(payload));\n    }\n  } catch {\n    /* SessionStart must never throw and break the session */\n  }\n}\n"
