    {
      "path": "hindsight-integrations/coding-agents/src/core/hindsight.ts",
      "content": "/**\n * Harness-agnostic Hindsight HTTP client (raw fetch, no SDK dep).\n *\n * Every harness adapter and the backfill CLI go through this one client: it configures the bank\n * (missions + git/chat retain strategies), retains memories, reflects, drains async operations, and\n * creates pages. Nothing here knows about opencode/claude-code/etc.\n */\nimport {\n  type BankOverrides,\n  buildPageTrigger,\n  codingBankManifest,\n  type CustomPagesConfig,\n  type CurrentPageTrigger,\n  PAGE_MAX_TOKENS,\n  pagesFor,\n  type PagesConfig,\n  pageScopeRule,\n  type PageTrigger,\n  pageTriggerDrifted,\n  pageTriggerFor,\n  pageTriggerPatch,\n  type RetainExtractionMode,\n} from \"./missions\";\nimport { version as PKG_VERSION } from \"../../package.json\";\nimport { pool, semverGte, sleep } from \"./util\";\nimport type { RetainStamp } from \"./retain-stamp\";\n\n/** Sent on every request so the server can tell which integration is calling. */\nexport const USER_AGENT = `hindsight-coding-agents/${PKG_VERSION}`;\n\n/** One node of GET /pages/tree. Only the fields this client reads. */\nexport interface PageNode {\n  id: string;\n  kind: \"folder\" | \"page\";\n  name: string;\n  /** The page's source query (OKF `description`) — what a re-sync compares against. */\n  description?: string;\n  /** The page's EFFECTIVE refresh policy, on servers new enough to report it (#3572). Absent\n   *  everywhere else, which `seedPages()` reads as \"unknown, leave it alone\". */\n  trigger?: CurrentPageTrigger;\n  children?: PageNode[];\n}\n\n/**\n * How consolidation scopes the observations a retained memory feeds (`observation_scopes` on the\n * retain API). The scalar modes are the server's; a `string[][]` declares the scopes explicitly.\n */\nexport type ObservationScopes =\n  | \"shared\"\n  | \"combined\"\n  | \"per_tag\"\n  | \"all_combinations\"\n  | \"per_source\"\n  | string[][];\n\n/**\n * `per_source` is resolved HERE, per document, and never reaches the server: it expands to the\n * global scope plus one named for that document's own `source:` tag.\n *\n * It cannot be expressed as configuration. The server treats an explicit scope list as\n * unconditional — consolidation returns it verbatim without filtering it against the memory's own\n * tags — so a configured `[[], [\"source:git\"], [\"source:chat\"]]` writes EVERY document into all\n * three, and the `source:git` scope fills up with beliefs built from chat transcripts. Only a\n * per-document decision separates \"what the commits say\" from \"what was discussed\".\n *\n * `per_tag` would split on the right axis but also on every other one: it reinstates the per-agent\n * `harness:` fork that `shared` exists to prevent, and any volatile tag (a session id in\n * `retainTags`) becomes its own scope, which is the fragmentation bug itself. Reading only\n * `source:` is what keeps this safe.\n *\n * A document may carry more than one source tag — the commit-message seed is both `source:git` and\n * `source:git-log`, because the cold-repo check filters on `source:git` — so every distinct one\n * gets a scope. Taking all of them, sorted, is the only rule that needs no arbitrary tie-break and\n * does not silently depend on the order the caller assembled its tags in.\n *\n * The empty scope is always first and always present, so the untagged observations that page\n * pages read (they match with `tags_match: \"all\"`) keep being written exactly as under `shared`.\n */\nexport function resolveRetainScopes(\n  tags: string[] | undefined,\n  configured: ObservationScopes\n): ObservationScopes {\n  if (configured !== \"per_source\") return configured;\n  const sources = [...new Set((tags ?? []).filter((t) => t.startsWith(\"source:\")))].sort();\n  return [[], ...sources.map((s) => [s])];\n}\n\n/**\n * One global scope for everything this plugin writes.\n *\n * The server default (`combined`) scopes an observation to the memory's WHOLE tag set, and every\n * document we write carries provenance tags — `source:chat`, `harness:<id>`, `knowledge:<kind>`,\n * anything from `retainTags`. That splits one repository's knowledge into a separate observation\n * set per tag combination: work the same repo with two agents and the harness tag alone gives two\n * parallel sets of beliefs that never merge, each blind to the other, at double the consolidation\n * cost (#3564). Those tags are provenance — they say who wrote a memory, not which project the\n * belief is about — so they belong on the facts (where they still filter recall) and not on the\n * consolidation boundary. `shared` keeps them on the facts and consolidates into ONE untagged\n * scope per bank, which is what a bank already is: one project's memory.\n */\nexport const DEFAULT_OBSERVATION_SCOPES: ObservationScopes = \"shared\";\n\nexport interface ClientOpts {\n  apiUrl: string;\n  apiToken?: string;\n  bank: string;\n  /** Repository this bank is about, named in every page query this client writes\n   *  (`pageScopeRule`). Undefined when no single repository is (a shared static bank, a path map, a\n   *  bank several repos are renamed onto) — the query then gets the shared-bank clause, which\n   *  names no project (#4490). Must be a property of the bank and never of the calling session's\n   *  cwd: see `bankProjectName` (#4146). */\n  project?: string;\n  log?: (msg: string) => void;\n  /** Cap on concurrent retain-related requests (drain op polls, deepen pools). Default 10. */\n  maxParallelRetains?: number;\n  /** Observation scoping for every retain this client sends. Default `DEFAULT_OBSERVATION_SCOPES`. */\n  observationScopes?: ObservationScopes;\n  /** Pages one page search returns. Default `DEFAULT_PAGE_SEARCH_LIMIT`. Lives on the\n   *  client so every caller — the hook's injection and the MCP tool — shares one value. */\n  pageSearchLimit?: number;\n  /** Recall-body overrides, merged key-by-key over `DEFAULT_RECALL_OPTIONS`. Passed through to\n   *  the API as given (`types`, `max_tokens`, `budget`, …); `query` is never overridable. */\n  recallOptions?: Record<string, unknown>;\n  /** Re-read the bearer token from the LIVE config, for hosts that outlive their credential.\n   *  `apiToken` alone is a construction-time snapshot: a long-lived host (dsh, Cline, Kilo, the\n   *  MCP server, any persistent plugin) kept signing with it forever, so enabling auth or rotating\n   *  the key mid-session 401'd every call until the host restarted (#3600). Consulted only on a\n   *  401, so the happy path never touches the filesystem. See `core/host-client.ts`. */\n  tokenProvider?: () => string | undefined;\n  /** How long one request may spend waiting out rate limits (HTTP 429) before it throws\n   *  `RateLimitedError`. Default 0: a hook answers to its host's deadline and must fail fast.\n   *  Background work that has nobody waiting on it (deepen) sets this, because a 429 it does not\n   *  wait out is an item missing from the bank — deepen used to log \"failed to enqueue\" and carry\n   *  on, dropping about a third of a repo's chats against a rate-limited Hindsight Cloud. */\n  rateLimitPatienceMs?: number;\n}\n\nexport interface RetainOpts {\n  timestamp?: string; // when the content occurred (temporal ranking)\n  metadata?: Record<string, string>; // source provenance (returned with recalls)\n  /** \"append\" concatenates `content` onto the stored document instead of replacing it — the whole\n   *  point of the live write-back cursor (core/retain-cursor.ts). Requires a document_id. */\n  updateMode?: \"append\";\n  /** Deterministic operation id: re-submitting the same payload returns the original operation\n   *  instead of admitting a second one. Ignored by servers older than 0.8.6. */\n  operationId?: string;\n}\n\n/** First release whose retain endpoint honours a caller-supplied `operation_id` (#2937, v0.8.6).\n *  Below it the field is silently ignored — unknown request fields are not rejected — so an append\n *  could be applied twice without us ever knowing. Hence: no idempotency, no append. */\nexport const MIN_IDEMPOTENT_RETAIN_VERSION = \"0.8.6\";\n\n/**\n * Raised when the API rate-limits a request (HTTP 429), carrying how long it asked us to wait.\n *\n * A plain Error would be indistinguishable from a 500 or a network fault, and those want opposite\n * treatment: a rate limit is a \"not now, ask again\" that the caller can honour, while a server\n * error is not worth hammering. Callers that have somewhere safe to wait retry; the rest fail as\n * before.\n */\nexport class RateLimitedError extends Error {\n  readonly code = \"rate_limited\";\n  constructor(readonly retryAfterMs: number) {\n    super(`rate limited; retry after ${Math.round(retryAfterMs / 1000)}s`);\n    this.name = \"RateLimitedError\";\n  }\n}\n\n/** Parse a `Retry-After` header (delta-seconds or HTTP-date) into ms; 0 when absent or unusable. */\nexport function retryAfterMs(header: string | null | undefined): number {\n  if (!header) return 0;\n  const secs = Number(header.trim());\n  if (Number.isFinite(secs) && secs >= 0) return secs * 1000;\n  const at = Date.parse(header);\n  return Number.isNaN(at) ? 0 : Math.max(0, at - Date.now());\n}\n\n/** Raised when the target server predates the pages API surface. */\nexport class PagesUnavailableError extends Error {\n  readonly code = \"pages_unavailable\";\n  constructor() {\n    super(\"Hindsight server does not support pages\");\n    this.name = \"PagesUnavailableError\";\n  }\n}\n\n/**\n * Does this 404 mean the server has no pages API, rather than \"that bank does not exist yet\"?\n *\n * The two are indistinguishable by status, and conflating them latched the page capability\n * off for the whole process on the FIRST session in a new bank — the bank is minted by the first\n * retain, so a session-start page read always precedes it (#4607).\n *\n * It matches the ENDPOINT-missing shape (FastAPI answers an unrouted path with exactly\n * `{\"detail\":\"Not Found\"}`), deliberately NOT the bank-missing wording. Matching the bank error\n * instead would hang the fix on a message the API is free to rephrase, and the day it did, #4607\n * would come back with no test failing. This way a reworded bank error simply fails to match: the\n * capability stays unknown and the next call retries, which is the safe direction to be wrong in.\n */\nasync function isEndpointMissing(r: Response): Promise<boolean> {\n  try {\n    // Consumes the body, which is safe: every 404 caller below returns without reading it.\n    const j = (await r.json()) as { detail?: unknown };\n    return (\n      String(j?.detail ?? \"\")\n        .trim()\n        .toLowerCase() === \"not found\"\n    );\n  } catch {\n    // No JSON body at all (a proxy's HTML/plain-text 404, a bare gateway response). This used to\n    // latch, but a reverse proxy answers exactly this while the backend restarts, and the latch\n    // never expires — pages stayed off for the life of the process (#5071). Only our\n    // API's own JSON 404 is a verdict; anything else leaves the capability unknown, so the next\n    // call asks again.\n    return false;\n  }\n}\n\n/**\n * A `/pages` sub-path as the URL to request. `legacy` gives its pre-rename `/knowledge-base` twin,\n * which a server from before the rename serves instead: there the page routes themselves sat\n * under `/knowledge-base/pages`, while tree/folders/search/export/nodes sat directly below\n * `/knowledge-base`. Remove in 2.x.\n */\nfunction pagesPath(sub: string, legacy = false): string {\n  if (!legacy) return `/pages${sub}`;\n  return /^\\/(tree|folders|search|export|nodes)\\b/.test(sub)\n    ? `/knowledge-base${sub}`\n    : `/knowledge-base/pages${sub}`;\n}\n\nconst TERMINAL = new Set([\"completed\", \"failed\", \"cancelled\", \"error\"]);\n\n/** Default cap on concurrent retain-related requests; configurable via `maxParallelRetains`. */\n/**\n * A reflect that failed on the SERVER's side of the wire: our deadline expired or the server\n * answered non-2xx. `status` is undefined for a timeout. Transport errors (connection refused,\n * DNS) are NOT wrapped — they mean the server is unreachable, so no other endpoint would answer\n * either.\n */\nexport class ReflectError extends Error {\n  constructor(\n    message: string,\n    readonly status: number | undefined,\n    readonly timedOut: boolean,\n    options?: ErrorOptions\n  ) {\n    super(message, options);\n    this.name = \"ReflectError\";\n  }\n\n  /** A timeout or a 5xx means reflect's synthesis (the slow LLM path) broke, while the cheap\n   *  retrieval endpoints may still answer — worth falling back. A 4xx will fail the same way on\n   *  every endpoint (auth, missing bank), so it is not. */\n  get fallbackEligible(): boolean {\n    return this.timedOut || (this.status !== undefined && this.status >= 500);\n  }\n\n  /** A 4xx the next attempt would get again (bad key, missing bank, rejected body) — retrying it\n   *  only spends another doomed call (#5207). 408/429 are \"not now\", so they stay retryable. */\n  get permanent(): boolean {\n    const s = this.status;\n    return s !== undefined && s >= 400 && s < 500 && s !== 408 && s !== 429;\n  }\n}\n\nexport const DEFAULT_MAX_PARALLEL_RETAINS = 10;\n/** Pages returned by one search — the hook's injection and the agent-facing\n *  `hindsight_search_pages` tool both get this, so tuning it moves both.\n *\n *  Ten, not three. Three was set when the page roster was injected wholesale and search was a\n *  rarely-used fallback; search is now the way in, and a repo's pages are narrow by design, so the\n *  decision one turn needs is routinely split across two of them (\"Pricing decisions\" AND\n *  \"Conventions\") and a three-hit cut drops one. Ten snippets is a few hundred tokens on a call the\n *  agent made deliberately. */\nexport const DEFAULT_PAGE_SEARCH_LIMIT = 10;\n/**\n * The recall body this client sends when `recallOptions` overrides nothing — one object rather\n * than a field per parameter, so a new recall parameter needs no plumbing here.\n *\n * Observations are the consolidated layer, so they are the best answer per token; a bank whose\n * consolidation is off never grows any, and recalling only observations there returns nothing.\n * Such a bank sets `{\"types\": [\"world\", \"experience\"]}`, or `{\"types\": null}` for every type.\n * The budget stays low and entities are excluded because this runs inside a hook window.\n */\nexport const DEFAULT_RECALL_OPTIONS: Record<string, unknown> = {\n  types: [\"observation\"],\n  budget: \"low\",\n  max_tokens: 2000,\n  include: { entities: null },\n};\n\n/** How long drain() pauses between poll cycles when the API did not rate-limit (429). */\nconst POLL_CYCLE_MS = 5000;\n\n/** Consecutive 5xx polls after which drain() gives an operation up as failed. A blip recovers in\n *  one or two cycles; a server answering 5xx for this long (~1 min at the 5s cycle) is not going to\n *  report that op's status, and polling it for the rest of the hour only hides it (#5080). */\nconst POLL_MAX_SERVER_ERRORS = 12;\n\n/** Minimum backoff after a 429 that carried no (or a shorter) Retry-After. */\nconst RETRY_AFTER_FLOOR_MS = 10 * 1000;\n\n/**\n * Ceiling on a single backoff, however long `Retry-After` asks for.\n *\n * The header is a server's hint, not a budget we owe it: a large value (an incident, a\n * misconfigured limiter, a proxy inventing one) would otherwise park a drain for as long as it\n * says — up to the whole `maxMs`, with the background seed frozen behind it. Capping keeps the\n * signal without handing over the schedule; if the limit still applies, the next poll simply gets\n * another 429 and backs off again.\n */\nconst RETRY_AFTER_CEILING_MS = 60 * 1000;\n\n/** First wait when a request is rate-limited and `Retry-After` asks for less (Cloud sends \"0\"),\n *  doubled per attempt up to RETRY_AFTER_CEILING_MS. Jittered, so a pool of workers that all got\n *  the 429 together does not come back together. */\nconst RATE_LIMIT_BACKOFF_MS = 1000;\n\n/**\n * What the agent gets back from reading one page.\n *\n * The API returns `body` AND `markdown`, where `markdown` is that same body with YAML frontmatter\n * on top — so passing the response straight through handed the model the entire page twice, on\n * every read. `timestamp` goes out as `last_updated_at`: the value is the page's last refresh, and\n * a bare \"timestamp\" beside a page tells the model nothing about whether it is looking at something\n * current.\n *\n * Applied inside `getPage`, not by the read tool: it used to live in page-tools, which left\n * `getPage` itself returning both copies to any other caller (#4836).\n */\nfunction shapePage(page: unknown): unknown {\n  const p = (page ?? {}) as Record<string, unknown>;\n  const body = typeof p.body === \"string\" && p.body.trim() ? p.body : p.markdown;\n  return {\n    id: p.id,\n    name: p.name,\n    ...(p.description ? { description: p.description } : {}),\n    ...(Array.isArray(p.tags) && p.tags.length ? { tags: p.tags } : {}),\n    ...(p.timestamp ? { last_updated_at: p.timestamp } : {}),\n    body,\n  };\n}\n\n/** Undici's cross-version handle on the dispatcher Node's global `fetch` uses. */\nconst GLOBAL_DISPATCHER = Symbol.for(\"undici.globalDispatcher.1\");\n\n/**\n * The global dispatcher with undici's own header/body timeouts switched off, for a request that\n * already carries an AbortSignal deadline — or undefined where there is nothing to wrap.\n *\n * Node's fetch applies a 300s `headersTimeout` below our signal, so a reflect configured above\n * 300s (`reflectToolTimeoutMs` defaults to 330s, past the server's own reflect wall) died with\n * UND_ERR_HEADERS_TIMEOUT before the server could answer (#5504). Composing over the CURRENT\n * global dispatcher, instead of building a new undici `Agent`, needs no `undici` dependency (the\n * bundled one is not importable) and keeps any proxy dispatcher the host installed. Hosts whose\n * fetch is not undici's (Bun, DSH's own) have no such dispatcher and ignore the option.\n */\nfunction signalOnlyDispatcher(): unknown {\n  // Node loads undici — which installs the global dispatcher — lazily. Touching the `Headers`\n  // global loads it; touching `fetch` does not (it is a wrapper until first called).\n  void globalThis.Headers;\n  const d = (globalThis as Record<symbol, unknown>)[GLOBAL_DISPATCHER] as\n    | { compose?: (interceptor: unknown) => unknown }\n    | undefined;\n  if (typeof d?.compose !== \"function\") return undefined; // Node 18's undici predates compose()\n  type Dispatch = (opts: Record<string, unknown>, handler: unknown) => boolean;\n  return d.compose(\n    (dispatch: Dispatch) => (opts: Record<string, unknown>, handler: unknown) =>\n      dispatch({ ...opts, headersTimeout: 0, bodyTimeout: 0 }, handler)\n  );\n}\n\nexport class HindsightClient {\n  readonly apiUrl: string;\n  /** The credential the NEXT request will sign with — NOT the one the config file holds. The two\n   *  diverge exactly when #3600 bites, which is why `hindsight_diagnose` reports both. */\n  private token: string | undefined;\n  private readonly tokenProvider?: () => string | undefined;\n  readonly bank: string;\n  readonly project?: string;\n  readonly opIds: string[] = []; // async operation ids collected by retain(), for drain()\n  /** Tri-state capability probe: unknown until the first page request, then cached. */\n  pagesSupported: boolean | undefined;\n  /** Tri-state capability probe: unknown until the first append-mode retain, then cached. */\n  private idempotentRetain: boolean | undefined;\n  private readonly log: (msg: string) => void;\n  readonly maxParallelRetains: number;\n  readonly observationScopes: ObservationScopes;\n  readonly pageSearchLimit: number;\n  readonly recallOptions: Record<string, unknown>;\n  private readonly rateLimitPatienceMs: number;\n\n  constructor(o: ClientOpts) {\n    this.apiUrl = o.apiUrl.replace(/\\/$/, \"\");\n    this.token = o.apiToken;\n    this.tokenProvider = o.tokenProvider;\n    this.bank = o.bank;\n    this.project = o.project;\n    this.log = o.log ?? (() => {});\n    this.maxParallelRetains = o.maxParallelRetains || DEFAULT_MAX_PARALLEL_RETAINS;\n    this.observationScopes = o.observationScopes ?? DEFAULT_OBSERVATION_SCOPES;\n    this.pageSearchLimit = o.pageSearchLimit || DEFAULT_PAGE_SEARCH_LIMIT;\n    // Merged once here, not per call, and copied rather than aliased: the default is a\n    // module-level object, and handing every client the same reference makes one caller's\n    // mutation everyone's.\n    this.recallOptions = { ...DEFAULT_RECALL_OPTIONS, ...o.recallOptions };\n    this.rateLimitPatienceMs = o.rateLimitPatienceMs ?? 0;\n  }\n\n  /** The credential in use, for diagnostics. Never log or report the VALUE — booleans only. */\n  get apiToken(): string | undefined {\n    return this.token;\n  }\n\n  private headers(): Record<string, string> {\n    // `identity`: the server gzips bodies >= 1 KB, and some hosts (DSH runs plugins on its own\n    // fetch) hand back the compressed bytes undecoded, so `.json()` dies on the gzip magic (#4868).\n    const h: Record<string, string> = {\n      \"Content-Type\": \"application/json\",\n      \"Accept-Encoding\": \"identity\",\n      \"User-Agent\": USER_AGENT,\n    };\n    if (this.token) h[\"Authorization\"] = `Bearer ${this.token}`;\n    return h;\n  }\n\n  /** Re-read the credential from the live config. Returns whether it actually CHANGED — a retry is\n   *  only worth sending if it did, so a genuinely wrong key still surfaces as one 401 rather than\n   *  doubling every failing request. */\n  private refreshToken(): boolean {\n    if (!this.tokenProvider) return false;\n    let next: string | undefined;\n    try {\n      next = this.tokenProvider();\n    } catch {\n      return false; // a half-written config file must never drop the last credential that worked\n    }\n    if (next === this.token) return false;\n    this.token = next;\n    return true;\n  }\n\n  /**\n   * The ONE place a request is signed. Every fetch goes through it — the generic `req`, the drain\n   * poll and `reflect` — because a 401 recovery wired into only one of them leaves the others\n   * failing forever, which is how #3600 read from the outside: hooks worked, in-session tools did\n   * not.\n   *\n   * On a 401 the credential is re-resolved and the request replayed ONCE (its body is already a\n   * string, so replay is exact). A 401 means the server did nothing, so replaying is side-effect\n   * free even for retain. The retry shares the caller's `signal`, deliberately: one deadline still\n   * bounds the whole call.\n   */\n  private async fetchWithAuth(url: string, init: RequestInit): Promise<Response> {\n    // Only a request with its own deadline drops undici's timeouts; the drain poll has none.\n    const dispatcher = init.signal ? signalOnlyDispatcher() : undefined;\n    const send = () =>\n      fetch(url, { ...init, headers: this.headers(), ...(dispatcher ? { dispatcher } : {}) });\n    const r = await send();\n    if (r.status !== 401 || !this.refreshToken()) return r;\n    return send();\n  }\n\n  /** A 401 with no `Authorization` header is a different failure from a rejected key, and the\n   *  server answers identically for both — only the client knows which it sent. */\n  private authHint(status: number): string {\n    if (status !== 401) return \"\";\n    return this.token\n      ? \" (the configured apiToken was rejected — check ~/.hindsight/coding-agent.json)\"\n      : \" (no apiToken is configured, so no Authorization header was sent)\";\n  }\n\n  bankUrl(suffix = \"\"): string {\n    return `${this.apiUrl}/v1/default/banks/${encodeURIComponent(this.bank)}${suffix}`;\n  }\n\n  /** `tolerate` adds statuses that are returned to the caller instead of thrown (404 always is). */\n  async req(\n    method: string,\n    url: string,\n    body?: unknown,\n    tolerate: number[] = [],\n    timeoutMs = 15_000\n  ): Promise<Response> {\n    // Hard cap on EVERY request: a stalled server (pool deadlock, network) must degrade to a\n    // memoryless turn — never hang a host that awaits us (opencode blocks its BOOT on plugin init).\n    const payload = body ? JSON.stringify(body) : undefined;\n    let r: Response;\n    for (let attempt = 0, waited = 0; ; attempt++) {\n      r = await this.fetchWithAuth(url, {\n        method,\n        body: payload,\n        signal: AbortSignal.timeout(timeoutMs),\n      });\n      if (r.status !== 429 || tolerate.includes(429)) break;\n      const asked = retryAfterMs(r.headers.get(\"retry-after\"));\n      const backoff = Math.min(RETRY_AFTER_CEILING_MS, RATE_LIMIT_BACKOFF_MS * 2 ** attempt);\n      const wait =\n        Math.min(RETRY_AFTER_CEILING_MS, Math.max(asked, backoff)) * (1 + Math.random() / 2);\n      if (waited + wait > this.rateLimitPatienceMs) throw new RateLimitedError(asked);\n      await sleep(wait);\n      waited += wait;\n    }\n    if (!r.ok && r.status !== 404 && !tolerate.includes(r.status))\n      throw new Error(\n        `${method} ${url} -> ${r.status} ${await r.text()}${this.authHint(r.status)}`\n      );\n    return r;\n  }\n\n  /** Retain one memory. ALWAYS async: enqueue extraction server-side and collect its op-id for\n   *  drain(). Nothing in this plugin can afford to block a coding agent's hook on extraction. */\n  async retain(\n    content: string,\n    context: string,\n    documentId: string,\n    tags: string[],\n    strategy: string,\n    opts: RetainOpts = {}\n  ): Promise<void> {\n    const item: Record<string, unknown> = {\n      content,\n      context,\n      document_id: documentId,\n      tags,\n      strategy,\n      // Sent on EVERY retain, including the server default `combined`, so the scoping a bank's\n      // observations were built under is a property of the write rather than of whichever server\n      // version happened to process it. Servers older than 0.4.15 ignore the field.\n      observation_scopes: resolveRetainScopes(tags, this.observationScopes),\n    };\n    if (opts.timestamp) item.timestamp = opts.timestamp;\n    if (opts.metadata) item.metadata = opts.metadata;\n    if (opts.updateMode) item.update_mode = opts.updateMode;\n    const body: Record<string, unknown> = { items: [item], async: true };\n    if (opts.operationId) body.operation_id = opts.operationId;\n    const r = await this.req(\"POST\", this.bankUrl(\"/memories\"), body);\n    try {\n      const j = (await r.json()) as { operation_id?: string };\n      if (j.operation_id) this.opIds.push(j.operation_id);\n    } catch {\n      /* ignore */\n    }\n  }\n\n  /**\n   * Whether this server honours `operation_id` on an async retain, and can therefore be appended to\n   * safely (see MIN_IDEMPOTENT_RETAIN_VERSION). Probed via the version endpoint; anything\n   * unreachable, unparseable or older answers \"no\", which costs efficiency, never correctness.\n   * Only a \"yes\" is cached: a long-lived plugin client would otherwise keep replacing for the rest\n   * of the process after one probe that hit a restarting server (#5735).\n   */\n  async supportsIdempotentRetain(): Promise<boolean> {\n    if (this.idempotentRetain) return true;\n    const supported = await this.probeIdempotentRetain();\n    if (supported || this.idempotentRetain === undefined) {\n      this.log(`server retain idempotency: ${supported ? \"supported\" : \"unavailable\"}`);\n    }\n    this.idempotentRetain = supported;\n    return supported;\n  }\n\n  /** `/v1/version` first: an ingress that routes only `/v1` to the API (the Helm chart's default)\n   *  hands a bare `/version` to the control plane, whose HTML 404 or login redirect read as \"no\",\n   *  so append silently never turned on (#5286). Servers that predate the alias still answer\n   *  `/version`, so that stays as the fallback. */\n  private async probeIdempotentRetain(): Promise<boolean> {\n    for (const path of [\"/v1/version\", \"/version\"]) {\n      try {\n        const r = await this.req(\"GET\", `${this.apiUrl}${path}`);\n        if (!r.ok) continue;\n        const j = (await r.json()) as { api_version?: string };\n        return semverGte(j.api_version, MIN_IDEMPOTENT_RETAIN_VERSION);\n      } catch {\n        /* unreachable or not our API's JSON — try the next path */\n      }\n    }\n    return false;\n  }\n\n  /**\n   * Whether a session write-back may use `update_mode=\"append\"`: the server must dedupe by\n   * `operation_id` AND the bank must keep document text, or the server rejects the append in the\n   * background (#4613). Only an explicit `store_document_text: false` answers \"no\" — an unreachable\n   * or unparseable config assumes the default (stored), so a flaky probe never downgrades appends.\n   */\n  async supportsAppendRetain(): Promise<boolean> {\n    if (!(await this.supportsIdempotentRetain())) return false;\n    try {\n      const r = await this.req(\"GET\", this.bankUrl(\"/config\"));\n      if (!r.ok) return true;\n      const j = (await r.json()) as { config?: { store_document_text?: boolean } };\n      return j.config?.store_document_text !== false;\n    } catch {\n      return true;\n    }\n  }\n\n  /**\n   * Every document_id currently in the bank under a strategy tag (e.g. `source:git`), paginated into a\n   * Set. Powers the incremental git-sync's \"what's already ingested?\" check — since git commits are stored\n   * with document_id `git:<sha>`, the returned Set lets a caller diff a ref's commits against memory.\n   */\n  async listDocumentIds(\n    tag: string,\n    tagsMatch: \"all\" | \"all_strict\" = \"all\"\n  ): Promise<Set<string>> {\n    const ids = new Set<string>();\n    const limit = 500;\n    for (let offset = 0; ; offset += limit) {\n      const q = `?tags=${encodeURIComponent(tag)}&tags_match=${tagsMatch}&limit=${limit}&offset=${offset}`;\n      const r = await this.req(\"GET\", this.bankUrl(`/documents${q}`));\n      let items: { id?: string }[] = [];\n      let total = 0;\n      try {\n        const j = (await r.json()) as { items?: { id?: string }[]; total?: number };\n        items = j.items || [];\n        total = j.total ?? 0;\n      } catch {\n        break;\n      }\n      for (const it of items) if (it.id) ids.add(it.id);\n      if (items.length < limit || ids.size >= total) break; // last page reached\n    }\n    return ids;\n  }\n\n  /**\n   * The tags on one document, or undefined when the bank holds none with that id. Read from the\n   * document LISTING narrowed by `q` (a substring match on the id, so the exact id is picked out of\n   * the page) rather than GET /documents/{id}, which also sends the document's full text: the\n   * caller, the git-log freshness check on SessionStart, reads a ~100k-character document for one tag.\n   */\n  async documentTags(documentId: string): Promise<string[] | undefined> {\n    const limit = 100;\n    for (let offset = 0; ; offset += limit) {\n      const q = `?q=${encodeURIComponent(documentId)}&limit=${limit}&offset=${offset}`;\n      const r = await this.req(\"GET\", this.bankUrl(`/documents${q}`));\n      const j = (await r.json()) as { items?: { id?: string; tags?: string[] }[]; total?: number };\n      const items = j.items ?? [];\n      const hit = items.find((it) => it.id === documentId);\n      if (hit) return hit.tags ?? [];\n      if (items.length < limit || offset + limit >= (j.total ?? 0)) return undefined;\n    }\n  }\n\n  /** Whether the bank holds any document at all — a one-row listing. A bank that does not exist\n   *  yet (404) holds none; any other failure throws, so a caller can tell \"empty\" from \"unknown\". */\n  async hasDocuments(): Promise<boolean> {\n    const r = await this.req(\"GET\", this.bankUrl(\"/documents?limit=1\"));\n    if (r.status === 404) return false;\n    const j = (await r.json()) as { items?: unknown[]; total?: number };\n    return (j.total ?? j.items?.length ?? 0) > 0;\n  }\n\n  /** Configure the bank: POST the coding bank manifest to /import (missions, retain strategies,\n   *  entity labels), then seed pages when the server supports them. Both halves are\n   *  idempotent and ADDITIVE — nothing the bank already says is overwritten (#3927), bar the\n   *  extraction mode of the plugin's own strategies, which follows its config (#4560) — so\n   *  the deepen engine can re-run this every pass. Creates the bank if missing; legacy servers\n   *  continue with the template-only path.\n   *\n   *  `manage: false` skips the config half entirely, for a bank whose owner shapes it themselves.\n   *  That bank should then define the strategies this plugin writes under (`git`, `gitlog`,\n   *  `conversation`, `document`, `survey`): an unknown strategy name is not an error server-side,\n   *  it just falls back to the bank's own config, so the miss is silent. */\n  async configureBank(\n    opts: {\n      reset?: boolean;\n      pageTrigger?: PageTrigger;\n      /** Which pages to seed and with what query — see RawConfig.pages. */\n      pages?: PagesConfig;\n      /** Pages of the user's own to seed alongside them — see RawConfig.customPages. */\n      customPages?: CustomPagesConfig;\n      manage?: boolean;\n      /** Extraction mode for the plugin's own strategies — see RawConfig.retainExtractionMode. */\n      extractionMode?: RetainExtractionMode;\n      /** Bank-config fields to add where the bank is silent — see RawConfig.defaultBankConfig. */\n      defaults?: Record<string, unknown>;\n    } = {}\n  ): Promise<void> {\n    if (opts.reset) {\n      await this.req(\"DELETE\", this.bankUrl());\n      this.log(`[bank] reset ${this.bank}`);\n    }\n    await this.configureBankSettings(opts);\n    await this.seedPages(opts.pageTrigger, opts.pages, opts.customPages);\n  }\n\n  /** The config half of `configureBank` (missions, retain strategies, entity labels), without\n   *  seeding pages. Session start calls it directly when the deepen engine — the usual caller of\n   *  `configureBank` — will not run (`autoSeed: false`, or a directory with no git history):\n   *  without it such a bank never got the `conversation` strategy, and every session write-back\n   *  was extracted with the server's generic rules instead of the plugin's mission. */\n  async configureBankSettings(\n    opts: {\n      reset?: boolean;\n      manage?: boolean;\n      extractionMode?: RetainExtractionMode;\n      defaults?: Record<string, unknown>;\n    } = {}\n  ): Promise<void> {\n    if (opts.manage === false) {\n      this.log(`[bank] manageBankConfig: false — leaving ${this.bank}'s configuration alone`);\n    } else {\n      // What the bank ALREADY overrides decides what is left to write: the missions are seeded once\n      // and then belong to whoever set them (#2492), and every other field is added only where the\n      // bank is silent (#3927) — bar the extraction mode of the plugin's own strategies, which is\n      // re-synced to `extractionMode` (#4560). A reset just deleted the bank, so there is nothing to read.\n      const manifest = codingBankManifest(\n        opts.reset ? undefined : await this.readBankOverrides(),\n        opts.extractionMode,\n        opts.defaults\n      );\n      if (!manifest) {\n        this.log(`[bank] ${this.bank} already carries the coding structure — nothing to apply`);\n      } else {\n        await this.req(\"POST\", this.bankUrl(\"/import\"), manifest);\n        this.log(`[bank] applied to ${this.bank}: ${Object.keys(manifest.bank).sort().join(\", \")}`);\n      }\n    }\n  }\n\n  /**\n   * This bank's own config OVERRIDES, or undefined when there are none to read.\n   *\n   * Deliberately the overrides and not the resolved config: an inherited global default is not\n   * something this bank's owner chose, so it must not read as \"already set\". `undefined` means the\n   * bank does not exist yet, or the deployment has the bank-config API switched off — in neither\n   * case can anything have been customised, so the caller seeds the full template.\n   */\n  private async readBankOverrides(): Promise<BankOverrides | undefined> {\n    try {\n      const r = await this.req(\"GET\", this.bankUrl(\"/config\"));\n      if (!r.ok) return undefined;\n      const j = (await r.json()) as { overrides?: BankOverrides };\n      return j.overrides ?? {};\n    } catch {\n      return undefined;\n    }\n  }\n\n  /** Explicitly delete one document (and its cascaded memory units/links). Background sync must\n   *  never use this as a cleanup primitive: a document id alone does not prove repository ownership. */\n  async deleteDocument(documentId: string): Promise<void> {\n    await this.req(\"DELETE\", this.bankUrl(`/documents/${encodeURIComponent(documentId)}`));\n  }\n\n  /** Count of operations still ACTIVE on this bank — the list includes terminal ops (completed/\n   *  failed/cancelled), so filter by status. Powers syncStatus's \"extractions drained\" check. */\n  async activeOperations(): Promise<number> {\n    const r = await this.req(\"GET\", this.bankUrl(\"/operations\"));\n    try {\n      const j = (await r.json()) as {\n        operations?: { status?: string }[];\n        items?: { status?: string }[];\n      };\n      const ops = j.operations ?? j.items ?? [];\n      return ops.filter((o) => !TERMINAL.has((o?.status || \"\").toLowerCase())).length;\n    } catch {\n      return 0;\n    }\n  }\n\n  /**\n   * Poll each enqueued operation by id until terminal. LIST only shows active ops, so per-id GET is reliable.\n   *\n   * Concurrency is capped at `maxParallelRetains` (the API rate-limits bursts, not single\n   * requests — a 200 to a lone GET with 429s under `Promise.all` over every pending op). A 429\n   * leaves the op pending and backs the next cycle off by its `Retry-After` (10s floor) instead\n   * of hammering the next cycle 5s later.\n   */\n  async drain(ids: string[], label: string, maxMs = 60 * 60 * 1000): Promise<void> {\n    if (!ids.length) return;\n    this.log(`[wait] draining ${ids.length} ${label} operations …`);\n    const start = Date.now();\n    const pending = new Set(ids);\n    const serverErrors = new Map<string, number>();\n    let failed = 0;\n    const giveUp = (id: string, status: number): void => {\n      pending.delete(id);\n      failed++;\n      this.log(`  … ${label} op ${id} -> HTTP ${status}, counted as failed`);\n    };\n    while (pending.size && Date.now() - start < maxMs) {\n      // Cycle backoff: default 5s; any 429 in the cycle raises it to the longest Retry-After seen\n      // (floor 10s) so a rate-limited API gets room to recover before the next poll round.\n      let backoffMs = POLL_CYCLE_MS;\n      await pool([...pending], this.maxParallelRetains, async (id) => {\n        try {\n          const r = await this.fetchWithAuth(this.bankUrl(`/operations/${id}`), { method: \"GET\" });\n          if (r.status === 429) {\n            backoffMs = Math.min(\n              RETRY_AFTER_CEILING_MS,\n              Math.max(backoffMs, RETRY_AFTER_FLOOR_MS, retryAfterMs(r.headers.get(\"retry-after\")))\n            );\n            return; // op stays pending — retried after the backoff\n          }\n          // Any other non-OK used to just `return`, leaving the op pending for the whole maxMs:\n          // a 403/404 (auth drift, vanished op or bank) was polled for an hour (#5080). A 4xx\n          // will answer the same next cycle, so it is terminal now; a 5xx gets a bounded run.\n          if (r.status >= 500) {\n            const n = (serverErrors.get(id) ?? 0) + 1;\n            serverErrors.set(id, n);\n            if (n >= POLL_MAX_SERVER_ERRORS) giveUp(id, r.status);\n            return;\n          }\n          if (!r.ok) return giveUp(id, r.status);\n          serverErrors.delete(id);\n          const st = (((await r.json()) as { status?: string }).status || \"\").toLowerCase();\n          if (TERMINAL.has(st)) {\n            pending.delete(id);\n            if (st !== \"completed\") failed++;\n          }\n        } catch {\n          /* transient — retry next cycle */\n        }\n      });\n      if (pending.size) {\n        this.log(`  … ${pending.size}/${ids.length} ${label} ops pending`);\n        await sleep(backoffMs);\n      }\n    }\n    this.log(\n      `[wait] ${label} drained — ${ids.length - pending.size} done, ${failed} failed` +\n        (pending.size ? `, ${pending.size} still pending at timeout` : \"\")\n    );\n  }\n\n  /**\n   * Reflect: synthesized, root-cause answer over the bank. Bounded so a slow server never hangs a\n   * caller — but `timeoutMs` is REQUIRED, deliberately: the right deadline differs by an order of\n   * magnitude between the automatic hook (20s, to fit the host's window) and the agent-invoked\n   * tool (minutes, on a populated bank). This used to default to 120s, which silently overrode the\n   * tool's configured window and aborted every high-budget synthesis mid-flight (#3590).\n   */\n  async reflect(query: string, opts: { budget?: string; timeoutMs: number }): Promise<string> {\n    const ctrl = new AbortController();\n    const timer = setTimeout(() => ctrl.abort(), opts.timeoutMs);\n    try {\n      const resp = await this.fetchWithAuth(this.bankUrl(\"/reflect\"), {\n        method: \"POST\",\n        body: JSON.stringify({ query, budget: opts.budget ?? \"high\" }),\n        signal: ctrl.signal,\n      });\n      // Keep the server's body: a bare \"reflect 500\" in the diag trail is undebuggable after the fact.\n      if (!resp.ok)\n        throw new ReflectError(\n          `reflect ${resp.status} ${(await resp.text()).slice(0, 1000)}${this.authHint(resp.status)}`,\n          resp.status,\n          false\n        );\n      const data = (await resp.json()) as { text?: string };\n      return (data.text || \"\").trim();\n    } catch (e) {\n      // Our own deadline surfaces as a generic \"This operation was aborted\"; name it.\n      if (ctrl.signal.aborted)\n        throw new ReflectError(`reflect timed out after ${opts.timeoutMs}ms`, undefined, true, {\n          cause: e,\n        });\n      throw e;\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n\n  /**\n   * Raw recall with no LLM in the loop, so it still answers when reflect's synthesis times out or\n   * 5xxs. The body is `recallOptions` (consolidated observations by default) — a bank that grows\n   * no observations widens it rather than getting nothing back. Returns the texts in rank order.\n   *\n   * The name predates `recallOptions` (the observation type used to be hardcoded here) and is\n   * kept deliberately: this is the client's published surface, so renaming it would break\n   * importers for a cosmetic gain. The doc above is the contract, not the name.\n   */\n  async recallObservations(query: string, opts: { timeoutMs: number }): Promise<string[]> {\n    const r = await this.req(\n      \"POST\",\n      this.bankUrl(\"/memories/recall\"),\n      // `query` is applied AFTER the spread: everything else is the caller's to override, but a\n      // config that could replace the goal with a fixed string would silently recall for the\n      // wrong question on every turn.\n      { ...this.recallOptions, query },\n      [],\n      opts.timeoutMs\n    );\n    if (r.status === 404) return [];\n    const j = (await r.json()) as { results?: { text?: string }[] };\n    return (j.results ?? []).map((x) => (x.text ?? \"\").trim()).filter(Boolean);\n  }\n\n  /** Set once a server answered on the deprecated `/knowledge-base/...` paths: one from before the\n   *  page routes moved to `/pages/...`. Remove in 2.x. */\n  private legacyPagesPaths = false;\n\n  /**\n   * Request a page endpoint by its `/pages` sub-path (`\"\"`, `/tree`, `/<id>`, `/nodes/<id>`, …).\n   *\n   * Returns `null` — and latches `pagesSupported = false` — iff the endpoint is really absent: an\n   * unrouted 404 on the `/pages` path AND on its pre-rename `/knowledge-base` twin, which a server\n   * older than the rename still serves (tried once, then remembered). A bank-not-found 404 is NOT\n   * a capability verdict — it is the expected answer before the bank's first retain — so it is\n   * returned as-is and never caches a negative (#4607). A 404's body may already be consumed.\n   *\n   * Only 404 is tested: `req` throws on every other non-ok status it was not told to tolerate, so\n   * the 405/501 this used to check for never reach a caller in the first place.\n   */\n  private async pagesReq(\n    method: string,\n    sub: string,\n    body?: unknown,\n    tolerate: number[] = [],\n    timeoutMs?: number\n  ): Promise<Response | null> {\n    const send = (legacy: boolean) =>\n      this.req(method, this.bankUrl(pagesPath(sub, legacy)), body, tolerate, timeoutMs);\n    let r = await send(this.legacyPagesPaths);\n    if (r.status !== 404 || !(await isEndpointMissing(r))) return r;\n    if (!this.legacyPagesPaths) {\n      r = await send(true);\n      if (r.status !== 404 || !(await isEndpointMissing(r))) {\n        this.legacyPagesPaths = true;\n        return r;\n      }\n    }\n    this.pagesSupported = false;\n    return null;\n  }\n\n  /**\n   * The bank's page tree (folders + pages, nested). The tree carries names, source\n   * queries and staleness but NOT synthesized content, so it is cheap enough to poll.\n   */\n  async tree(): Promise<PageNode[]> {\n    if (this.pagesSupported === false) throw new PagesUnavailableError();\n    const r = await this.pagesReq(\"GET\", \"/tree\");\n    if (!r) throw new PagesUnavailableError();\n    // Bank not created yet: it genuinely has no pages, and the capability stays UNKNOWN so the\n    // next call (after the first retain mints the bank) asks again instead of short-circuiting.\n    if (r.status === 404) return [];\n    this.pagesSupported = true;\n    try {\n      return ((await r.json()) as { roots?: PageNode[] }).roots ?? [];\n    } catch {\n      return [];\n    }\n  }\n\n  /**\n   * List pages (ids + names only — no synthesized content), flattened out of the tree\n   * and shaped as `{items:[…]}` for `parsePageList`. Folders are dropped: they carry no content\n   * to read, and a caller enumerating pages wants leaves, not structure.\n   *\n   * NOTE the ids are page node ids (`kp-…`), NOT the backing mental-model ids. Every\n   * page read/update in this client goes through the same page ids, so a page id from\n   * here, from `searchPages`, or from a `[[page:<id>]]` link all resolve identically.\n   */\n  async listPages(): Promise<unknown> {\n    const items: { id: string; name: string; description?: string; folder?: string }[] = [];\n    const walk = (nodes: PageNode[], folder?: string): void => {\n      for (const n of nodes) {\n        if (!n?.id || !n?.name) continue;\n        if (n.kind === \"page\") {\n          items.push({\n            id: n.id,\n            name: n.name,\n            ...(n.description ? { description: n.description } : {}),\n            ...(folder ? { folder } : {}),\n          });\n        }\n        if (n.children?.length) walk(n.children, n.kind === \"folder\" ? n.name : folder);\n      }\n    };\n    walk(await this.tree());\n    return { items };\n  }\n\n  /**\n   * Read one page's synthesized content by page id, shaped by `shapePage` so\n   * the body arrives once. The endpoint omits the internal reflect trace that built\n   * the page — that is 70-95% of the raw bytes and can blow past an MCP host's per-tool-result\n   * token cap.\n   */\n  async getPage(pageId: string): Promise<unknown> {\n    if (this.pagesSupported === false) throw new PagesUnavailableError();\n    const r = await this.pagesReq(\"GET\", `/${encodeURIComponent(pageId)}`);\n    if (!r) throw new PagesUnavailableError();\n    if (r.status === 404) throw new Error(`page not found: ${pageId}`);\n    return shapePage(await r.json());\n  }\n\n  /** Hybrid (BM25 + vector, RRF-fused) server-side search over the bank's pages.\n   *  Returns page-level hits with a relevance snippet — the real search behind\n   *  hindsight_search_pages. */\n  async searchPages(\n    query: string,\n    opts: { limit?: number; timeoutMs?: number } = {}\n  ): Promise<\n    { id: string; name: string; source_query?: string; snippet: string; score: number }[]\n  > {\n    if (this.pagesSupported === false) throw new PagesUnavailableError();\n    const q = `?q=${encodeURIComponent(query)}&limit=${opts.limit ?? this.pageSearchLimit}`;\n    const r = await this.pagesReq(\"GET\", `/search${q}`, undefined, [], opts.timeoutMs);\n    // Routed through the same check as every other page endpoint. Without it a server with no\n    // pages API parsed its own 404 body into zero hits and reported \"nothing matched\"\n    // forever, which reads as an empty bank rather than a missing feature.\n    if (!r) throw new PagesUnavailableError();\n    if (r.status === 404) return []; // bank not created yet — no pages to match\n    const j = (await r.json()) as {\n      results?: {\n        id: string;\n        name: string;\n        source_query?: string | null;\n        snippet?: string;\n        score?: number;\n      }[];\n    };\n    return (j.results ?? []).map((x) => ({\n      id: x.id,\n      name: x.name,\n      ...(x.source_query ? { source_query: x.source_query } : {}),\n      snippet: x.snippet ?? \"\",\n      score: x.score ?? 0,\n    }));\n  }\n\n  /**\n   * Seed the fixed page taxonomy as pages at the tree root, idempotently.\n   *\n   * Matched by NAME, not id: `POST /pages` mints its own `kp-…` id, so a stable\n   * client-chosen id isn't available to match on (unlike the old mental-model path, which keyed\n   * off a slug). Names are unique per folder server-side, which makes them a sound key.\n   *\n   * An existing page is PATCHed rather than recreated so a plugin upgrade that rewords a\n   * `source_query` re-syncs onto the live page instead of orphaning its synthesized content —\n   * which is how `pageScopeRule`'s repo name reaches banks seeded by an earlier version.\n   */\n  async seedPages(\n    pageTrigger: PageTrigger = buildPageTrigger(),\n    pagesConfig: PagesConfig = {},\n    customPages: CustomPagesConfig = {}\n  ): Promise<void> {\n    // No project = a bank no single repository owns: the shared-bank clause. Pages seeded under the\n    // old bank-named clause drift from it and are PATCHed below, which rebuilds them (#4490).\n    const pages = pagesFor(this.project, pagesConfig, customPages);\n    const existing = new Map<string, PageNode>();\n    let roots: PageNode[];\n    try {\n      roots = await this.tree();\n    } catch (e) {\n      if (e instanceof PagesUnavailableError) {\n        this.log(`[bank] pages unavailable on ${this.apiUrl}; continuing without them`);\n        return;\n      }\n      throw e;\n    }\n    for (const n of roots) {\n      if (n.kind === \"page\" && n.name) existing.set(n.name.toLowerCase(), n);\n    }\n    let created = 0;\n    let updated = 0;\n    let vanished = 0; // deleted under us mid-run — neither re-synced nor unchanged\n    for (const page of pages) {\n      const hit = existing.get(page.name.toLowerCase());\n      const body = {\n        name: page.name,\n        source_query: page.source_query,\n        tags: page.tags,\n        max_tokens: PAGE_MAX_TOKENS,\n        // Resolved HERE, not in `buildPageTrigger`: a hashed cron (`H`) needs the page's identity,\n        // and one trigger is built per session for all of them.\n        trigger: pageTriggerFor(pageTrigger, this.bank, page.name),\n      };\n      if (!hit) {\n        // 409 = another deepen run seeded this name between our tree read and this POST. That is\n        // the outcome we wanted anyway, so tolerate it rather than failing the whole run.\n        const r = await this.pagesReq(\"POST\", \"\", body, [409]);\n        if (!r) {\n          this.log(`[bank] pages unavailable on ${this.apiUrl}; continuing without them`);\n          return;\n        }\n        if (r.status === 404) {\n          this.log(`[bank] ${this.bank} does not exist yet; pages seed on the next session`);\n          return;\n        }\n        if (r.status !== 409) created++;\n      } else {\n        const sourceDrift = hit.description !== page.source_query;\n        // Older servers omit trigger from the tree, so an absent value means unknown rather\n        // than drift. Those servers also reject a trigger-only PATCH as an empty update.\n        const triggerDrift = hit.trigger != null && pageTriggerDrifted(hit.trigger, body.trigger);\n        if (!sourceDrift && !triggerDrift) continue;\n\n        // The name IS the match key, so it can't drift; the source query and the trigger can.\n        // The trigger is re-sent on ANY difference in the policy this plugin states — the refresh\n        // schedule included, not just `tags_match` as before — because that is the only way a\n        // changed default reaches a bank that was seeded under the old one (the hourly staggered\n        // schedule that replaced auto-refresh would otherwise apply to new repos only). The\n        // config is therefore the source of truth for these pages: a trigger edited in the\n        // control plane is re-synced back on the next session, and a repo that wants a different\n        // policy sets `pageTriggerType`/`pageTriggerCron`. Servers that do not report a page's\n        // trigger leave its policy unknown; source-query drift can still be reconciled safely.\n        const patch: { trigger?: PageTrigger; source_query?: string; tags?: string[] } = {};\n        if (sourceDrift) {\n          patch.source_query = page.source_query;\n          patch.tags = page.tags;\n          // Say so. This replaces a query edited through the API or the control plane, which used\n          // to happen silently and read as the edit never having saved (#4460).\n          this.log(\n            `[bank] re-syncing \"${page.name}\" to its configured source_query — set ` +\n              `pages[${JSON.stringify(page.name)}].source_query to keep your own wording`\n          );\n        }\n        // The page's OWN resolved trigger (a hashed cron differs per page), not the shared one.\n        if (triggerDrift) patch.trigger = pageTriggerPatch(body.trigger);\n        const r = await this.pagesReq(\"PATCH\", `/nodes/${encodeURIComponent(hit.id)}`, patch);\n        if (!r) {\n          this.log(`[bank] pages unavailable on ${this.apiUrl}; continuing without them`);\n          return;\n        }\n        // The node vanished under us (a concurrent delete). Skip it — the remaining pages are\n        // still worth syncing, and the run's summary line is still worth logging.\n        if (r.status === 404) {\n          vanished++;\n          continue;\n        }\n        updated++;\n      }\n    }\n    const initiatives = await this.resyncInitiativeTriggers(roots, pageTrigger);\n    this.log(\n      `[bank] pages seeded on ${this.bank} (scoped to ${this.project ?? \"the shared bank\"}): ` +\n        `${created} created, ${updated} re-synced, ` +\n        `${pages.length - created - updated - vanished} unchanged` +\n        (vanished ? `, ${vanished} deleted under us` : \"\") +\n        (initiatives ? `, ${initiatives} initiative pages re-synced` : \"\")\n    );\n  }\n\n  /**\n   * Bring the captured initiative pages onto the same refresh policy as the seeded taxonomy.\n   *\n   * `captureInitiative` stamps this very trigger when it creates a page, so on a bank seeded under\n   * an older default they are the same drift as the taxonomy — and on a real repo they are most of\n   * it: five taxonomy pages against one page per initiative, each an LLM synthesis per\n   * consolidation under the auto-refresh that used to be the default (#3506).\n   *\n   * Their `name` and `source_query` are written once, from the initiative's own title, and\n   * re-stating either would rebuild a page whose question never changed. The one exception is\n   * the scope clause: a page captured while the clause named the BANK is scoped to a project no\n   * memory is about and comes out empty (#4490), so exactly that clause is swapped for the current\n   * one — the rest of the query, the user's wording included, is kept. The tree read above is\n   * reused rather than re-fetched.\n   */\n  private async resyncInitiativeTriggers(\n    roots: PageNode[],\n    pageTrigger: PageTrigger\n  ): Promise<number> {\n    const folder = roots.find(\n      (n) => n.kind === \"folder\" && (n.name || \"\").toLowerCase() === \"initiatives\"\n    );\n    const bankScope = pageScopeRule(this.bank);\n    let updated = 0;\n    for (const page of folder?.children ?? []) {\n      if (page.kind !== \"page\") continue;\n      const patch: { trigger?: PageTrigger; source_query?: string } = {};\n      const query = page.description?.replace(bankScope, pageScopeRule(this.project));\n      if (query !== page.description) patch.source_query = query;\n      // No trigger reported = policy unknown, not divergent (a server older than #3572).\n      if (page.trigger != null) {\n        const desired = pageTriggerFor(pageTrigger, this.bank, page.name);\n        if (pageTriggerDrifted(page.trigger, desired)) patch.trigger = pageTriggerPatch(desired);\n      }\n      if (!patch.trigger && !patch.source_query) continue;\n      const r = await this.pagesReq(\"PATCH\", `/nodes/${encodeURIComponent(page.id)}`, patch);\n      // 404 only: `req` throws on every other non-ok status it was not told to tolerate, so the\n      // 405/501 this used to test for never arrive (see `pagesReq`). No latch here — a\n      // node that has gone missing says nothing about the server's capabilities, and nothing about\n      // the pages after it either, so skip it rather than abandoning the rest of the re-sync (this\n      // `break`ed while the status still carried a server-wide meaning). If it is the BANK that\n      // went rather than one node, this costs one wasted PATCH per initiative page instead of one\n      // total — bounded by the folder's size, and the next session re-syncs from scratch anyway.\n      if (!r || r.status === 404) continue;\n      updated++;\n    }\n    return updated;\n  }\n\n  /** URL/id-safe slug: lowercase, non-alphanumerics → \"-\", trim dashes, cap length; fallback \"initiative\". */\n  private slugify(s: string): string {\n    return (\n      s\n        .toLowerCase()\n        .replace(/[^a-z0-9]+/g, \"-\")\n        .replace(/^-+|-+$/g, \"\")\n        .slice(0, 60) || \"initiative\"\n    );\n  }\n\n  /**\n   * Active-path capture: register a major feature as a per-initiative page + a marker memory.\n   * New initiative → creates a page under the Initiatives folder.\n   * Update (relatesToPageId) → no new page; only a marker accruing to the existing page, so an\n   * enhancement or a mid-work plan change lands on the initiative it belongs to.\n   *\n   * The marker carries its page id in two places, neither of them a tag (#3641):\n   * `metadata.relatedPageId` for provenance (visible on the document, and to a reflect loop that\n   * expands one), and a `[[page:<id>]]` link in the retain CONTEXT, which is the only one of the\n   * three channels a page synthesis actually reads — reflect's search results keep `context` and\n   * `tags` but strip `metadata` (`_UNREAD_RESULT_FIELDS`), and the id has no business in a tag\n   * vocabulary that exists to be matched with exact set-ops.\n   */\n  async captureInitiative(args: {\n    title: string;\n    summary: string;\n    relatesToPageId?: string;\n    stamp?: RetainStamp;\n    /** Same refresh policy as the seeded pages — an initiative page is one of them, and used to\n     *  carry its own hardcoded copy of this trigger. */\n    pageTrigger?: PageTrigger;\n  }): Promise<{ page_id: string }> {\n    // `POST /pages` mints its OWN page id (kp-…); we can't set it. So for a new initiative\n    // we create the page first and adopt the server-assigned id — that id is what the return value\n    // and the marker must use, or `hindsight_read_page(id)` 404s and the `[[page:<id>]]` link\n    // points at nothing.\n    let pageId = args.relatesToPageId;\n    if (!pageId) {\n      const folderId = await this.ensureFolder(\"Initiatives\");\n      // Same subject scoping and budget as the seeded pages: an initiative page synthesizes from\n      // the same bank, which also holds facts about the dependencies this repo merely uses, and\n      // \"the project's memory\" alone never said WHICH project (#3476). `max_tokens` is stated for\n      // the same reason `seedPages` states it — leaving it implicit pins these pages to whatever\n      // the server's page default happens to be, which is only coincidentally PAGE_MAX_TOKENS.\n      const r = await this.pagesReq(\"POST\", \"\", {\n        name: args.title,\n        source_query:\n          `Summarize the \"${args.title}\" initiative: what is being built or changed and why, ` +\n          `and its current state — drawn from the project's memory.` +\n          pageScopeRule(this.project),\n        parent_id: folderId,\n        tags: [\"knowledge:feature-work\"],\n        max_tokens: PAGE_MAX_TOKENS,\n        trigger: pageTriggerFor(args.pageTrigger ?? buildPageTrigger(), this.bank, args.title),\n      });\n      try {\n        const j = (await r?.json()) as { page_id?: string; id?: string } | undefined;\n        pageId = j?.page_id ?? j?.id;\n      } catch {\n        /* fall through to the slug fallback below */\n      }\n      pageId ||= `initiative-${this.slugify(args.title)}`; // last resort if the response lacked an id\n    }\n    // \"Update\", not \"Enhancement\": a recapture is just as often a plan change (scope/goal/why\n    // rewritten) as an addition, and this string is what the page synthesis reads.\n    const verb = args.relatesToPageId ? \"Update to an existing initiative\" : \"New initiative\";\n    const content = `${verb}: ${args.title}. ${args.summary}`;\n    // A STABLE id per initiative, so a recapture upserts instead of adding one more document every\n    // call (#5076). Keyed on the page, not the title — a recapture may reword it — and two slots:\n    // the creation marker keeps what the initiative set out to do, the update marker holds the\n    // latest plan change (a newer update supersedes the older one).\n    const markerId = `initiative-marker-${this.slugify(pageId)}${args.relatesToPageId ? \"-update\" : \"\"}`;\n    const tags = [...new Set([...(args.stamp?.tags ?? []), \"knowledge:feature-work\"])];\n    // The context rides on every fact extracted from this marker, verbatim (ExtractedFact.context),\n    // so the Initiatives overview can link an initiative to its own page from what it retrieved.\n    const context = `initiative marker for [[page:${pageId}]]`;\n    await this.retain(content, context, markerId, tags, \"document\", {\n      metadata: { ...(args.stamp?.metadata ?? {}), relatedPageId: pageId },\n    });\n    return { page_id: pageId };\n  }\n\n  /** Find a root folder by name (case-insensitive) or create it; returns its id. Fail-open to undefined. */\n  async ensureFolder(name: string): Promise<string | undefined> {\n    try {\n      const r = await this.pagesReq(\"GET\", \"/tree\");\n      const tree = (await r?.json()) as\n        | { roots?: { id?: string; kind?: string; name?: string }[] }\n        | undefined;\n      const hit = (tree?.roots || []).find(\n        (n) => n.kind === \"folder\" && (n.name || \"\").toLowerCase() === name.toLowerCase()\n      );\n      if (hit?.id) return hit.id;\n    } catch {\n      /* fall through to create */\n    }\n    try {\n      const r = await this.pagesReq(\"POST\", \"/folders\", { name });\n      return ((await r?.json()) as { id?: string } | undefined)?.id;\n    } catch {\n      return undefined;\n    }\n  }\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/missions.ts",
      "content": "/**\n * Harness-agnostic Hindsight missions, retain strategies, and page taxonomy.\n *\n * These describe HOW a coding project's memory is extracted and reasoned over. They are independent\n * of which agent harness produced the sessions, so they live in the shared core and are reused by\n * every harness adapter.\n */\n\nimport { createHash } from \"node:crypto\";\n\n// ── retain missions (git vs chat need different extraction) ─────────────────────\nexport const GIT_MISSION =\n  \"You are ingesting a single git commit: its message and its full diff. Extract the concrete \" +\n  \"technical DECISION and the CAUSE/INVARIANT it encodes, bound to the specific code entities \" +\n  \"(functions, methods, files) and behaviors it changes. Preserve exact identifiers, paths, and \" +\n  \"literal values verbatim. Preserve the 'REF-ID: <token>' marker verbatim in every fact. Capture \" +\n  \"both WHAT changed and WHY. Issue/PR references (#123, GH-123, PROJ-123) are load-bearing: keep \" +\n  \"them VERBATIM in the fact text and emit each as an ENTITY, so a later question about that issue \" +\n  \"or PR retrieves this decision.\";\n\nexport const GITLOG_MISSION =\n  \"You are ingesting an aggregated block of git commit MESSAGES ONLY (no diffs) — the project's \" +\n  \"recent commit-message history, oldest first. Extract the project's INITIATIVES, FEATURES, \" +\n  \"ENHANCEMENTS, and notable changes or THEMES over time — what the project has been working on and \" +\n  \"how it has evolved. Do NOT extract per-line code detail (there is no diff to draw it from). Group \" +\n  \"related commits into a coherent initiative/theme where the messages make that clear; preserve exact \" +\n  \"identifiers and literal values verbatim when quoting a subject line. Keep issue/PR references \" +\n  \"(#123, GH-123) VERBATIM and emit each as an ENTITY — they are how future sessions will ask about \" +\n  \"this work.\";\n\nexport const CONVERSATION_MISSION =\n  \"You are ingesting a developer conversation as a JSONL transcript (one {role, content} turn per line): the \" +\n  \"user's requests, the assistant's narration, and compact 'action' turns naming each tool use and \" +\n  'its target (e.g. \"Edit boltons/strutils.py\") with no arguments or outputs. It may be a SHORT ' +\n  \"decision chat or a LONG working session — scale the facts to the substance, never to the message \" +\n  \"count. Extract the FEWEST facts that capture the OUTCOME: the settled DECISIONS and their exact \" +\n  \"rules/values (quote literals VERBATIM); concrete CHANGES to specific code entities; problems and \" +\n  \"how they were resolved; conventions or invariants established; at most one fact for a notable \" +\n  \"REJECTED alternative ('initially proposed X, changed to Y because Z'). A short decision chat \" +\n  \"usually yields 1-2 facts; a substantial working session several. CRITICAL: a conversation REVISES \" +\n  \"itself — record ONLY the FINAL state as what is in effect; a superseded proposal appears ONLY \" +\n  \"inside the rejected fact, NEVER as its own 'decided' fact; if the same setting changes several \" +\n  \"times keep only the LAST, and make unmistakably clear which choice WON. Do NOT emit one fact per \" +\n  \"message, per intermediate proposal, or per action turn. Keep issue/PR references (#123, GH-123) \" +\n  \"VERBATIM and emit each as an ENTITY. Preserve the 'REF-ID: <token>' marker \" +\n  \"verbatim in every fact. When the session checked its work (a test passed or failed, a result was \" +\n  \"judged right or wrong), record the exact METHOD behind that outcome — which file, table, column, \" +\n  \"command or formula — and any caveat the session found in the data or code (a column mostly empty, a \" +\n  \"value in other units), so the same work repeats what worked and avoids what failed. Do not invent; \" +\n  \"capture only what was actually settled.\";\n\nexport const REFLECT_MISSION =\n  \"You are a debugging assistant with the project's past decisions in memory (git rationale and \" +\n  \"developer chats). Given a bug's SYMPTOM, find the past decision whose rationale explains the ROOT \" +\n  \"CAUSE — not one that merely shares vocabulary. Answer with the PRECISE fix: state the EXACT rule \" +\n  \"and the LITERAL values, identifiers, strings, numbers, or set members that were decided — quote \" +\n  \"them VERBATIM, never paraphrase, generalize, or omit them (give the actual decided value, not \" +\n  \"'the project standard'). If memories CONFLICT on the same rule, the LATEST decision wins — \" +\n  \"prefer facts that explicitly amend or supersede an earlier one, state the superseded rule as \" +\n  \"no longer in effect, and never present it as the fix. Name the function/file to change and \" +\n  \"cite the REF-ID(s). If NOTHING in memory genuinely explains THIS symptom, say exactly that in \" +\n  \"one short sentence — a wrong-but-confident nearest match is worse than an honest miss; never \" +\n  \"stretch an unrelated decision to fit.\";\n\nexport const DOCUMENT_MISSION =\n  \"You are ingesting a standalone document (notes, docs, or structural findings). Extract the \" +\n  \"concrete facts, concepts, and structure it describes.\";\n\nexport const OBSERVATIONS_MISSION =\n  \"Consolidate durable knowledge about THIS codebase — recurring patterns, conventions, module \" +\n  \"responsibilities, and how components relate — from the ingested commits and conversations. \" +\n  \"Favor stable structural understanding over one-off details. When a new fact contradicts or \" +\n  \"supersedes an existing observation, UPDATE that observation to reflect the current state rather \" +\n  \"than creating a sibling alongside it; note that the rule was revised and when, so the superseded \" +\n  \"version is visible as history rather than as a competing claim.\";\n\n/** Extraction modes the plugin can run its own strategies under (`custom` needs instructions the\n *  plugin does not have, so it is not offered). */\nexport const RETAIN_EXTRACTION_MODES = [\"concise\", \"verbose\", \"verbatim\", \"chunks\"] as const;\nexport type RetainExtractionMode = (typeof RETAIN_EXTRACTION_MODES)[number];\n/** `concise`, not `verbose`: every Stop writes the session back, so the mode is paid per turn, and\n *  verbose made one active Claude Code session cost ~$150/hr on Cloud (#4560). */\nexport const DEFAULT_RETAIN_EXTRACTION_MODE: RetainExtractionMode = \"concise\";\n\nexport const RETAIN_STRATEGIES = {\n  git: { retain_mission: GIT_MISSION, retain_extraction_mode: DEFAULT_RETAIN_EXTRACTION_MODE },\n  // ONE big aggregated document (last N commit messages, no diffs) -> a larger chunk size so it stays\n  // in as few chunks as possible and the extractor sees the whole history arc at once.\n  gitlog: {\n    retain_mission: GITLOG_MISSION,\n    retain_extraction_mode: DEFAULT_RETAIN_EXTRACTION_MODE,\n    retain_chunk_size: 12000,\n  },\n  // ONE strategy for ALL developer conversations — backfilled decision chats and live working\n  // sessions alike (they are the same content type in the same JSON transcript format; the mission\n  // scales extraction to the substance, final-state-wins). Chunk big enough to hold a whole typical\n  // conversation in ONE chunk so the extractor sees the full proposal→revision arc (the 3000\n  // default SPLIT them into per-chunk fragments); very long sessions still split and fall back to\n  // the consolidation layer.\n  conversation: {\n    retain_mission: CONVERSATION_MISSION,\n    retain_extraction_mode: DEFAULT_RETAIN_EXTRACTION_MODE,\n    retain_chunk_size: 12000,\n  },\n  // Structural documents (e.g. the codebase survey's ingested findings) aren't dialogue — the\n  // chat strategy's \"final decision vs rejected proposal\" extraction doesn't apply. A bigger chunk\n  // size (documents can run long) keeps the concrete facts/structure together instead.\n  document: {\n    retain_mission: DOCUMENT_MISSION,\n    retain_extraction_mode: DEFAULT_RETAIN_EXTRACTION_MODE,\n    retain_chunk_size: 12000,\n  },\n  // Codebase-SURVEY lifecycle documents, ONE strategy with conditional rules: the survey's\n  // internal status markers (\"researching…\"/\"completed\" baselines) must yield ZERO memories,\n  // while any actual survey findings routed here extract as concrete structural facts.\n  survey: {\n    retain_extraction_mode: \"custom\",\n    retain_custom_instructions:\n      \"This document belongs to the Hindsight codebase-survey lifecycle. Apply ONE of two rules: \" +\n      \"(1) If the content is an internal status marker — it says it is an internal marker, or \" +\n      \"merely announces that a survey started/completed at some commit — extract NOTHING: return \" +\n      \"an empty list of facts. (2) Otherwise the content is survey FINDINGS about the codebase: \" +\n      \"extract the concrete structural facts it states (components and their responsibilities, \" +\n      \"key concepts, conventions, tech stack), preserving identifiers verbatim.\",\n    retain_chunk_size: 12000,\n  },\n} as const;\n\n// ── passive tier tagging (entity_labels) ───────────────────────────────────────\n// A single hierarchical bank-config group set by `configureBank` at seed time. `tag: true` makes the\n// extractor copy each selected `knowledge:<value>` onto the fact's tags (via `_inject_label_tags`),\n// giving every durable fact a knowledge-tier routing tag the server-side pages (and any\n// tag-filtered query) can select on. The vocabulary is FIXED (not per-feature) because tag matching\n// is exact set-ops with no wildcards.\nexport interface EntityLabelValue {\n  value: string;\n  description: string;\n}\n\nexport interface EntityLabelGroup {\n  key: string;\n  type: \"multi-values\";\n  optional: boolean;\n  tag: boolean;\n  description: string;\n  values: EntityLabelValue[];\n}\n\nexport const PAGE_LABELS: EntityLabelGroup = {\n  key: \"knowledge\",\n  type: \"multi-values\", // 0, 1, or several — empty is normal\n  optional: true,\n  tag: true, // emits knowledge:<value> onto the fact's tags\n  description:\n    \"Routing labels for this project's Hindsight PAGES — curated, human-readable summaries \" +\n    \"of the repo's DURABLE engineering knowledge (architecture, key decisions, conventions, ongoing \" +\n    \"initiatives), each page rebuilt automatically from the facts labeled for it. Mark a fact only when \" +\n    \"it is durable, reusable knowledge a developer would still want surfaced in future sessions. \" +\n    \"IMPORTANT: leave this EMPTY for routine, transient, or operational facts — a passing test, a \" +\n    \"one-off command, a status update, a debugging dead-end. MOST facts should get no label here. \" +\n    \"Assign more than one value only when the fact genuinely fits several.\",\n  values: [\n    {\n      value: \"feature-work\",\n      description:\n        \"A new feature, initiative, or enhancement being planned or built — the capability being added \" +\n        \"and the intent behind it. Not routine bug-fixes or chores.\",\n    },\n    {\n      value: \"decision\",\n      description:\n        \"A technical decision that will constrain future work, with its rationale — why this approach \" +\n        \"was chosen over alternatives, or a rule deliberately adopted.\",\n    },\n    {\n      value: \"convention\",\n      description:\n        \"An established way this project does things — naming, structure, testing, error handling, or \" +\n        \"another recurring pattern a contributor is expected to follow.\",\n    },\n    {\n      value: \"component\",\n      description:\n        \"What a specific module, file, service, or subsystem is responsible for, or how components \" +\n        \"depend on and connect to one another.\",\n    },\n    {\n      value: \"concept\",\n      description:\n        \"A domain concept, key abstraction, or piece of project vocabulary a new contributor must \" +\n        \"understand to work effectively.\",\n    },\n  ],\n};\n\n// PAGES (OKF pages = mental models) = a developer's durable mental model of the codebase,\n// CONSOLIDATED from the ingested MEMORY (commit history + past conversations) — NOT mirrored from the\n// current source (which would need constant re-sync). A universal 5-page taxonomy that generalizes to\n// any repo; the curator populates each from history+chats and can spawn per-component sub-pages.\n// A seeded page is a tag-scoped synthesis view: `tags` pins it to one `knowledge:<tier>` label so\n// its synthesis draws from the facts the extractor routed to that tier (exact set-ops — see\n// PAGE_LABELS above; names/tiers mirror the label vocabulary). The tiers say what KIND of\n// knowledge a fact is, never WHOSE — `pageScopeRule` below carries that half.\nexport interface PageSpec {\n  name: string;\n  source_query: string;\n  tags: string[];\n}\n\n/**\n * The subject-scoping clause every page this plugin creates carries, naming the subject it is\n * about — the seeded taxonomy (through `pagesFor`) and each captured initiative alike.\n *\n * `project` is the repository when the bank is one repository's, and undefined otherwise — a bank\n * several repos share has no repo to name, and naming whichever one seeded last made the sentence\n * flip on every session start (#4146). Naming the BANK instead, as this once did, scoped every page\n * to a project no memory is about, so a shared bank's pages all came out empty (#4490): such a bank\n * gets a clause that keeps the dependency exclusion and attributes each item to its own project.\n * Either way it must be stable for the bank, because the clause is PATCHed onto pages that outlive\n * the session.\n *\n * A bank collects everything said IN a repository, which is NOT the same as everything said ABOUT\n * it: a repo that reads its dependency's source, drafts its upstream issues, or documents how it\n * configures a service files those facts here too — correctly, since that is where the work\n * happened. Nothing downstream can tell the two apart. Attribution tags (`project:`, `harness:`,\n * `workspace:`) record where a fact ARRIVED from, never what it is ABOUT, and by synthesis time the\n * source document is gone: the fact reads as a bare technical decision with no hint whose codebase\n * it belongs to. So the page builder answered \"what are this project's key decisions?\" over\n * everything the bank held and presented a dependency's decisions as the repo's own, upstream\n * commit SHAs and all (#3476).\n *\n * Naming the repo and stating the exclusion is what lets the synthesizer make that call while it\n * still has the fact's text in front of it. It rides on `source_query` rather than the bank's\n * `reflect_mission` because the mission is seeded ONCE and then belongs to whoever set it\n * (`codingBankManifest`, #2492) — a mission-only fix would never reach an existing bank, while a\n * reworded query re-syncs through `seedPages()`'s drift PATCH on the next run.\n */\nexport function pageScopeRule(project?: string): string {\n  if (project === undefined)\n    return (\n      ` This bank is shared by several projects: attribute each thing you include to the ` +\n      `repository or project its sources name, and group by project where that helps. Leave out ` +\n      `facts about external tools, libraries and services those projects merely use, configure, ` +\n      `deploy or discuss — they belong to somebody else's codebase — including any commit SHA or ` +\n      `identifier from such a dependency's repository.`\n    );\n  return (\n    ` Scope this page to ${project} ITSELF: the bank also holds facts about external tools, ` +\n    `libraries and services that ${project} merely uses, configures, deploys or discusses, and ` +\n    `those belong to somebody else's codebase. Include something only when its subject is ` +\n    `${project}'s own code, configuration or process; when it is about a dependency, leave it out ` +\n    `however well-evidenced it looks — including any commit SHA or identifier that belongs to that ` +\n    `dependency's repository rather than this one.`\n  );\n}\n\n/** The taxonomy before scoping — never seeded directly; `pagesFor` binds it to a repository. */\nconst PAGE_TAXONOMY: readonly PageSpec[] = [\n  {\n    name: \"Component map\",\n    source_query:\n      \"From this project's commit history and past discussions, what are the main \" +\n      \"components/modules/subsystems, what is each responsible for, and how do they relate to or \" +\n      \"depend on one another? Describe the structure and responsibilities.\",\n    tags: [\"knowledge:component\"],\n  },\n  {\n    name: \"Core concepts\",\n    source_query:\n      \"What are the core concepts, domain abstractions, and key entities in this project — \" +\n      \"the vocabulary a developer must understand? For each, explain what it represents and its role, \" +\n      \"drawn from how they are introduced and discussed across the history and conversations.\",\n    tags: [\"knowledge:concept\"],\n  },\n  {\n    name: \"Conventions and patterns\",\n    source_query:\n      \"What conventions, idioms, and recurring patterns does this project follow — its \" +\n      \"approach to testing, error handling, naming, structure, and how changes are typically made? \" +\n      \"Describe how THIS project does things, as evidenced across its history and discussions.\",\n    tags: [\"knowledge:convention\"],\n  },\n  {\n    name: \"Key decisions and rationale\",\n    source_query:\n      \"What are the significant technical decisions made in this project and the rationale \" +\n      \"behind them — the durable 'why we do it this way' a developer should know? Summarize the \" +\n      \"decisions and their reasoning from the commit rationales and past conversations.\",\n    tags: [\"knowledge:decision\"],\n  },\n  {\n    name: \"Initiatives and enhancements\",\n    source_query:\n      \"Based on this repository's commit history, what are the major initiatives, features, and \" +\n      \"enhancements the project has worked on? Summarize the themes and notable changes over time. \" +\n      \"When a source memory's context carries a `[[page:<id>]]` link, repeat that link in the \" +\n      \"summary of what it describes, so each initiative links to its detailed page.\",\n    tags: [\"knowledge:feature-work\"],\n  },\n];\n\n/** The seeded pages' names, in taxonomy order — the keys `RawConfig.pages` accepts. */\nexport const PAGE_NAMES: readonly string[] = PAGE_TAXONOMY.map((page) => page.name);\n\n/**\n * What a config says about ONE seeded page, keyed by its name in `RawConfig.pages`:\n *   false                   — don't seed it at all\n *   { source_query: \"...\" } — seed it, but ask this question instead of the taxonomy's\n * An absent entry means the taxonomy's own query, which is what every page gets by default.\n */\nexport type PageOverride = false | { source_query?: string };\nexport type PagesConfig = Record<string, PageOverride>;\n\n/**\n * A page the USER defines, keyed by its name in `RawConfig.customPages` — as opposed to `pages`,\n * which only reworks the taxonomy above:\n *   source_query — the question the page answers (required)\n *   tags         — which facts feed it, e.g. [\"knowledge:decision\"]. OPTIONAL: the page trigger\n *                  matches tags with `all` (see PAGE_TAGS_MATCH), so no tags is no tag constraint\n *                  rather than an empty page — it synthesizes from everything the bank holds.\n */\nexport interface CustomPage {\n  source_query: string;\n  tags?: string[];\n}\nexport type CustomPagesConfig = Record<string, CustomPage>;\n\n/**\n * The seeded pages for one subject: the taxonomy above with `project` named in every query, minus\n * the ones `pages` disables and with its custom queries substituted.\n *\n * A pure function of its arguments, so the query text is STABLE for a given subject and\n * `seedPages()` PATCHes once (on the upgrade that introduces the clause) rather than on every\n * deepen run — which holds only while the caller's `project` is itself stable per bank (see\n * `bankProjectName`), and while `pages` itself is stable.\n *\n * `pageScopeRule` is appended to a CUSTOM query too — a page from `customPages` included. It is\n * what stops the synthesizer presenting a dependency's decisions as this project's own (#3476), a\n * failure mode someone rewording or adding a question is not thereby choosing to take on.\n */\nexport function pagesFor(\n  project: string | undefined,\n  pages: PagesConfig = {},\n  customPages: CustomPagesConfig = {}\n): PageSpec[] {\n  const scope = pageScopeRule(project);\n  // Matched case-insensitively on the same key `seedPages` matches live pages by, so a config\n  // entry and the page it names can't disagree about which page that is.\n  const byName = new Map(\n    Object.entries(pages).map(([name, override]) => [name.trim().toLowerCase(), override])\n  );\n  const out: PageSpec[] = [];\n  for (const page of PAGE_TAXONOMY) {\n    const override = byName.get(page.name.toLowerCase());\n    if (override === false) continue;\n    out.push({ ...page, source_query: (override?.source_query || page.source_query) + scope });\n  }\n  // The user's own pages, seeded at the same root and treated exactly like a taxonomy page from\n  // here on: same scoping clause, same drift re-sync, same trigger. Appended last so a taxonomy\n  // page keeps its position, which is the order the seed log and the page roster read in.\n  for (const [name, page] of Object.entries(customPages)) {\n    out.push({ name: name.trim(), source_query: page.source_query + scope, tags: page.tags ?? [] });\n  }\n  return out;\n}\n\n// Refresh policy shared by every page this plugin creates — the seeded taxonomy above and the\n// per-initiative pages `captureInitiative` adds.\nexport const PAGE_MAX_TOKENS = 4096;\n\n/** A page's `trigger`, in the API's own shape (see MentalModelTrigger in engine/response_models.py). */\nexport interface PageTrigger {\n  fact_types: string[];\n  /** How the page's own `tags` filter the memories a refresh reads. See `PAGE_TAGS_MATCH`. */\n  tags_match: \"any\" | \"all\" | \"any_strict\" | \"all_strict\" | \"exact\";\n  refresh_after_consolidation?: boolean;\n  /** `null` CLEARS a schedule the page already has. The server drops an unstated counterpart only\n   *  for a truthy field, so `{refresh_after_consolidation: false}` alone would leave a cron in\n   *  place and the page would keep refreshing — see `pageTriggerPatch`. */\n  refresh_cron?: string | null;\n}\n\n/**\n * `all` — AND over the page's tier tag, but INCLUDING untagged memories.\n *\n * The server defaults a tagged model to `all_strict`, which excludes untagged memories, and every\n * observation in these banks is untagged: `DEFAULT_OBSERVATION_SCOPES = \"shared\"` consolidates into\n * the single empty scope on purpose (#3564), so the consolidated tier carries no tags to match on.\n * Under `all_strict` that put `\"observation\"` in `PAGE_FACT_TYPES` and the consolidated beliefs it\n * asks for on opposite sides of the filter: pages declared the tier and could never retrieve a\n * single row of it, synthesizing from raw world/experience facts alone.\n *\n * `all` keeps the discrimination that matters — a `knowledge:decision` fact still cannot reach the\n * Component map, since it is tagged and lacks that page's tag — while letting the untagged shared\n * observations reach every page, where the page's `source_query` is what selects among them. That\n * is what one shared belief pool means.\n */\nconst PAGE_TAGS_MATCH = \"all\" as const;\n\n/** A page synthesizes from all three tiers; the fact types are not a preference. */\nexport const PAGE_FACT_TYPES = [\"world\", \"experience\", \"observation\"];\n\n/**\n * The default schedule: once an hour, each page on its own hashed minute (see `H` below).\n *\n * Hourly rather than daily because a page a coding agent reads at the start of a session\n * is worth little if it lags a day behind the repo; hourly rather than per-consolidation because a\n * refresh costs one LLM synthesis per page, and a repo under active work consolidates far more\n * often than once an hour. The server skips a tick that has nothing new to fold in, so an idle\n * repo pays nothing for the schedule.\n */\nexport const DEFAULT_PAGE_TRIGGER_CRON = \"H * * * *\";\n\n/** The config fields that shape the trigger (a subset of Config — see core/config.ts). */\nexport interface PageTriggerConfig {\n  pageTriggerType?: \"auto-refresh\" | \"cron\" | \"manual\";\n  pageTriggerCron?: string;\n}\n\n// ── hashed cron fields (`H`) ───────────────────────────────────────────────────\n/**\n * A cron field written `H` means \"pick a value in this field's range by hashing the page\", so\n * every page gets its OWN stable slot instead of the one the config literally names.\n *\n * One `pageTriggerCron` is shared by every page in every bank running this plugin — it ships as a\n * single documented example and is copied verbatim. A literal `\"0 3 * * *\"` therefore does not\n * schedule a refresh at 03:00; it schedules ALL of them at 03:00, on the worker pool that also\n * serves retain, so a session ingesting at 03:0x queues behind ~5 page syntheses per bank that\n * happened to share the one minute the docs suggested. Moving the hour moves the pile.\n *\n * `H` is Jenkins' syntax for exactly this problem, borrowed rather than invented because it is\n * already recognisable, and it composes with the rest of the expression instead of replacing it:\n *\n *   \"H H * * *\"      once a day, at this page's own minute and hour\n *   \"H * * * *\"      once an hour, at this page's own minute\n *   \"H 3 * * *\"      daily at 03:MM — spread within the hour the operator chose\n *   \"H H(0-5) * * *\" daily, spread across the night only\n *   \"0 3 * * *\"      unchanged: no `H`, no hashing, exactly what it says\n *\n * The alternative — one enum member per period (`daily-staggered`, then `hourly-staggered`, then\n * whatever is asked for next) — spells the schedule in the type name, so every new period is a new\n * config value, a new branch, and a new row of docs. Spreading is a property of the SCHEDULE, so it\n * belongs in the expression.\n *\n * `H` never leaves this package: `expandCronHash` resolves it to an ordinary 5-field expression\n * before the trigger is sent, because `refresh_cron` is parsed server-side as standard cron.\n */\nconst CRON_FIELD_RANGES: readonly (readonly [number, number])[] = [\n  [0, 59], // minute\n  [0, 23], // hour\n  [1, 31], // day of month\n  [1, 12], // month\n  [0, 6], // day of week\n];\n\nconst HASHED_FIELD = /^H(?:\\((\\d+)-(\\d+)\\))?$/;\n\n/**\n * Does this expression ask for hashing at all? Plain crons take every path below unchanged.\n *\n * Any field STARTING with `H` counts, not just a well-formed one: no standard cron field begins\n * with `H` (values are digits, `*`, `,`, `-`, `/`, and the JAN-DEC/SUN-SAT names), so `\"Hx\"` is a\n * typo in this package's syntax rather than something the server was going to accept. Claiming it\n * here is what gets it reported as a malformed hashed field instead of an opaque cron parse error.\n */\nexport function isHashedCron(cron: string): boolean {\n  return /(^|\\s)H/.test(cron);\n}\n\n/**\n * The five fields of `cron` when every `H` in it is well-formed, else `undefined`.\n *\n * Only the `H` fields are checked. The rest are the server's to validate, as they already are —\n * this package does not own cron syntax, only the extension it adds to it.\n */\nexport function parseHashedCron(cron: string): string[] | undefined {\n  const fields = cron.trim().split(/\\s+/);\n  if (fields.length !== CRON_FIELD_RANGES.length) return undefined;\n  for (const [i, field] of fields.entries()) {\n    if (!field.startsWith(\"H\")) continue;\n    const m = HASHED_FIELD.exec(field);\n    if (!m) return undefined;\n    if (m[1] === undefined) continue;\n    const [lo, hi] = [Number(m[1]), Number(m[2])];\n    const [min, max] = CRON_FIELD_RANGES[i];\n    if (lo > hi || lo < min || hi > max) return undefined;\n  }\n  return fields;\n}\n\n/**\n * `seed`'s own value in `[lo, hi]` — stable across machines, processes and releases.\n *\n * The field index is hashed alongside the seed so `H H * * *` does not derive its minute and its\n * hour from one number: the two would move together across pages, collapsing the 1440 daily slots\n * the expression offers back towards 60.\n */\nfunction hashedValue(seed: string, field: number, lo: number, hi: number): number {\n  const digest = createHash(\"sha256\").update(`${seed}\\u0000${field}`).digest();\n  return lo + (digest.readUInt32BE(0) % (hi - lo + 1));\n}\n\n/**\n * `cron` with each `H` replaced by `seed`'s own value for that field — an ordinary cron expression.\n *\n * Returns the input untouched when it holds no `H`, and when an `H` in it is malformed: a bad\n * expression is reported by the server that parses crons, not silently rewritten into a valid one\n * that runs at a time nobody asked for. `resolvePageTriggerType` rejects it before it gets here.\n */\nexport function expandCronHash(cron: string, seed: string): string {\n  if (!isHashedCron(cron)) return cron;\n  const fields = parseHashedCron(cron);\n  if (!fields) return cron;\n  return fields\n    .map((field, i) => {\n      const m = HASHED_FIELD.exec(field);\n      if (!m) return field;\n      const [lo, hi] =\n        m[1] === undefined ? CRON_FIELD_RANGES[i] : ([Number(m[1]), Number(m[2])] as const);\n      return String(hashedValue(seed, i, lo, hi));\n    })\n    .join(\" \");\n}\n\n/**\n * `trigger` as it should be sent for ONE page, resolving any `H` against that page's identity.\n *\n * Applied where a page is created rather than where the trigger is built, because that is the only\n * place the identity exists: `buildPageTrigger` runs once per session for all of them.\n *\n * The seed is bank + page name — the pair that identifies a page across runs — so a page keeps its\n * slot for as long as it keeps its name, and two banks seeded from the same config land on\n * different ones. Hashing distributes; it does not partition, so two pages CAN still collide.\n */\nexport function pageTriggerFor(trigger: PageTrigger, bank: string, page: string): PageTrigger {\n  const cron = trigger.refresh_cron;\n  if (!cron || !isHashedCron(cron)) return trigger;\n  return { ...trigger, refresh_cron: expandCronHash(cron, `${bank}\\u0000${page}`) };\n}\n\n/**\n * How this project's pages keep themselves current.\n *\n * WHEN is the only part of this that is a preference. The default is `cron` on\n * `DEFAULT_PAGE_TRIGGER_CRON` — hourly, each page on its own hashed minute: current within the\n * hour, and bounded, since the server skips a tick when nothing changed. `auto-refresh`, which\n * every page used to ship with, rebuilds whenever consolidation produced new material — the most\n * current setting and by far the most expensive, since a busy repo consolidates constantly and\n * each pass is an LLM synthesis per page (#3506). `manual` refreshes only when something asks. A\n * page is a mental model like any other, so the scheduler picks it up either way\n * (`mental_models_with_cron()` filters on nothing but a non-empty `refresh_cron`).\n *\n * HOW a page refreshes is deliberately NOT stated here. `create_page` owns that\n * (`PAGE_DEFAULT_TRIGGER`: delta refresh, no sibling pages in the reflect loop) and\n * merges a client's fields over it, so this sends only what it actually means and inherits the\n * rest. Restating the server's own defaults here would just freeze a copy of them that drifts the\n * next time they change.\n *\n * `fact_types` IS ours to state: the server's page default is observation-only, while these pages\n * are tag-scoped syntheses over the `knowledge:<tier>` labels the extractor puts on world and\n * experience facts. So is `tags_match`, for the reason `PAGE_TAGS_MATCH` gives.\n *\n * `refresh_after_consolidation` and `refresh_cron` are mutually exclusive server-side, so exactly\n * one of them is ever set here.\n */\nexport function buildPageTrigger(cfg: PageTriggerConfig = {}): PageTrigger {\n  const base: PageTrigger = { fact_types: PAGE_FACT_TYPES, tags_match: PAGE_TAGS_MATCH };\n  switch (cfg.pageTriggerType) {\n    case \"auto-refresh\":\n      return { ...base, refresh_after_consolidation: true };\n    case \"manual\":\n      return { ...base, refresh_after_consolidation: false };\n    // \"cron\" and an unset type alike: the default schedule stands in for a missing expression, so\n    // a trigger built from a partial config is never a cron trigger with nothing to fire on.\n    default:\n      return { ...base, refresh_cron: cfg.pageTriggerCron || DEFAULT_PAGE_TRIGGER_CRON };\n  }\n}\n\n/** A page's refresh policy as the tree reports it — the EFFECTIVE one, defaults filled in. */\nexport interface CurrentPageTrigger {\n  tags_match?: string;\n  refresh_after_consolidation?: boolean;\n  refresh_cron?: string | null;\n}\n\n/**\n * Has an existing page's refresh policy drifted from what this config asks for?\n *\n * Compared against the page's OWN resolved trigger (`pageTriggerFor`), not the shared one: under a\n * hashed cron every page has a different expression, and comparing the unresolved `H * * * *`\n * would report drift on every page on every session.\n *\n * Only the fields this plugin actually states are compared. Everything else on the trigger —\n * `mode`, sibling exclusion, `min_refresh_interval_seconds` — is the server's or the operator's,\n * and a re-sync must not have an opinion about it (#3506).\n */\nexport function pageTriggerDrifted(current: CurrentPageTrigger, desired: PageTrigger): boolean {\n  return (\n    current.tags_match !== desired.tags_match ||\n    (current.refresh_cron ?? null) !== (desired.refresh_cron ?? null) ||\n    Boolean(current.refresh_after_consolidation) !== Boolean(desired.refresh_after_consolidation)\n  );\n}\n\n/**\n * The trigger to PATCH onto an existing page, given the one we would create it with.\n *\n * The server merges a trigger patch field by field and drops the unstated counterpart of a TRUTHY\n * refresh field, so a cron patch clears auto-refresh and vice versa. `manual` is the gap: its\n * `refresh_after_consolidation: false` is falsy, nothing is dropped, and a page that had a cron\n * would keep firing on it. Stating `refresh_cron: null` closes that.\n */\nexport function pageTriggerPatch(desired: PageTrigger): PageTrigger {\n  if (desired.refresh_after_consolidation === false) return { ...desired, refresh_cron: null };\n  return desired;\n}\n\n// ── the bank template ──────────────────────────────────────────────────────────\n// The bank's CONFIG — missions, retain strategies, entity labels — as a single manifest for\n// POST /banks/{id}/import. Idempotent (config fields apply as per-bank overrides), so the deepen\n// engine can apply it every run. Replaces the old configureBank PUT+PATCH.\n//\n// The seeded pages are NOT part of this manifest: the template's `mental_models` key creates bare\n// mental models with no page node, which leaves them invisible to page search (it joins\n// through `knowledge_pages`) and unreadable by node id. Pages are seeded separately, through the\n// pages API, by `HindsightClient.seedPages()`.\nexport const CODING_BANK_TEMPLATE = {\n  version: \"1\",\n  bank: {\n    reflect_mission: REFLECT_MISSION,\n    enable_observations: true,\n    observations_mission: OBSERVATIONS_MISSION,\n    retain_mission: GIT_MISSION,\n    retain_extraction_mode: DEFAULT_RETAIN_EXTRACTION_MODE,\n    retain_default_strategy: \"git\",\n    retain_strategies: RETAIN_STRATEGIES,\n    entity_labels: [PAGE_LABELS],\n    entities_allow_free_form: true,\n  },\n} as const;\n\n/** Bank-level missions the template seeds ONCE and then leaves alone (#2492). */\nconst MISSION_FIELDS = [\"reflect_mission\", \"retain_mission\", \"observations_mission\"] as const;\n\n/** Bank-scoped config OVERRIDES exactly as `GET /banks/{id}/config` reports them. */\nexport type BankOverrides = Record<string, unknown>;\n\n/** The manifest `configureBank` POSTs to `/banks/{id}/import`. */\nexport interface BankManifest {\n  version: \"1\";\n  bank: Record<string, unknown>;\n}\n\n/**\n * Bank-config fields `defaultBankConfig` may NOT set, because this plugin already governs them:\n * the two containers are merged per entry (see below), and the extraction mode has its own\n * setting. Letting a default name one of these would either replace a merged map wholesale — the\n * very failure #3927 fixed — or fight the re-sync that `retainExtractionMode` performs.\n */\nexport const PLUGIN_GOVERNED_BANK_FIELDS: readonly string[] = [\n  \"retain_strategies\",\n  \"entity_labels\",\n  \"retain_extraction_mode\",\n];\n\n/** A bank-config override the bank's owner actually made. Blank is not a choice; `false` is. */\nfunction isSet(v: unknown): boolean {\n  if (v === null || v === undefined) return false;\n  if (typeof v === \"string\") return v.trim() !== \"\";\n  return true;\n}\n\n/**\n * The template fields still missing from a bank whose overrides are `overrides` — or `undefined`\n * when it already carries them all and there is nothing to write.\n *\n * **This plugin only ever ADDS what is missing; it never overwrites what the bank already says.**\n *\n * Re-applying the whole template on every pass is how a plugin takes a bank over, and it has now\n * been fixed three times over the same shape: #1270 for OpenClaw's missions, #2492 for this\n * plugin's, and #3927 for everything those two left un-guarded. Each earlier fix protected only the\n * fields that had just been noticed, so the rest kept being stamped back on every session start.\n * Reading the current overrides and writing only where the bank is silent covers the whole surface\n * at once, including whatever gets added to the template next.\n *\n * The two container fields merge PER ENTRY, because the server stores each as ONE config value and\n * an import replaces it outright: re-sending the five strategies wholesale deleted any strategy the\n * user had defined, reverted their edits to the plugin's own (mission, extraction mode, chunk\n * size), and could leave `retain_default_strategy` naming a strategy that no longer existed.\n * Merging still lets a strategy ADDED by a newer plugin release reach an existing bank — the reason\n * the re-apply exists — without touching the entries already there.\n *\n * The consequence is deliberate: a release that REWORDS an existing strategy or label does not\n * reach a bank that already has it. Clearing that override on the bank takes the current default\n * back, since the next pass then finds the bank silent there.\n *\n * ONE exception, and it is a config key rather than a default: the extraction mode of the plugin's\n * own strategies follows `mode` (RawConfig.retainExtractionMode) and is re-synced on drift, the way\n * `seedPages()` re-syncs a page's query. It is what every session write-back costs, so it has to be\n * changeable from the plugin's config and reach banks seeded before the change (#4560). The\n * strategy's other fields, and any strategy the plugin did not define, are still left alone.\n *\n * `defaults` (RawConfig.defaultBankConfig) are the user's OWN additions to the template — bank-config\n * fields written under the same rule, only where the bank is silent. They exist because a bank this\n * plugin creates is otherwise born with the server's defaults for everything the template does not\n * name — `enable_auto_consolidation`, `mental_model_min_refresh_interval_seconds` — and on a\n * cost-conscious deployment those are the expensive settings (#4725): a new repo an agent touched\n * spawned a bank running auto-consolidation on a 60s refresh floor while every other bank had been\n * hand-set to a cheap baseline. On a key the template also names (`enable_observations`), the\n * user's default wins, since it is the more specific statement. Applied under the same\n * silent-only rule, a default reaches an existing bank too — but only where that bank never took\n * a position, so a value set in the control plane (even one equal to the server default) is kept.\n */\nexport function codingBankManifest(\n  overrides: BankOverrides | undefined,\n  mode: RetainExtractionMode = DEFAULT_RETAIN_EXTRACTION_MODE,\n  defaults: Record<string, unknown> = {}\n): BankManifest | undefined {\n  // Unreadable overrides — the bank does not exist yet, or the deployment has the bank-config API\n  // switched off. Nothing can have been customised through an API that is not there, and this same\n  // POST is what CREATES the bank, so `{}` seeds the lot (every branch below fires, and the result\n  // is CODING_BANK_TEMPLATE — asserted in missions.test.ts).\n  const current = overrides ?? {};\n  const template = CODING_BANK_TEMPLATE.bank;\n  const bank: Record<string, unknown> = {};\n\n  // The missions are seeded as a GROUP: the plugin writes all three together, so any one of them\n  // being present means this bank has been seeded already, or its owner wrote their own (#2492).\n  if (!MISSION_FIELDS.some((f) => isSet(current[f]))) {\n    bank.reflect_mission = template.reflect_mission;\n    bank.enable_observations = template.enable_observations;\n    bank.observations_mission = template.observations_mission;\n    bank.retain_mission = template.retain_mission;\n    bank.retain_extraction_mode = mode;\n  }\n\n  if (!isSet(current.retain_default_strategy))\n    bank.retain_default_strategy = template.retain_default_strategy;\n  if (!isSet(current.entities_allow_free_form))\n    bank.entities_allow_free_form = template.entities_allow_free_form;\n\n  const strategies =\n    current.retain_strategies && typeof current.retain_strategies === \"object\"\n      ? (current.retain_strategies as Record<string, unknown>)\n      : {};\n  const updates: Record<string, unknown> = {};\n  for (const [name, def] of Object.entries(template.retain_strategies)) {\n    // `custom` (the survey) carries its own instructions and is not the configured mode's to change.\n    const synced = def.retain_extraction_mode === \"custom\" ? {} : { retain_extraction_mode: mode };\n    const have = strategies[name] as Record<string, unknown> | null | undefined;\n    if (!have || typeof have !== \"object\") updates[name] = { ...def, ...synced };\n    else if (\"retain_extraction_mode\" in synced && have.retain_extraction_mode !== mode)\n      updates[name] = { ...have, ...synced };\n  }\n  // The whole map is one config value, so the UNION has to be sent — not just the changes.\n  if (Object.keys(updates).length > 0) bank.retain_strategies = { ...strategies, ...updates };\n\n  const labels = Array.isArray(current.entity_labels) ? current.entity_labels : [];\n  const [knowledgeGroup] = template.entity_labels;\n  if (!labels.some((g) => (g as { key?: unknown } | null)?.key === knowledgeGroup.key))\n    bank.entity_labels = [...labels, knowledgeGroup];\n\n  // After the template, so a default wins the keys both name. The governed fields are dropped at\n  // config resolution (with a warning) and skipped again here, so a caller of this function alone\n  // cannot replace a merged container either.\n  for (const [key, value] of Object.entries(defaults)) {\n    if (PLUGIN_GOVERNED_BANK_FIELDS.includes(key) || !isSet(value) || isSet(current[key])) continue;\n    bank[key] = value;\n  }\n\n  return Object.keys(bank).length > 0 ? { version: \"1\", bank } : undefined;\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/transcript-dsh.ts",
      "content": "/**\n * DeepSeek Harness (dsh) transcript normalizer.\n *\n * dsh keeps a session as an append-only log of typed `SessionEvent`s rather than a chat array, and\n * a plugin reads that log straight off the live session (`snapshotEvents()`) — so this is a pure\n * function over those events, like the opencode normalizer, not a file reader. The SAME event\n * vocabulary is what dsh persists to disk, so the backfill reader (core/history.ts) feeds this\n * exact function.\n *\n * Only three of the ~30 event types carry conversation:\n *   - `user/message`      surface, a UserMessage — the human prompt OR an injected plugin context\n *   - `assistant/message` surface, the assembled reply for one step\n *   - `tool/call`         log-only, the model's tool invocation (rendered as a compact action turn)\n * `tool/result` is deliberately skipped: its payload is raw tool output, which the shared\n * `actionLine` convention keeps out of the bank (see transcript-util.ts).\n *\n * A `user/message` is only kept when its source is an actual HUMAN (`source.kind === 'user'`).\n * dsh delivers plugin context — its own runtime-context snapshots, the skill catalog, file-change\n * notices, and OUR recalled memories — as user-role messages on the same surface, and retaining\n * those would file machine scaffolding as if the user had said it (and, for our own block, feed\n * recalled memory straight back into the next extraction). The tag-based `stripInjectedMemory`\n * still runs on what remains, for text that arrived inside a genuine prompt.\n */\nimport type { TransportTurn } from \"./chat\";\nimport { actionLine, stripInjectedMemory } from \"./transcript-util\";\n\n/**\n * The Cordis plugin name. Messages this integration injects carry `source.kind: 'plugin:hindsight'`\n * (the V4 producer-owned kind; V3 logs recorded `kind: 'plugin', plugin: 'hindsight'`), so an\n * injected block is identifiable in a session log even though the `kind: 'user'` filter below\n * already keeps it (and every other plugin's context) out of a retain.\n */\nexport const HINDSIGHT_PLUGIN = \"hindsight\";\n\n/** Structural subset of a dsh ContentBlock (text is the only kind that carries prose). */\ninterface DshContentBlock {\n  type?: string;\n  text?: string;\n}\n\n/** Structural subset of a dsh Message ({ id, role, content, source }). */\ninterface DshMessage {\n  role?: string;\n  content?: DshContentBlock[];\n  source?: { kind?: string; plugin?: string };\n}\n\n/** Structural subset of a dsh SessionEvent. `data` is the per-type payload. */\nexport interface DshSessionEvent {\n  type?: string;\n  time?: number;\n  data?: unknown;\n}\n\n/** Join a message's text blocks; reasoning/image/tool blocks carry no durable prose. */\nfunction textOf(message: DshMessage): string {\n  return (message.content || [])\n    .filter((block) => block?.type === \"text\" && typeof block.text === \"string\")\n    .map((block) => block.text!)\n    .join(\"\\n\")\n    .trim();\n}\n\n/** dsh stamps epoch milliseconds on every event; absent only on malformed input. */\nfunction stampOf(event: DshSessionEvent): { timestamp?: string } {\n  return typeof event.time === \"number\" ? { timestamp: new Date(event.time).toISOString() } : {};\n}\n\n/**\n * Normalize a dsh session event log into transcript turns: user/assistant prose plus compact\n * `role:\"action\"` turns for tool calls. Never throws on malformed entries.\n */\nexport function readDshEvents(events: readonly DshSessionEvent[]): TransportTurn[] {\n  const turns: TransportTurn[] = [];\n  for (const event of events || []) {\n    if (!event || typeof event !== \"object\") continue;\n    const stamp = stampOf(event);\n    if (event.type === \"user/message\") {\n      const message = event.data as DshMessage | undefined;\n      if (!message || message.source?.kind !== \"user\") continue;\n      const text = stripInjectedMemory(textOf(message)).trim();\n      if (text) turns.push({ role: \"user\", content: text, ...stamp });\n    } else if (event.type === \"assistant/message\") {\n      const message = (event.data as { message?: DshMessage } | undefined)?.message;\n      if (!message) continue;\n      const text = stripInjectedMemory(textOf(message)).trim();\n      if (text) turns.push({ role: \"assistant\", content: text, ...stamp });\n    } else if (event.type === \"tool/call\") {\n      const call = event.data as { name?: string; arguments?: string } | undefined;\n      if (!call?.name) continue;\n      turns.push({\n        role: \"action\",\n        content: actionLine(call.name, parseArgs(call.arguments)),\n        ...stamp,\n      });\n    }\n  }\n  return turns;\n}\n\n/** `tool/call.arguments` is the model's RAW JSON string, unparsed by design. */\nfunction parseArgs(raw: string | undefined): unknown {\n  if (!raw) return undefined;\n  try {\n    return JSON.parse(raw);\n  } catch {\n    return raw; // a malformed argument string still names what the model was reaching for\n  }\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/transcript-util.ts",
      "content": "/** Shared transcript-rendering helpers used by both the Claude (transcript.ts) and Codex\n *  (transcript-codex.ts) session readers. */\n\n/** Cap on any single rendered tool input or tool result (mirrors v1's 2000-char cap): small\n *  edits/commands are captured verbatim while a giant Write/output is bounded. */\nexport const TOOL_TEXT_CAP = 2000;\n\n/** Injected context — stripped from retained text so a write-back never re-ingests its own\n *  injected memory (a retain→reflect feedback loop). Covers every block the hooks inject, PLUS\n *  the host's own hook-transport wrappers, which arrive as ordinary USER messages and would\n *  otherwise be extracted as things the user said (#3023):\n *    <hook_prompt>        codex surfaces hook stdout/errors this way\n *    <task-notification>  Claude Code reports a background task's outcome — task id, tool-use id,\n *                         status; measured at 39 of these across 400 local transcripts, each one\n *                         the entire message\n *    <system-reminder>    same class; today it only rides inside `tool_result` blocks, which the\n *                         Claude reader already drops, so this is insurance against it moving\n *    <hindsight_knowledge>, <hindsight_knowledge_refresh>  the pre-rename names of the page\n *                         preamble tags, still in transcripts recorded before it. Remove in 2.x.\n *  Tag-structural, not content-guessing. The block is removed and any surrounding text KEPT — a\n *  message that is nothing but a wrapper then renders empty and is dropped as a no-content turn. */\nconst MEMORY_TAG_RE =\n  /<(hook_prompt|task-notification|system-reminder|hindsight_memory|hindsight_memories|hindsight_bank|relevant_memories|user_feedback|hindsight_pages|hindsight_page_refresh|hindsight_knowledge|hindsight_knowledge_refresh)\\b[\\s\\S]*?<\\/\\1>/g;\n\nexport function stripInjectedMemory(s: string): string {\n  return s.replace(MEMORY_TAG_RE, \"\");\n}\n\nexport function truncate(s: string, max = TOOL_TEXT_CAP): string {\n  return s.length > max ? `${s.slice(0, max)}… (truncated)` : s;\n}\n\n/** Keys tried, in order, to find a tool call's primary target for the compact action line. */\nconst TARGET_KEYS = [\n  \"file_path\",\n  \"path\",\n  \"notebook_path\",\n  \"command\",\n  \"pattern\",\n  \"query\",\n  \"url\",\n  \"name\",\n  \"id\",\n] as const;\n\nconst ACTION_TARGET_CAP = 100;\n\n/**\n * Compact one tool call into an action line: the tool name plus its primary target — a file path,\n * command, pattern, … — with NO full arguments and NO output (e.g. `Edit boltons/strutils.py`).\n * Retaining raw args/outputs buries the session's decisions in mechanical noise; the extractor only\n * needs WHAT was touched. The one exception is a memory note, whose text is kept (memoryNoteText).\n */\nexport function actionLine(tool: string, input: unknown): string {\n  let target = \"\";\n  if (input && typeof input === \"object\") {\n    const rec = input as Record<string, unknown>;\n    for (const k of TARGET_KEYS) {\n      const v = rec[k];\n      if (typeof v === \"string\" && v.trim()) {\n        target = v.trim().split(\"\\n\")[0];\n        break;\n      }\n    }\n  } else if (typeof input === \"string\") {\n    target = input.trim().split(\"\\n\")[0];\n  }\n  if (target.length > ACTION_TARGET_CAP) target = `${target.slice(0, ACTION_TARGET_CAP)}…`;\n  const line = target ? `${tool} ${target}` : tool;\n  const note = memoryNoteText(input);\n  return note ? `${line}\\n${truncate(note, MEMORY_NOTE_CAP)}` : line;\n}\n\n/** Larger than TOOL_TEXT_CAP: an agent's progress note grows to ~5KB over a run (CL-Bench, 15\n *  questions), and cutting it at 2KB drops the newest lessons, which it appends at the end. */\nconst MEMORY_NOTE_CAP = 8000;\n\n/** A file under a `memory/` or `memories/` folder, or a `MEMORY.md`: where an agent keeps the\n *  notes it writes for its future self (Claude Code's auto memory, Anthropic's memory protocol). */\nconst MEMORY_NOTE_PATH_RE = /(^|[\\\\/])(memory|memories)[\\\\/]|(^|[\\\\/])MEMORY\\.md$/i;\n/** The notes folder named anywhere in a shell command, as a path segment or a `cd` target. */\nconst MEMORY_SHELL_WRITE_RE = /[\\\\/](memory|memories)([\\\\/\\s\"']|$)|MEMORY\\.md/i;\n/** Output redirected to a file (`>`, `>>`, not `2>` or `&>`) or `tee`: the command writes. */\nconst SHELL_WRITE_RE = /(^|[^0-9&>])>>?(?!&)|\\btee\\b/;\n\n/**\n * The text an agent wrote into one of its memory notes, so the write-back keeps the lesson in the\n * agent's own words. Every other file write stays a bare action line, but a note IS the decision:\n * reduced to `Write memories/prices.md`, extraction had to rebuild \"prc is cents, prc_usd is NULL\n * for most rows\" from the session's queries, and on CL-Bench it kept the unit and dropped the\n * caveat that the agent itself had written down. `content` is a Write, `new_string` an Edit.\n */\nfunction memoryNoteText(input: unknown): string {\n  if (!input || typeof input !== \"object\") return \"\";\n  const rec = input as Record<string, unknown>;\n  // A shell write into the notes folder (`echo \"lesson\" >> memory/notes.md`, a heredoc after\n  // `cd memory`) IS a note too: on CL-Bench 8 of the agent's 30 note writes went through Bash,\n  // and the 100-char action cap cut the Q5 lesson off before its point.\n  const cmd = rec.command;\n  if (typeof cmd === \"string\")\n    return MEMORY_SHELL_WRITE_RE.test(cmd) && SHELL_WRITE_RE.test(cmd) ? cmd.trim() : \"\";\n  const path = rec.file_path ?? rec.path;\n  if (typeof path !== \"string\" || !MEMORY_NOTE_PATH_RE.test(path)) return \"\";\n  const text = rec.content ?? rec.new_string;\n  return typeof text === \"string\" ? text.trim() : \"\";\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/chat.ts",
      "content": "/**\n * Harness-agnostic chat memory: the JSON user/assistant transcript schema shared by BOTH the\n * backfill (ingest past sessions) and the live runtime write-back. A leading `system` turn carries\n * the REF-ID tracer; every turn gets an ABSOLUTE timestamp.\n */\nimport { diag } from \"./diag\";\nimport { RateLimitedError, type HindsightClient } from \"./hindsight\";\nimport { log } from \"./log\";\nimport {\n  advancePaths,\n  advanceSegments,\n  bankTurns,\n  fingerprintTurns,\n  MAX_CURSOR_OPS,\n  planRetain,\n  type RetainCursor,\n  type RetainCursorStore,\n} from \"./retain-cursor\";\nimport type { RetainStamp } from \"./retain-stamp\";\nimport type { ChatSession } from \"./types\";\nimport { uuidV5 } from \"./uuid\";\nimport { pool, sleep } from \"./util\";\n\nexport interface TransportTurn {\n  role: string;\n  content: string;\n  timestamp?: string;\n}\n\n/** Prepend the REF-ID system turn to a set of already-normalized turns. */\nexport function withRefId(refId: string, turns: TransportTurn[], baseTs: string): TransportTurn[] {\n  return [{ role: \"system\", content: `REF-ID: ${refId}`, timestamp: baseTs }, ...turns];\n}\n\n/**\n * Render normalized turns as a JSONL transcript (ONE turn per line) — the same shape everywhere:\n * live write-back and backfilled chats alike. JSONL beats a JSON array on both ends: appending a\n * turn never rewrites the document, and the server's structured chunker treats each line as an\n * atomic unit (`retain_structured_chunk_size`), so a turn is never split mid-thought. The REF-ID\n * system turn leads; tool activity is already compacted into `role:\"action\"` turns.\n */\nexport function renderSessionJsonl(refId: string, turns: TransportTurn[], baseTs: string): string {\n  return withRefId(refId, turns, baseTs)\n    .map((t) => JSON.stringify(t))\n    .join(\"\\n\");\n}\n\n/** Backfill: ingest past sessions RAW as JSON transcripts under the `conversation` strategy. */\nexport async function ingestChats(\n  client: HindsightClient,\n  sessions: ChatSession[],\n  opts: {\n    concurrency?: number;\n    log?: (m: string) => void;\n    stampFor?: (sessionId: string) => RetainStamp;\n  } = {}\n): Promise<number> {\n  const log = opts.log ?? (() => {});\n  if (!sessions.length) {\n    log(\"[chat] no sessions; skipping\");\n    return 0;\n  }\n  log(`[chat] ingesting ${sessions.length} chats (RAW, JSONL transcript — one turn per line) …`);\n  const NOW = Date.now(); // anchor synthesized times to a real, ABSOLUTE clock (not a fabricated epoch)\n  let failures = 0;\n  await pool(\n    sessions,\n    opts.concurrency ?? 8,\n    async (s, i) => {\n      const id = s.id || `s${i}`;\n      const stamp = opts.stampFor?.(id);\n      // List order is CHRONOLOGICAL (a later chat can amend an earlier one), so the LAST session is\n      // the newest — the previous `NOW - i*1h` inverted recency and made an amendment rank older than\n      // the decision it superseded. This synthetic stagger is therefore only a FALLBACK, for a\n      // transcript that carries no clocks of its own.\n      const sessBase = NOW - (sessions.length - 1 - i) * 3600000;\n      // A backfilled session keeps the clock it actually happened on: when any turn carries a source\n      // timestamp, the first one dates the document (verbatim, offset included) and anchors the\n      // turns that have none. Dating it to the import made an old session surface as recent even\n      // though every turn inside it was dated correctly.\n      const sourceTs = (s.turns || [])\n        .map((t) => t.timestamp)\n        .find((v): v is string => typeof v === \"string\" && !Number.isNaN(Date.parse(v)));\n      const anchorMs = sourceTs ? Date.parse(sourceTs) : sessBase;\n      const baseIso = sourceTs ?? new Date(sessBase).toISOString();\n      const turns = withRefId(\n        `chat:${id}`,\n        (s.turns || []).map((t, j) => ({\n          role: t.role,\n          content: t.text,\n          timestamp: t.timestamp || new Date(anchorMs + (j + 1) * 60000).toISOString(),\n        })),\n        baseIso\n      );\n      await client.retain(\n        turns.map((x) => JSON.stringify(x)).join(\"\\n\"),\n        \"developer chat\",\n        `chat:${id}`,\n        [...new Set([...(stamp?.tags ?? []), \"source:chat\"])],\n        \"conversation\",\n        {\n          timestamp: baseIso,\n          metadata: {\n            ...stamp?.metadata,\n            source: \"chat\",\n            chat: id,\n            ref_id: `chat:${id}`,\n          },\n        }\n      );\n    },\n    (i, e) => {\n      failures++;\n      log(`  ! chat ${i} failed to enqueue: ${(e as Error).message?.slice(0, 120)}`);\n    }\n  );\n  log(`[chat] done: ${sessions.length} chats ingested (JSONL) under strategy 'chat'`);\n  return failures;\n}\n\n/** Capability probe for the append path. A failed server-version probe answers \"no\": appending\n *  without `operation_id` dedupe can double-write, so doubt falls back to a full replace. A failed\n *  bank-config probe answers \"yes\" (see HindsightClient.supportsAppendRetain): banks store document\n *  text by default, and only an explicit `store_document_text: false` rules append out (#4613). */\nasync function supportsAppend(client: HindsightClient): Promise<boolean> {\n  try {\n    return await client.supportsAppendRetain();\n  } catch {\n    return false;\n  }\n}\n\n/** Short: this runs on every write-back that follows an accepted one, inside a hook's budget. */\nconst OP_CHECK_TIMEOUT_MS = 5_000;\nconst LOST_OP_STATUSES = new Set([\"failed\", \"cancelled\", \"error\"]);\n\n/**\n * Settle the cursor's accepted-but-unconfirmed operations (#5251). Returns the cursor to plan from —\n * marked `dirty` when one of them failed, so the plan replaces and re-sends the turns it carried —\n * and the ids still worth checking next time. Fail-open: an op whose status cannot be read stays\n * tracked, never counts as failed.\n */\nasync function settleOps(\n  client: HindsightClient,\n  cursor: RetainCursor\n): Promise<{ cursor: RetainCursor; ops: string[] }> {\n  const ops = cursor.ops ?? [];\n  const statuses = await Promise.all(\n    ops.map(async (id) => {\n      try {\n        const r = await client.req(\n          \"GET\",\n          client.bankUrl(`/operations/${encodeURIComponent(id)}`),\n          undefined,\n          [],\n          OP_CHECK_TIMEOUT_MS\n        );\n        if (r.status === 404) return \"not_found\"; // pruned: nothing left to learn\n        return String(((await r.json()) as { status?: unknown }).status ?? \"\").toLowerCase();\n      } catch {\n        return \"\";\n      }\n    })\n  );\n  const lost = statuses.some((s) => LOST_OP_STATUSES.has(s));\n  const open = ops.filter((_, i) => ![\"completed\", \"not_found\"].includes(statuses[i]));\n  return { cursor: lost ? { ...cursor, dirty: true } : cursor, ops: lost ? [] : open };\n}\n\n/** Retry window for a caller that did not supply one — a long-lived host with no external clock. */\nconst DEFAULT_RETRY_WINDOW_MS = 60_000;\n\n/** Attempts a rate-limited write-back may make before giving up. */\nconst RETAIN_RETRY_ATTEMPTS = 2;\n\n/** What a retry must still leave room for: `req` aborts a request at 15s. Waiting past the point\n *  where the retry itself could not finish buys nothing. */\nconst REQUEST_BUDGET_MS = 15_000;\n\n/**\n * Submit a write-back, retrying while the API is rate-limiting us AND our write is still the\n * newest one for this session.\n *\n * Retrying is safe rather than duplicative because the payload carries a deterministic\n * `operation_id`: an identical resubmission is collapsed into the original operation server-side.\n *\n * The staleness check is the important half. If another write-back has claimed the cursor since\n * ours — a newer turn, another process — then ours is superseded, and the newer one carries\n * everything we were sending: it replays our buffered payload ahead of its own, or replaces the\n * document outright. Retrying then would spend a hook's remaining time re-sending content that is\n * already on its way.\n */\nasync function submitWithRetry(\n  send: () => Promise<void>,\n  isStillNewest: () => boolean,\n  retryUntil: number\n): Promise<void> {\n  for (let attempt = 0; ; attempt++) {\n    try {\n      return await send();\n    } catch (e) {\n      const limited = e instanceof RateLimitedError;\n      if (!limited || attempt >= RETAIN_RETRY_ATTEMPTS || !isStillNewest()) throw e;\n      // Either honour Retry-After in full or do not retry at all: waiting less than the server\n      // asked would just earn another 429. Whether it fits is the CALLER's clock, not a constant —\n      // a hook process is killed by its host at a known deadline, a long-lived runtime is not.\n      const wait = e.retryAfterMs || 1000;\n      if (Date.now() + wait + REQUEST_BUDGET_MS > retryUntil) throw e;\n      await sleep(wait);\n    }\n  }\n}\n\n/**\n * One write-back at a time per session, keyed by the store the cursors live in.\n *\n * The persistent-plugin runtime fires retains without awaiting them (a turn-driven one and an\n * idle-driven one can overlap), and reading the cursor is not atomic with claiming it — there is an\n * await in between. Two overlapping calls therefore both planned an append from the SAME position\n * and submitted overlapping slices, duplicating turns inside the document; and even serialising the\n * claim alone would leave an append racing a replace on the wire, where the order they land in\n * decides whether the result is correct. Chaining the whole read-plan-send-confirm cycle is what\n * makes the cursor mean what it says: the second call sees the first call's CONFIRMED position.\n */\nconst writeBacks = new WeakMap<RetainCursorStore, Map<string, Promise<void>>>();\n\nfunction serialize(\n  cursors: RetainCursorStore,\n  sessionId: string,\n  write: () => Promise<void>\n): Promise<void> {\n  const perSession = writeBacks.get(cursors) ?? new Map<string, Promise<void>>();\n  writeBacks.set(cursors, perSession);\n  // Chain off the previous write-back whether it succeeded or failed — a failure leaves its payload\n  // buffered on the cursor (or the cursor dirty), which the next call needs to see before it plans.\n  const next = (perSession.get(sessionId) ?? Promise.resolve()).then(write, write);\n  const tail = next.catch(() => {});\n  perSession.set(sessionId, tail);\n  // Drop the entry once it is settled AND still the tail, so a host that outlives many sessions\n  // (opencode runs for days) doesn't accumulate one resolved promise per session id forever.\n  void tail.then(() => {\n    if (perSession.get(sessionId) === tail) perSession.delete(sessionId);\n  });\n  return next;\n}\n\n/**\n * The `context` of a session write-back when `retainContext` is unset. The second sentence keeps an\n * agent's own \"fixed\"/\"passes\" a claim: stored as fact, a later session applied it without checking\n * the code (#4791). It lives here rather than in the bank's retain mission because the mission is\n * seeded once and never reaches a bank that already has one; the context rides on every write.\n */\nexport const DEFAULT_RETAIN_CONTEXT =\n  \"conversation between the user and you (the coding agent): user turns are the user's words and \" +\n  \"decisions, assistant turns are yours. When an assistant turn says something is fixed, passes or \" +\n  'works, record it as the agent\\'s claim (\"the agent reported X fixed\"), not as an established fact.';\n\n/**\n * Live write-back: upsert a running session under a stable document_id, sending only what is new.\n *\n * Given a cursor store, a session that has already been written APPENDS the turns added since the\n * last successful write; the server concatenates them onto the stored document (with \"\\n\", which is\n * why the transcript is JSONL) and re-chunks. Without one — first write, a rewritten transcript, an\n * unconfirmed previous write, or a server too old to be idempotent — it falls back to REPLACING the\n * whole document, which is what this always used to do. See core/retain-cursor.ts for why every\n * uncertain case resolves that way.\n *\n * Uses the same `conversation` strategy as backfilled chats — one strategy for all developer\n * conversations; the mission scales extraction to the substance. The content is a JSON transcript\n * (renderSessionJsonl) whose tool activity is compacted into `role:\"action\"` turns\n * (see core/transcript*.ts).\n */\nexport async function retainLiveSession(\n  client: HindsightClient,\n  sessionId: string,\n  turns: TransportTurn[],\n  startTs: string,\n  harness?: string,\n  opts: {\n    cursors?: RetainCursorStore;\n    stamp?: RetainStamp;\n    retryUntil?: number;\n    /** The transcript file the turns came from, when there is one — see RetainCursor.paths. */\n    transcriptPath?: string;\n  } = {}\n): Promise<void> {\n  const cursors = opts.cursors;\n  if (!cursors)\n    return writeSession(\n      client,\n      sessionId,\n      turns,\n      startTs,\n      harness,\n      opts.stamp,\n      undefined,\n      opts.retryUntil,\n      opts.transcriptPath\n    );\n  // Serialised so the plan is made against the previous write-back's CONFIRMED cursor (see above).\n  return serialize(cursors, sessionId, () =>\n    writeSession(\n      client,\n      sessionId,\n      turns,\n      startTs,\n      harness,\n      opts.stamp,\n      cursors,\n      opts.retryUntil,\n      opts.transcriptPath\n    )\n  );\n}\n\nasync function writeSession(\n  client: HindsightClient,\n  sessionId: string,\n  turns: TransportTurn[],\n  startTs: string,\n  harness?: string,\n  stamp?: RetainStamp,\n  cursors?: RetainCursorStore,\n  /** Absolute time this write-back may keep retrying until; the caller owns its own clock. */\n  retryUntil = Date.now() + DEFAULT_RETRY_WINDOW_MS,\n  transcriptPath?: string\n): Promise<void> {\n  if (!turns.length) return;\n  const refId = `conversation:${sessionId}`;\n  let cursor = cursors?.read(sessionId);\n  // A \"yes\" is remembered on the cursor: hook harnesses run a fresh process per Stop, so without it\n  // every turn re-asked, and one slow or failed probe turned that turn's append into a full replace\n  // (#4560). A \"no\" is not remembered — the server can be upgraded mid-session.\n  const probed = Boolean(cursors) && cursor?.appendSupported !== true;\n  const appendSupported =\n    Boolean(cursors) && (cursor?.appendSupported === true || (await supportsAppend(client)));\n  // The session followed its working folder into another bank (#5812): from here on its turns go\n  // there, and nothing the other bank's document holds or still owes is this bank's business.\n  const moved = Boolean(cursor && cursor.bank !== client.bank);\n  if (moved)\n    log.warn(harness ?? \"\", \"session moved to another bank mid-session\", {\n      session: sessionId,\n      from: cursor?.bank,\n      to: client.bank,\n      atTurn: cursor?.turns,\n    });\n  const segments = advanceSegments(cursor, client.bank);\n  // Only an append can build on a lost write; a replace already re-sends everything. The ops of a\n  // bank the session just left would be looked up in this one, so they are not checked.\n  let ops: string[] = [];\n  if (appendSupported && cursor?.ops?.length && !cursor.dirty && !moved)\n    ({ cursor, ops } = await settleOps(client, cursor));\n  const plan = planRetain(turns, cursor, {\n    appendSupported,\n    bank: client.bank,\n    path: transcriptPath,\n  });\n  // Recorded whenever the probe ran, so a deployment where append never activates shows up in the\n  // diag trail instead of only as oversized retains (#5286). A cached \"yes\" is not re-logged.\n  if (probed) diag(harness ?? \"\", \"retain_mode\", { mode: plan.mode, appendSupported });\n  // Which files the document holds after this write-back. A replace rebuilds it from THIS file\n  // alone, so it forgets the others — which is what lets the file it dropped be appended back as a\n  // segment on its next hook, rather than replacing again.\n  const paths =\n    plan.mode === \"replace\"\n      ? transcriptPath\n        ? [transcriptPath]\n        : undefined\n      : advancePaths(cursor?.paths, transcriptPath);\n  // Appends built but never confirmed. A replace rewrites the whole document from the same\n  // transcript, so it SUBSUMES them; on every other path they go out first, oldest first, before\n  // anything new — the document only ever grows in transcript order. Buffered appends of the bank\n  // the session just left belong to THAT document, so they are never replayed into this one.\n  const outbox = plan.mode === \"replace\" || moved ? [] : (cursor?.pending ?? []);\n  if (plan.mode === \"skip\" && !outbox.length) return;\n\n  /** Identity of ONE payload: a resubmission of the same bytes is collapsed server-side into the\n   *  original operation instead of extracting (or appending) twice. */\n  const opId = (mode: string, content: string) =>\n    uuidV5(`${client.bank}\\n${refId}\\n${mode}\\n${content}`);\n  const submit = (content: string, operationId: string, append: boolean) =>\n    client.retain(\n      content,\n      // Configured context wins. Extraction reads this to decide whose claim a sentence is, so the\n      // default names both speakers: the previous \"coding agent session\" said nothing about\n      // authorship and let an assistant's proposal be recorded as the user's decision.\n      stamp?.context ?? DEFAULT_RETAIN_CONTEXT,\n      refId,\n      // Configured tags first, built-ins last and deduped: `source:chat` and `harness:<id>` are what\n      // the documents list filters and draws its agent logo from, so a template cannot displace them.\n      [\n        ...new Set([\n          ...(stamp?.tags ?? []),\n          \"source:chat\",\n          ...(harness ? [`harness:${harness}`] : []),\n        ]),\n      ],\n      \"conversation\",\n      {\n        timestamp: startTs,\n        updateMode: append ? \"append\" : undefined,\n        operationId,\n        metadata: {\n          ...stamp?.metadata, // configured first: the built-ins below win on any key collision\n          source: \"chat\",\n          session_id: sessionId,\n          ref_id: refId,\n          ...(harness ? { harness } : {}),\n        },\n      }\n    );\n\n  // The position the cursor reaches once everything below has been applied. On a \"skip\" this is\n  // exactly where the cursor already is: skip means the transcript ends at cursor.turns.\n  const next = {\n    turns: turns.length,\n    fingerprint: fingerprintTurns(turns, turns.length),\n    bank: client.bank,\n    ...(paths ? { paths } : {}),\n    ...(segments ? { segments } : {}),\n    ...(appendSupported ? { appendSupported: true } : {}),\n  };\n  /** `next` plus the ops to check on the next write-back, with `id` newly accepted. */\n  const accepted = (id?: string) => {\n    if (id) ops = [...ops, id].slice(-MAX_CURSOR_OPS);\n    return ops.length ? { ...next, ops } : next;\n  };\n  // Still ours to retry only while the cursor holds the claim we write below.\n  const stillOurs = () => {\n    if (!cursors) return true;\n    const now = cursors.read(sessionId);\n    return now?.turns === next.turns && now?.fingerprint === next.fingerprint;\n  };\n\n  if (plan.mode === \"replace\") {\n    // Only this bank's share: a session that moved here keeps its earlier turns in the bank they\n    // were written to (#5812). A move with nothing new since has no share to start a document with.\n    const share = bankTurns(turns, segments, client.bank);\n    if (!share.length) return;\n    const content = renderSessionJsonl(refId, share, startTs);\n    // Nothing to buffer: replace is idempotent by construction, so a later one re-establishes the\n    // same truth from the same transcript. Claim the position unconfirmed so an outcome we never\n    // learn resolves to another replace rather than an append onto an unknown state.\n    // The id also names what the document held before, from the cursor: content alone repeats\n    // when a session returns to an earlier branch (A → B → A), and the server acknowledges a\n    // completed id without applying it, leaving B stored (#5845). A retry still has the same base.\n    const base = cursor ? `${cursor.turns}\\n${cursor.fingerprint}` : \"\";\n    cursors?.write(sessionId, { ...next, dirty: true });\n    const operationId = opId(\"replace\", `${base}\\n${content}`);\n    await submitWithRetry(() => submit(content, operationId, false), stillOurs, retryUntil);\n    ops = []; // the replace re-sends every turn, so nothing older can still lose any\n    cursors?.write(sessionId, accepted(operationId));\n    return;\n  }\n\n  const queue = [...outbox];\n  if (plan.mode === \"append\") {\n    const content = turns\n      .slice(plan.fromTurn)\n      .map((t) => JSON.stringify(t))\n      .join(\"\\n\");\n    queue.push({ content, operationId: opId(\"append\", content), at: Date.now() });\n  }\n\n  // Claim the position BEFORE the request, WITH the bytes: a rejected retain — or a process the\n  // host kills mid-write — leaves a replayable buffer rather than a cursor that can only be\n  // recovered by re-sending (and re-extracting) the entire transcript, forever, for the rest of the\n  // session (#3989). Replay is safe precisely because the bytes and the operation id are unchanged:\n  // a write the server DID commit collapses into that same operation instead of appending twice,\n  // which is the one thing appending onto an unknown state could otherwise get wrong.\n  cursors?.write(sessionId, { ...accepted(), pending: queue });\n  for (let i = 0; i < queue.length; i++) {\n    // One request per entry, each able to burn the full 15s abort — where this used to send exactly\n    // once. Never START one that cannot finish inside the caller's budget: a hook harness is killed\n    // by its host at `retryUntil` (retain-hook's hostDeadline), and a flush that overruns it buys\n    // nothing. The first entry always goes out, so a chronically short budget still makes progress;\n    // whatever is left is already durable, so the next write-back sends it.\n    if (i > 0 && Date.now() + REQUEST_BUDGET_MS > retryUntil) return;\n    const entry = queue[i];\n    await submitWithRetry(\n      () => submit(entry.content, entry.operationId, true),\n      stillOurs,\n      retryUntil\n    );\n    // Confirmed: drop it immediately, so a failure on a LATER entry cannot resubmit it as part of\n    // the next flush. Whatever is still queued when this throws is what the next flush replays.\n    const remaining = queue.slice(i + 1);\n    const done = accepted(entry.operationId);\n    cursors?.write(sessionId, remaining.length ? { ...done, pending: remaining } : done);\n  }\n}\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/cordis.patch.yml",
      "content": "# DeepSeek Harness profile layer for Hindsight memory.\n#\n# `dsh plugin --profile <name> add @vectorize-io/hindsight-coding-agents` installs this package into\n# the profile and — because package.json declares `dsh.bundle.patch` — appends this file to the\n# profile's ordered bundle list. Nothing else needs editing: the row below mounts on the host plane,\n# where the pre-step/session-start/turn-stopping events and the layered tools registry all reach\n# every session, including the Web surface's per-session agent presets.\n#\n# Memory itself is configured OUTSIDE dsh, in ~/.hindsight/coding-agent.json (server URL, token,\n# bank naming, opt-outs) — the same file every other Hindsight coding-agent harness reads. To turn\n# it off for one profile without uninstalling, patch this row in the profile's own\n# cordis.patch.yml:\n#\n#   - id: hindsight\n#     disabled: true\n- insert:\n    - id: hindsight\n      name: \"@vectorize-io/hindsight-coding-agents/dsh\"\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/config.ts",
      "content": "/**\n * ONE config file: ~/.hindsight/coding-agent.json.\n *\n * Layering, later wins per field:\n *   1. built-in defaults\n *   2. environment variables (ENV_KEYS below) — a FALLBACK for containers, CI and secret managers\n *   3. the config file's top level\n *   4. its `harnesses.<name>` section for the asking harness\n *\n * There is deliberately NO project-local config: a second, repo-carried file was both a security\n * surface (untrusted repos influencing memory behavior) and a second place to look. Per-repo bank\n * routing is `mapPathToBank`; per-agent differences are `harnesses.<name>`.\n */\nimport { readFileSync } from \"node:fs\";\nimport { homedir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { DEFAULT_SEED_LIMIT } from \"./seed\";\nimport { isOptedIn, pathSection } from \"./bank\";\nimport { log } from \"./log\";\nimport {\n  DEFAULT_OBSERVATION_SCOPES,\n  DEFAULT_PAGE_SEARCH_LIMIT,\n  type ObservationScopes,\n} from \"./hindsight\";\nimport {\n  type CustomPagesConfig,\n  DEFAULT_PAGE_TRIGGER_CRON,\n  DEFAULT_RETAIN_EXTRACTION_MODE,\n  isHashedCron,\n  PAGE_NAMES,\n  type PagesConfig,\n  parseHashedCron,\n  PLUGIN_GOVERNED_BANK_FIELDS,\n  RETAIN_EXTRACTION_MODES,\n  type RetainExtractionMode,\n} from \"./missions\";\n\n/** Default config-file path: ~/.hindsight/coding-agent.json */\nexport // HINDSIGHT_CONFIG joins the two env exceptions (diag/log files): it points at THE config file,\n// for containers and test harnesses where $HOME isn't the right anchor. Still one file.\nconst CONFIG_PATH =\n  process.env.HINDSIGHT_CONFIG || join(homedir(), \".hindsight\", \"coding-agent.json\");\n\n/** Daemon-mode defaults. The port matches the old per-agent Claude Code plugin so a machine that\n *  already ran that daemon keeps using the same one. */\nexport const DEFAULT_DAEMON_PORT = 9077;\nexport const DEFAULT_DAEMON_PROFILE = \"coding-agent\";\n\n/** Incremental git-sync settings (see core/sync.ts). */\n/** The config file's shape — every field optional; omitted fields take the documented default. */\nexport interface RawConfig {\n  /** Where memory lives. All three modes speak the same HTTP API; they differ only in who runs it:\n   *   \"cloud\"       — Hindsight Cloud (the default `apiUrl`)\n   *   \"self-hosted\" — a Hindsight server you run; set `apiUrl` to it\n   *   \"daemon\"      — a local `hindsight-embed` daemon this plugin starts on demand, at\n   *                   127.0.0.1:{apiPort}. `apiUrl` is ignored in this mode.\n   * Omitted, it is inferred: \"daemon\" is never assumed, so an existing config keeps talking to\n   * whatever `apiUrl` it already names. */\n  serverMode?: \"cloud\" | \"self-hosted\" | \"daemon\";\n  apiUrl?: string; // Hindsight API base URL (default https://api.hindsight.vectorize.io — Cloud; set to http://localhost:8888 for a local server)\n  apiToken?: string; // bearer token (optional)\n  /** Daemon mode: port the local daemon listens on (default 9077).\n   *  NOT 8888 — that is the conventional port for a server you run yourself, and a daemon must\n   *  never squat on it. A healthy server already on this port is adopted rather than restarted. */\n  apiPort?: number;\n  /** Daemon mode: seconds of inactivity before the daemon exits. Unset means it never exits on\n   *  its own — `hindsight-embed`'s own default, which every other Hindsight integration also\n   *  ships. This used to default to 300 here, which made the plugin the only thing on the machine\n   *  opting a shared daemon into an auto-exit nobody asked for. There is deliberately no\n   *  stop-on-session-end either: one daemon is shared by every agent and repo on the machine, so\n   *  ending one session must not cut memory out from under another. */\n  daemonIdleTimeout?: number;\n  /** Daemon mode: `hindsight-embed` profile name, i.e. which local database is used (default\n   *  \"coding-agent\"). Separate profiles keep unrelated setups from sharing memory. */\n  daemonProfile?: string;\n  /** Daemon mode: which `hindsight-embed` release to run via uvx (default \"latest\"). */\n  embedVersion?: string;\n  /** Daemon mode: local `hindsight-embed` checkout to run instead of a published release (dev). */\n  embedPackagePath?: string;\n  bankId?: string; // EXPLICIT memory bank id — set = static bank; unset = per-repo dynamic (core/bank.ts)\n  dynamicBankId?: boolean; // force dynamic resolution even when bankId is set (default: dynamic iff no bankId)\n  bankIdTemplate?: string; // dynamic bank id format (default \"coding-agent::{gitProject}\" — harness-neutral) —\n  //   placeholders: {gitProject} {project} {harness} {channel} {user} (see core/bank.ts)\n  mapPathToBank?: Record<string, string>; // absolute path -> bank; longest prefix wins; overrides everything\n  resolveWorktrees?: boolean; // {gitProject}: worktrees share the main repo's bank (default true)\n  /** Run memory ONLY in projects that were opted in (default false: every project gets memory,\n   *  which is what makes the plugin zero-setup). With it on, an unlisted project is inert — no\n   *  bank is created, nothing is retained, no seed runs — so unrelated work leaves no trace. */\n  optInOnly?: boolean;\n  /** Directories opted in, matched as PREFIXES with `~` expanded: approving a directory approves\n   *  the repos beneath it, and each still gets its own dynamic bank. A `mapPathToBank` entry counts\n   *  as opted in too, since routing a path to a named bank already declares that project. */\n  optInPaths?: string[];\n  harness?: string; // runtime adapter (default \"opencode\")\n  disabled?: boolean; // hard off-switch — inert plugin, for a no-memory baseline (default false)\n  /** Session transcript write-back (default true; set false to opt out). Honored by every\n   *  harness: the hook harnesses' Stop write-back and the persistent plugins' per-turn\n   *  cadence alike. Gates ONLY the transcript — recall, git ingest, seeding and the memory\n   *  tools keep working (that is `disabled`'s job). */\n  retainSessions?: boolean;\n  /** Cap on concurrent retain-related requests the client sends to the API (default 10):\n   *  drain()'s per-operation polls and deepen's chat/git retain pools. A single request returning\n   *  200 while bursts get 429s means the server is rate-limiting concurrency, not total volume —\n   *  lower this rather than raising it. */\n  maxParallelRetains?: number;\n  /** Automatic session-reflect timeout (default 20000). The default, with the fallback chain after\n   *  it, fits the 30s prompt-hook timeout the installer registers on hook harnesses; going higher\n   *  there needs that host timeout raised too, or the host kills the hook mid-reflect. */\n  reflectTimeoutMs?: number;\n  /** Timeout for the agent-invoked `hindsight_reflect` tool (default 330000). Deliberately its own\n   *  knob and much larger than `reflectTimeoutMs`: that one bounds an automatic hook that must fit\n   *  the host's hook window, whereas this one bounds a call the agent made on purpose and waits on,\n   *  whose `budget: \"high\"` synthesis on a populated bank can run for minutes. The default sits\n   *  ABOVE the server's own reflect wall timeout (HINDSIGHT_API_REFLECT_WALL_TIMEOUT, 300s) so the\n   *  server decides when to give up, not an arbitrary client deadline (#3590). Unset, it inherits\n   *  an explicitly-raised `reflectTimeoutMs` — a user who raised that meant \"let reflect run\". */\n  reflectToolTimeoutMs?: number;\n  /** Retrieval timeout for autoInject \"pages\"/\"recall\" (default 7000), and the shared budget for\n   *  the page-search -> recall fallback after a reflect timeout/5xx. On hook harnesses, the full\n   *  reflect + fallback must fit the host's prompt-hook timeout (30s by default). */\n  injectTimeoutMs?: number;\n  /** Reflect budget for the `hindsight_reflect` tool: \"low\" | \"mid\" | \"high\" (default \"high\").\n   *  Drop to \"mid\"/\"low\" on a large bank where high-budget synthesis exceeds the server's wall\n   *  timeout. The automatic session-start reflect is NOT affected — it always uses \"low\" to fit\n   *  its hook window. */\n  reflectBudget?: \"low\" | \"mid\" | \"high\";\n  /** What to inject on the session's first prompt (default \"reflect\"):\n   *    \"reflect\" — one low-budget reflect synthesis (falls back to pages, then recall, on timeout/5xx)\n   *    \"pages\"   — the pages matching the prompt by search (retrieval only, no LLM)\n   *    \"recall\"  — the bank's memories recalled for the prompt (`recallOptions`; no LLM)\n   *    \"none\"    — nothing; the tool guide routes new goals through pages before optional reflection */\n  autoInject?: AutoInject;\n  /** @deprecated Use `autoInject`. Still honoured: false = `autoInject: \"none\"`, true = \"reflect\";\n   *  ignored when `autoInject` is set. Setting it logs a deprecation warning. */\n  autoReflect?: boolean;\n  /** Pages ONE search returns (default 3). Applies wherever the bank is searched: the\n   *  `autoInject: \"pages\"` injection, the reflect fallback, and the agent's\n   *  `hindsight_search_pages` tool — the limit lives on the client so they can't drift. */\n  pageSearchLimit?: number;\n  /** Recall-request overrides, merged key-by-key into the body every recall sends (the\n   *  `autoInject: \"recall\"` source and the reflect fallback) — `{\"types\": [\"world\",\n   *  \"experience\"], \"max_tokens\": 4000}`. Keys are the API's own recall parameters, passed\n   *  through unchanged, so a parameter the API gains needs no new setting here; `query` is the\n   *  one field a config cannot replace. Defaults to `{\"types\": [\"observation\"], \"budget\": \"low\",\n   *  \"max_tokens\": 2000, \"include\": {\"entities\": null}}`.\n   *\n   *  A bank with consolidation disabled never grows observations, and the default recall comes\n   *  back empty on it: those set `{\"types\": [\"world\", \"experience\"]}`, or `{\"types\": null}` for\n   *  every type. */\n  recallOptions?: Record<string, unknown>;\n  /** Your own guidance for how the agent should treat memory, added AFTER the built-in tool guide\n   *  (SessionStart and every refresh) and after the crediting note that comes back with\n   *  `hindsight_search_pages` results. It adds to the built-in text, never replaces it,\n   *  so the plugin's call triggers and crediting rule keep up with releases (#4791). */\n  toolGuideExtra?: string;\n  pageRefreshEveryTurns?: number; // page refresh cadence in user turns (default 1; 0 also means 1)\n  /** What it COSTS to keep this project's pages current — the trigger stamped on every\n   *  page this plugin creates (the seeded taxonomy and each captured initiative):\n   *    \"cron\" (default)         — refresh on `pageTriggerCron` only, and only when actually stale\n   *    \"auto-refresh\"           — refresh after every consolidation that produced new material\n   *    \"manual\"                 — never refresh on its own; the tools and control plane still can\n   *  Auto-refresh is both the most current and the most expensive: one LLM synthesis per page per\n   *  consolidation, which adds up fast across auto-surveyed repos (#3506) — hence the hourly\n   *  staggered schedule as the default. Existing pages keep the trigger they were created with —\n   *  this changes what NEW pages get. */\n  pageTriggerType?: \"auto-refresh\" | \"cron\" | \"manual\";\n  /** Schedule for `pageTriggerType: \"cron\"` — UTC, standard 5-field cron, e.g. \"0 3 * * *\".\n   *  Defaults to DEFAULT_PAGE_TRIGGER_CRON (\"H * * * *\": hourly, on each page's own minute).\n   *  A field written `H` (\"0 3 * * *\" -> \"H H * * *\") is replaced per page by a value hashed from\n   *  bank + page name, so pages spread across the period instead of all firing on the one minute\n   *  this shared setting names. See `expandCronHash` in core/missions.ts. */\n  pageTriggerCron?: string;\n  /** Per-page configuration for the seeded pages, keyed by page name (case-insensitive):\n   *    \"Component map\": false                                   — don't seed this page at all\n   *    \"Key decisions and rationale\": {\"source_query\": \"...\"}   — seed it, asking your question\n   *  Omitted (the default) seeds every taxonomy page with its built-in query.\n   *\n   *  This is the supported way to own a page's query. The plugin re-syncs a page whose live query\n   *  differs from the one it is configured to have, so a query edited through the API or the\n   *  control plane is replaced on the next session (#4460); setting it here makes your wording the\n   *  configured one, and the re-sync then keeps it.\n   *\n   *  A disabled page is NOT deleted — one already seeded keeps its content and simply stops being\n   *  re-synced. The subject-scoping clause is appended to a custom query too, so a reworded page\n   *  cannot start reporting a dependency's decisions as this project's own (#3476).\n   *\n   *  File-only, like `recallOptions` — a nested object does not flatten into an env var. In a\n   *  `banks.<id>` section it REPLACES the global map rather than merging into it. */\n  pages?: PagesConfig;\n  /** Pages of your OWN, seeded alongside the taxonomy and keyed by the name they get:\n   *    \"Security posture\": {\"source_query\": \"...\", \"tags\": [\"knowledge:decision\"]}\n   *  `source_query` is the question the page answers. `tags` picks which facts feed it and is\n   *  optional — the trigger matches tags with `all`, so omitting them means no tag constraint and\n   *  the page synthesizes from everything the bank holds, rather than from nothing.\n   *\n   *  Deliberately a SEPARATE key from `pages`, not another shape inside it: `pages` rejects a name\n   *  that matches no seeded page, which is what turns a typo into a warning instead of silence. If\n   *  an unknown key there meant \"create a page\", `\"Componnet map\"` would quietly create an empty\n   *  second page instead of rewording the one that was meant.\n   *\n   *  These are re-synced like the seeded ones — the config is the source of truth for the query —\n   *  so rewording one here reaches the live page on the next session. A page you create yourself\n   *  in the control plane is a different thing entirely and is never touched.\n   *\n   *  File-only, and replaced (not merged) by a `banks.<id>` section, exactly like `pages`. */\n  customPages?: CustomPagesConfig;\n  autoSeed?: boolean; // SessionStart: auto-seed a cold repo's bank from git history (default true)\n  seedLimit?: number; // git-log document: keeps between seedLimit/2 and seedLimit newest commits (default 300)\n  codebaseSurvey?: boolean; // SessionStart: spawn a headless claude to survey a cold repo's structure (default true)\n  surveyModel?: string; // model passed to the headless survey's `claude -p --model` (default \"haiku\")\n  surveyBudgetUsd?: number; // spend cap passed to the headless survey's `claude -p --max-budget-usd` (default 2)\n  /** Plugin log verbosity (\"debug\" | \"info\" | \"warn\" | \"error\", default \"info\");\n   *  HINDSIGHT_LOG_LEVEL overrides for ad-hoc debugging. */\n  logLevel?: \"debug\" | \"info\" | \"warn\" | \"error\";\n  /** Keep the installed runtime current by itself (default true). Once a day a session start asks\n   *  npm for the published version and, when it is newer, re-stages ~/.hindsight/coding-agents in\n   *  the background — the copy every wired agent's hooks already point at. It rewires no host\n   *  config, so a release that adds a NEW hook entry point still needs a manual `install`.\n   *  Set false to pin the installed version (air-gapped machines, or a deliberate downgrade);\n   *  updating is then `npx @vectorize-io/hindsight-coding-agents install` again, as before. */\n  autoUpdate?: boolean;\n  surveyRefreshCommits?: number; // re-run the survey at SessionStart once this many commits have accrued since the last one, so structural pages track an evolving architecture (default 20; 0 = cold-seed only)\n  /** How git history feeds memory — seeding AND keeping current use the same engine:\n   *  \"message\" = commit messages only (cheap aggregated doc, re-upserted when HEAD moves);\n   *  \"full\"    = messages + every recent commit's full diff (progressive batches, newest first);\n   *  \"none\"    = git ingestion off entirely. Default \"message\" (cheap by default; opt into depth). */\n  gitIngest?: \"message\" | \"full\" | \"none\";\n  /** Extra tags stamped on every session write-back, e.g. [\"project:{gitProject}\", \"env:work\"].\n   *  Placeholders: {gitProject} {project} {harness} {bankId} {sessionId} {timestamp} {channel}\n   *  {user} (see core/retain-stamp.ts). Mainly for a SHARED bank, where the bank id no longer says\n   *  which repo a memory came from. Built-in tags win on conflict. */\n  retainTags?: string[];\n  /** Extra metadata stamped on every session write-back, e.g. {\"repo\": \"{gitProject}\"}. Same\n   *  placeholders as retainTags; built-in metadata (harness attribution) wins on conflict. */\n  retainMetadata?: Record<string, string>;\n  /** The `context` sent with every session write-back (default: DEFAULT_RETAIN_CONTEXT in\n   *  core/chat.ts, which names the user and the agent as the two speakers). Same placeholders as\n   *  retainTags. Extraction reads this to decide WHOSE claim a sentence is. */\n  retainContext?: string;\n  /** Let the plugin shape the bank's own configuration — the retain strategies it writes under,\n   *  the `knowledge` entity-label group, and (on a bank that has none) the missions (default true).\n   *\n   *  Writing is ADDITIVE: the plugin adds what the bank does not already define and never\n   *  overwrites an existing value, so an edit made in the control plane survives (#3927) — except\n   *  the extraction mode of its own strategies, which follows `retainExtractionMode`. Set false\n   *  to keep it out of the bank's configuration entirely — for a bank you shape yourself, or share\n   *  with non-coding work. That bank should then define the strategies this plugin retains under\n   *  (`git`, `gitlog`, `conversation`, `document`, `survey`): the server does not reject a retain\n   *  naming a strategy the bank lacks, it logs a warning and extracts with the bank's own config\n   *  instead — so a diff, a transcript and a survey marker all get the same generic treatment.\n   *  Pages are seeded either way (see `pageTriggerType`). */\n  manageBankConfig?: boolean;\n  /** How the server extracts memories from what this plugin retains — sessions, commits, documents\n   *  (default \"concise\"). One of \"concise\", \"verbose\", \"verbatim\", \"chunks\" (store the text with no\n   *  extraction). Every Stop writes the session back, so this is what each turn costs: \"verbose\"\n   *  extracts more detail at several times the tokens. Kept in sync on the plugin's own retain\n   *  strategies on every session start, so changing it reaches an existing bank too (unless\n   *  `manageBankConfig` is false). Anything else falls back to the default. */\n  retainExtractionMode?: RetainExtractionMode;\n  /** Bank-config fields of your own for the banks this plugin shapes, e.g.\n   *    {\"enable_observations\": false, \"enable_auto_consolidation\": false,\n   *     \"mental_model_min_refresh_interval_seconds\": 21600}\n   *  Keys are the bank-config API's own field names, passed straight through, so anything the\n   *  bank-config accepts is settable here. Written under the same rule as the rest of the\n   *  template — only where the bank does not already define the field — so a bank the plugin\n   *  creates is born with these instead of the server's defaults, while a value you set in the\n   *  control plane is never overwritten (#4725). Wins over the template on a key both name\n   *  (`enable_observations`). The fields the plugin governs itself (`retain_strategies`,\n   *  `entity_labels`, `retain_extraction_mode`) are refused with a warning: the first two are\n   *  merged per entry, the last follows `retainExtractionMode`. Ignored when `manageBankConfig`\n   *  is false.\n   *\n   *  File-only, like `recallOptions` — a nested object does not flatten into an env var. In a\n   *  `banks.<id>` section it REPLACES the global map rather than merging into it. */\n  defaultBankConfig?: Record<string, unknown>;\n  /** How consolidation groups the observations this plugin's memories feed (default \"shared\" — one\n   *  global scope per bank, so every agent working a repo builds ONE set of beliefs; see\n   *  DEFAULT_OBSERVATION_SCOPES). \"combined\" restores the server default of one scope per distinct\n   *  tag set, \"per_tag\" one per tag, \"all_combinations\" one per subset; a string[][] declares the\n   *  scopes literally. Anything else falls back to the default. */\n  observationScopes?: ObservationScopes;\n  /** Per-harness overrides of any of the fields above, keyed by harness name (\"opencode\",\n   *  \"claude-code\", ...). Lets one config file give each agent its own bank/settings. */\n  harnesses?: Record<string, Omit<RawConfig, \"harnesses\">>;\n  /** Per-BANK overrides, applied AFTER bank resolution — the per-repo opt-in/out surface, keyed\n   *  by the RESOLVED bank id (run a session once or check the banner to see it). Any behavioral\n   *  field, plus `bank` to RENAME the destination (single hop: the section is selected by the\n   *  resolved id, the rename is literal — several ids may converge on one shared bank).\n   *  Bank-resolution fields (bankId/template/map/...) are ignored here. Example:\n   *    \"banks\": { \"coding-agent::secret-client\": { \"disabled\": true },\n   *               \"coding-agent::old-name\": { \"bank\": \"team::shared\" },\n   *               \"coding-agent::big-mono\": { \"gitIngest\": \"full\", \"retainSessions\": false } } */\n  banks?: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\"> & { bank?: string }>;\n  /** Per-DIRECTORY overrides, keyed by absolute path prefix (`~` allowed; longest prefix wins;\n   *  a linked worktree uses its main checkout's entry). Applied after bank resolution and before\n   *  the `banks.<id>` section, so one entry can send every repo under a directory to another\n   *  server or tenant while each repo keeps its own bank. Bank-resolution fields are ignored here,\n   *  as in `banks`. Example:\n   *    \"paths\": { \"~/work/client-x\": { \"apiToken\": \"client-x-key\" } } */\n  paths?: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\" | \"paths\">>;\n}\n\n/** Fully-resolved config: every field present. */\nexport interface Config {\n  serverMode: \"cloud\" | \"self-hosted\" | \"daemon\";\n  /** The EFFECTIVE base URL. In daemon mode this is already 127.0.0.1:{apiPort}, so every caller\n   *  that builds a client keeps working without knowing which mode is active. */\n  apiUrl: string;\n  apiToken?: string;\n  apiPort: number;\n  /** Undefined = never told the daemon to auto-exit; see RawConfig above. */\n  daemonIdleTimeout?: number;\n  daemonProfile: string;\n  embedVersion?: string;\n  embedPackagePath?: string;\n  bankId?: string; // resolved per-directory via deriveBankIdOrSkip — see core/bank.ts\n  dynamicBankId?: boolean;\n  bankIdTemplate?: string;\n  mapPathToBank?: Record<string, string>;\n  resolveWorktrees?: boolean;\n  optInOnly: boolean;\n  optInPaths: string[];\n  harness: string;\n  disabled: boolean;\n  retainSessions: boolean;\n  maxParallelRetains: number;\n  reflectTimeoutMs: number;\n  reflectToolTimeoutMs: number;\n  injectTimeoutMs: number;\n  reflectBudget: \"low\" | \"mid\" | \"high\";\n  autoInject: AutoInject;\n  pageSearchLimit: number;\n  recallOptions: Record<string, unknown>;\n  toolGuideExtra?: string;\n  pageRefreshEveryTurns: number;\n  pageTriggerType: \"auto-refresh\" | \"cron\" | \"manual\";\n  pageTriggerCron?: string;\n  pages: PagesConfig;\n  customPages: CustomPagesConfig;\n  autoSeed: boolean;\n  seedLimit: number;\n  codebaseSurvey: boolean;\n  surveyModel: string;\n  surveyBudgetUsd: number;\n  surveyRefreshCommits: number;\n  gitIngest: \"message\" | \"full\" | \"none\";\n  retainTags: string[];\n  retainMetadata: Record<string, string>;\n  retainContext?: string;\n  manageBankConfig: boolean;\n  retainExtractionMode: RetainExtractionMode;\n  defaultBankConfig: Record<string, unknown>;\n  observationScopes: ObservationScopes;\n  banks: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\"> & { bank?: string }>;\n  paths: Record<string, Omit<RawConfig, \"banks\" | \"harnesses\" | \"paths\">>;\n  logLevel: \"debug\" | \"info\" | \"warn\" | \"error\";\n  autoUpdate: boolean;\n}\n\n/**\n * The page-refresh trigger a raw config asks for: the schedule kind, and the expression it fires on.\n *\n * `\"cron\"` is the default and needs no `pageTriggerCron`: an omitted expression takes\n * DEFAULT_PAGE_TRIGGER_CRON, so the common config — none of these fields at all — is an hourly\n * staggered refresh. A user who wants pages to stop refreshing on their own writes \"manual\".\n *\n * A malformed `H` is refused here and not one step later: `expandCronHash` leaves an expression it\n * cannot read alone, so an unchecked `\"H(9-3) * * * *\"` would reach the server verbatim and fail\n * page creation with a cron parse error naming syntax this package invented. Such an expression\n * takes the default schedule, with a warning — the same as writing none. Ordinary cron syntax\n * stays unvalidated: the server owns that, and duplicating its parser here would only disagree\n * with it.\n */\nfunction resolvePageTrigger(raw: RawConfig): {\n  type: \"auto-refresh\" | \"cron\" | \"manual\";\n  cron?: string;\n} {\n  if (raw.pageTriggerType === \"manual\") return { type: \"manual\" };\n  if (raw.pageTriggerType === \"auto-refresh\") return { type: \"auto-refresh\" };\n  if (raw.pageTriggerType !== undefined && raw.pageTriggerType !== \"cron\")\n    log.warn(\n      \"config\",\n      `ignoring pageTriggerType=${JSON.stringify(raw.pageTriggerType)} — ` +\n        \"expected cron|auto-refresh|manual\"\n    );\n  const cron = raw.pageTriggerCron?.trim();\n  if (!cron) return { type: \"cron\", cron: DEFAULT_PAGE_TRIGGER_CRON };\n  if (!isHashedCron(cron) || parseHashedCron(cron)) return { type: \"cron\", cron };\n  log.warn(\n    \"config\",\n    `pageTriggerCron ${JSON.stringify(cron)} has a malformed hashed field — ` +\n      'write `H` or `H(<lo>-<hi>)` within the field\\'s own range, e.g. \"H H(0-5) * * *\" — ' +\n      `falling back to ${JSON.stringify(DEFAULT_PAGE_TRIGGER_CRON)}`\n  );\n  return { type: \"cron\", cron: DEFAULT_PAGE_TRIGGER_CRON };\n}\n\n/**\n * Validate `pages`, dropping anything unusable with a warning.\n *\n * A key matching no seeded page is the mistake worth catching loudly: it reads as having disabled\n * or reworded something and silently does nothing, so the warning names it alongside the set that\n * would have worked. Values are checked for the same reason — `{\"source_query\": 5}` would\n * otherwise travel and become a page whose description is `5`.\n */\nfunction resolvePages(raw: RawConfig[\"pages\"]): PagesConfig {\n  // Widened deliberately: this arrives from a hand-edited JSON file, so the declared type says\n  // what is meant, not what is there.\n  const value: unknown = raw;\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) return {};\n  const out: PagesConfig = {};\n  for (const [name, entry] of Object.entries(value as Record<string, unknown>)) {\n    if (!PAGE_NAMES.some((known) => known.toLowerCase() === name.trim().toLowerCase())) {\n      log.warn(\n        \"config\",\n        `ignoring pages[${JSON.stringify(name)}] — no seeded page has that name; ` +\n          `expected one of: ${PAGE_NAMES.join(\", \")}`\n      );\n      continue;\n    }\n    if (entry === false) {\n      out[name] = false;\n      continue;\n    }\n    const query: unknown =\n      entry && typeof entry === \"object\" && !Array.isArray(entry)\n        ? (entry as { source_query?: unknown }).source_query\n        : undefined;\n    if (typeof query === \"string\" && query.trim()) {\n      out[name] = { source_query: query };\n      continue;\n    }\n    log.warn(\n      \"config\",\n      `ignoring pages[${JSON.stringify(name)}]=${JSON.stringify(entry)} — ` +\n        'expected false, or {\"source_query\": \"<your question>\"}'\n    );\n  }\n  return out;\n}\n\n/**\n * Validate `customPages` — the pages a user defines, as opposed to the taxonomy that `pages` reworks.\n *\n * A name colliding with a seeded page is refused rather than merged: the two keys mean different\n * things (rework the plugin's page vs. create your own), and picking one for the user would be a\n * guess. `tags` is optional and an absent one is not an empty page — see CustomPage.\n */\nfunction resolveCustomPages(raw: RawConfig[\"customPages\"]): CustomPagesConfig {\n  // Widened deliberately, like resolvePages: a hand-edited JSON file says what is meant, not what\n  // is there.\n  const value: unknown = raw;\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) return {};\n  const out: CustomPagesConfig = {};\n  for (const [rawName, entry] of Object.entries(value as Record<string, unknown>)) {\n    const name = rawName.trim();\n    if (!name) continue;\n    if (PAGE_NAMES.some((known) => known.toLowerCase() === name.toLowerCase())) {\n      log.warn(\n        \"config\",\n        `ignoring customPages[${JSON.stringify(rawName)}] — that is a seeded page; ` +\n          \"reword it under `pages` instead\"\n      );\n      continue;\n    }\n    const query: unknown =\n      entry && typeof entry === \"object\" && !Array.isArray(entry)\n        ? (entry as { source_query?: unknown }).source_query\n        : undefined;\n    if (typeof query !== \"string\" || !query.trim()) {\n      log.warn(\n        \"config\",\n        `ignoring customPages[${JSON.stringify(rawName)}]=${JSON.stringify(entry)} — ` +\n          'expected {\"source_query\": \"<your question>\"}'\n      );\n      continue;\n    }\n    const rawTags: unknown = (entry as { tags?: unknown }).tags;\n    // A stray number or nested object would reach the API as a tag and fail page creation.\n    const tags = Array.isArray(rawTags)\n      ? rawTags.filter((t): t is string => typeof t === \"string\" && t.trim() !== \"\")\n      : [];\n    out[name] = tags.length ? { source_query: query, tags } : { source_query: query };\n  }\n  return out;\n}\n\n/** Default timeout for the automatic hook reflect — see RawConfig.reflectTimeoutMs. */\nexport const DEFAULT_REFLECT_TIMEOUT_MS = 20_000;\n/** Default timeout for the agent-invoked `hindsight_reflect` tool — see RawConfig.reflectToolTimeoutMs. */\nexport const DEFAULT_REFLECT_TOOL_TIMEOUT_MS = 330_000;\n/** Default retrieval budget for automatic injection — see RawConfig.injectTimeoutMs. */\nexport const DEFAULT_INJECT_TIMEOUT_MS = 7_000;\n\nconst REFLECT_BUDGETS = [\"low\", \"mid\", \"high\"] as const;\n\n/**\n * Which reflect budget the `hindsight_reflect` tool should ask for.\n *\n * An unrecognized value takes the default rather than travelling: the API rejects an unknown budget\n * outright, which would turn a typo here into a hard tool failure on every call.\n */\nfunction resolveReflectBudget(raw: RawConfig): \"low\" | \"mid\" | \"high\" {\n  const value: unknown = raw.reflectBudget;\n  if (value === undefined) return \"high\";\n  if (typeof value === \"string\" && (REFLECT_BUDGETS as readonly string[]).includes(value))\n    return value as \"low\" | \"mid\" | \"high\";\n  log.warn(\"config\", `ignoring reflectBudget=${JSON.stringify(value)} — expected low|mid|high`);\n  return \"high\";\n}\n\n/** The server's scalar scoping modes; anything else in this field has to be an explicit scope list. */\n// `per_source` is this plugin's own mode, resolved per document in `resolveRetainScopes` and never\n// sent to the server; the rest are the server's.\nconst OBSERVATION_SCOPE_MODES = [\n  \"shared\",\n  \"combined\",\n  \"per_tag\",\n  \"all_combinations\",\n  \"per_source\",\n] as const;\n\n/**\n * Validate `observationScopes`, falling back to the default on anything unrecognized.\n *\n * A typo here would otherwise reach the API as an unknown scoping mode and change how a whole\n * bank's observations are grouped, so an unusable value takes the default rather than travelling.\n * An empty list is unusable too, and specifically so: `[]` declares ZERO scopes, which the server\n * reads as \"no spec\" and silently treats as `combined` — the opposite of what writing this field\n * at all was meant to express.\n */\nfunction resolveObservationScopes(raw: RawConfig[\"observationScopes\"]): ObservationScopes {\n  // Widened deliberately: this arrives from a hand-edited JSON file, so the declared type says what\n  // is meant, not what is there.\n  const value: unknown = raw;\n  if (typeof value === \"string\")\n    return (OBSERVATION_SCOPE_MODES as readonly string[]).includes(value)\n      ? (value as ObservationScopes)\n      : DEFAULT_OBSERVATION_SCOPES;\n  if (Array.isArray(value)) {\n    const scopes = (value as unknown[])\n      .filter((scope): scope is unknown[] => Array.isArray(scope))\n      .map((scope) => scope.filter((t): t is string => typeof t === \"string\" && t.trim() !== \"\"));\n    if (scopes.length) return scopes;\n  }\n  return DEFAULT_OBSERVATION_SCOPES;\n}\n\n/**\n * Validate `defaultBankConfig`: an object, minus the fields the plugin governs itself.\n *\n * Same shape rule as `recallOptions` — an array would spread into numeric keys and reach the\n * import as garbage, so anything but a plain object contributes nothing. A governed key is dropped\n * here, with a warning naming the setting that owns it, rather than silently in the manifest: a\n * user who wrote `retain_strategies` there would otherwise watch it do nothing every session.\n */\nfunction resolveDefaultBankConfig(raw: RawConfig[\"defaultBankConfig\"]): Record<string, unknown> {\n  const value: unknown = raw;\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) return {};\n  const out: Record<string, unknown> = {};\n  for (const [key, v] of Object.entries(value as Record<string, unknown>)) {\n    if (PLUGIN_GOVERNED_BANK_FIELDS.includes(key)) {\n      log.warn(\n        \"config\",\n        `ignoring defaultBankConfig.${key} — the plugin manages this field itself` +\n          (key === \"retain_extraction_mode\" ? \" (set retainExtractionMode instead)\" : \"\")\n      );\n      continue;\n    }\n    out[key] = v;\n  }\n  return out;\n}\n\n/** Apply defaults to a raw (file) config. Pure — the single place the defaults live. */\nexport type AutoInject = \"reflect\" | \"pages\" | \"recall\" | \"none\";\nconst AUTO_INJECT_MODES: readonly AutoInject[] = [\"reflect\", \"pages\", \"recall\", \"none\"];\n\n/** `autoInject` wins; otherwise the deprecated `autoReflect: false` means \"none\". */\nfunction resolveAutoInject(raw: RawConfig): AutoInject {\n  if (raw.autoReflect !== undefined) {\n    const replacement = raw.autoReflect === false ? \"none\" : \"reflect\";\n    log.warn(\"config\", `autoReflect is deprecated — use autoInject: \"${replacement}\" instead`);\n  }\n  if (AUTO_INJECT_MODES.includes(raw.autoInject as AutoInject)) return raw.autoInject as AutoInject;\n  return raw.autoReflect === false ? \"none\" : \"reflect\";\n}\n\nexport function resolveConfig(raw: RawConfig = {}): Config {\n  const serverMode = [\"cloud\", \"self-hosted\", \"daemon\"].includes(raw.serverMode as string)\n    ? (raw.serverMode as \"cloud\" | \"self-hosted\" | \"daemon\")\n    : \"cloud\";\n  const apiPort = raw.apiPort || DEFAULT_DAEMON_PORT;\n  const pageTrigger = resolvePageTrigger(raw);\n  return {\n    serverMode,\n    // Daemon mode resolves the URL HERE rather than at each call site: every entry point already\n    // builds its client from cfg.apiUrl, so collapsing the mode into that one field means the\n    // daemon needs no plumbing through eight separate constructors.\n    apiUrl:\n      serverMode === \"daemon\"\n        ? `http://127.0.0.1:${apiPort}`\n        : (raw.apiUrl ?? \"https://api.hindsight.vectorize.io\"),\n    apiToken: raw.apiToken || undefined,\n    apiPort,\n    daemonIdleTimeout: raw.daemonIdleTimeout,\n    daemonProfile: raw.daemonProfile || DEFAULT_DAEMON_PROFILE,\n    embedVersion: raw.embedVersion || undefined,\n    embedPackagePath: raw.embedPackagePath || undefined,\n    bankId: raw.bankId,\n    dynamicBankId: raw.dynamicBankId,\n    bankIdTemplate: raw.bankIdTemplate,\n    mapPathToBank: raw.mapPathToBank,\n    resolveWorktrees: raw.resolveWorktrees,\n    optInOnly: raw.optInOnly ?? false,\n    // Same shape as retainTags: a config typo must not become a path that silently approves nothing.\n    optInPaths: Array.isArray(raw.optInPaths)\n      ? raw.optInPaths.filter((p): p is string => typeof p === \"string\" && p.trim() !== \"\")\n      : [],\n    harness: raw.harness ?? \"opencode\",\n    disabled: raw.disabled ?? false,\n    retainSessions: raw.retainSessions ?? true, // write sessions back by default, every harness\n    manageBankConfig: raw.manageBankConfig ?? true,\n    retainExtractionMode: RETAIN_EXTRACTION_MODES.includes(raw.retainExtractionMode!)\n      ? raw.retainExtractionMode!\n      : DEFAULT_RETAIN_EXTRACTION_MODE,\n    defaultBankConfig: resolveDefaultBankConfig(raw.defaultBankConfig),\n    maxParallelRetains: raw.maxParallelRetains || 10,\n    reflectTimeoutMs: raw.reflectTimeoutMs || DEFAULT_REFLECT_TIMEOUT_MS,\n    // Inherit an explicitly-raised reflectTimeoutMs (that is what users reaching for a longer\n    // reflect already set), but never let it LOWER the tool below the default — a short window is\n    // set to bound the automatic hook, not to cut off a call the agent is waiting on.\n    reflectToolTimeoutMs:\n      raw.reflectToolTimeoutMs ||\n      Math.max(raw.reflectTimeoutMs || 0, DEFAULT_REFLECT_TOOL_TIMEOUT_MS),\n    injectTimeoutMs: raw.injectTimeoutMs || DEFAULT_INJECT_TIMEOUT_MS,\n    reflectBudget: resolveReflectBudget(raw),\n    autoInject: resolveAutoInject(raw),\n    pageSearchLimit: raw.pageSearchLimit || DEFAULT_PAGE_SEARCH_LIMIT,\n    // Same shape as retainMetadata: an object, or nothing. An array would spread into numeric\n    // keys and reach the API as garbage, so it is rejected like any other non-object.\n    recallOptions:\n      raw.recallOptions &&\n      typeof raw.recallOptions === \"object\" &&\n      !Array.isArray(raw.recallOptions)\n        ? { ...raw.recallOptions }\n        : {},\n    toolGuideExtra:\n      typeof raw.toolGuideExtra === \"string\" && raw.toolGuideExtra.trim()\n        ? raw.toolGuideExtra\n        : undefined,\n    // Every turn, not every tenth. The guide is what tells the agent WHEN to reach for memory, and\n    // at a cadence of 10 a normal session is told once, on turn 1, and never again. Measured over\n    // 40 real Claude Code turns, moving this from 10 to 1 took searches from 15% of turns to 32.5%\n    // with no wording change at all. The cost is the guide's ~2KB re-sent per turn, which caches.\n    pageRefreshEveryTurns: raw.pageRefreshEveryTurns || 1,\n    pageTriggerType: pageTrigger.type,\n    pageTriggerCron: pageTrigger.cron,\n    pages: resolvePages(raw.pages),\n    customPages: resolveCustomPages(raw.customPages),\n    autoSeed: raw.autoSeed ?? true,\n    seedLimit: raw.seedLimit || DEFAULT_SEED_LIMIT,\n    codebaseSurvey: raw.codebaseSurvey ?? true,\n    surveyModel: raw.surveyModel || \"haiku\",\n    surveyBudgetUsd: raw.surveyBudgetUsd || 2,\n    surveyRefreshCommits: raw.surveyRefreshCommits ?? 20,\n    gitIngest: [\"message\", \"full\", \"none\"].includes(raw.gitIngest as string)\n      ? (raw.gitIngest as \"message\" | \"full\" | \"none\")\n      : \"message\",\n    // Hostile input is a config typo, not an attack: keep only string entries so a stray number or\n    // nested object cannot reach the API as a tag and fail the whole retain.\n    retainTags: Array.isArray(raw.retainTags